insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (226, 21, 1, 15, 'سورة الأنبياء ١ – ١٥', '«اقترب للناس حسابهم وهم في غفلة معرضون»، و«لقد أنزلنا إليكم كتاباً فيه ذكركم»، و«وكم قصمنا من قرية كانت ظالمة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 226) = $j$[{"lbl": "الآيات ١ – ٦", "q": "ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ ﴿١﴾ مَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ ﴿٢﴾ لَاهِيَةٗ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ ظَلَمُواْ هَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ ﴿٣﴾ قَالَ رَبِّي يَعۡلَمُ ٱلۡقَوۡلَ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٤﴾ بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرٞ فَلۡيَأۡتِنَا بِـَٔايَةٖ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ ﴿٥﴾ مَآ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَآۖ أَفَهُمۡ يُؤۡمِنُونَ ﴿٦﴾", "w": [["اقترب للناس حسابهم", "قرب زمن حسابهم، وهو يوم القيامة."], ["وهم في غفلة", "عما هم صائرون إليه."], ["معرضون", "عن التأهّب ليوم الحساب بصالح الأعمال بعد ترك الشرك والمعاصي."], ["من ذكر من ربهم محدث", "من قرآن نازل من ربهم جديد النزول."], ["وهم يلعبون", "ساخرين مستهزئين."], ["لاهية قلوبهم", "مشغولة عنه بما لا يغني من الباطل والشر."], ["وأسرّوا النجوى", "أخفوا مناجاتهم بينهم."], ["أضغاث أحلام", "أخلاط رآها في المنام."], ["بل افتراه", "اختلقه وكذبه ولم يوح إليه."], ["أفهم يؤمنون", "لا يؤمنون، فالاستفهام للنفي."]], "m": "يخبر تعالى وقوله الحق: دنا وقت حساب الناس على أعمالهم وهم في غفلة عما ينتظرهم، معرضون عن التأهّب له بترك الشرك والتزوّد بالإيمان وصالح الأعمال. ما ينزل الله من قرآن يعظهم به إلا استمعوه وهم هازئون لاعبون غير متدبّرين، قلوبهم مشغولة عنه منصرفة عما تحمل الآيات من هدى ونور. وأسرّ الظالمون مناجاتهم: هل هذا إلا بشر مثلكم، فكيف تتابعونه؟ إن هو إلا ساحر، أفتأتون السحر وأنتم تبصرون؟ قل: ربي يعلم القول في السماء والأرض، وهو السميع لأقوالكم العليم بصدقي. بل قالوا في القرآن: أخلاط رؤيا منامية، بل اختلقه، بل هو شاعر، ينتقلون من قول إلى آخر لحيرتهم، فليأتنا بمعجزة كما أُرسل الأولون كناقة صالح وعصا موسى. قال تعالى: ما آمنت قبلهم من قرية أهلكناها لما جاءتها الآية فكذّبت، أفهم يؤمنون؟ لا، فشأنهم شأن غيرهم، فلا معنى لإعطائهم الآية ونحن نعلم أنهم لا يؤمنون.", "h": ["قرب الساعة.", "بيان ما كان عليه المشركون من غفلة ولهو وإعراض، والناس اليوم أكثر منهم في ذلك.", "بيان حيرة المشركين إزاء الوحي الإلهي والنبي ﷺ.", "المعجزات لم تكن يوماً سبباً في هداية الناس، بل كانت سبب إهلاكهم، إذ هذا طبع الإنسان إذا لم يرد الإيمان والهداية فإنه لا يهتدي ولو جاءته كل آية."], "k": "«اقترب للناس حسابهم وهم في غفلة معرضون»… كم من يومي مرّ في غفلة عن هذا الحساب؟"}, {"lbl": "الآيات ٧ – ١٠", "q": "وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ﴿٧﴾ وَمَا جَعَلۡنَٰهُمۡ جَسَدٗا لَّا يَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُواْ خَٰلِدِينَ ﴿٨﴾ ثُمَّ صَدَقۡنَٰهُمُ ٱلۡوَعۡدَ فَأَنجَيۡنَٰهُمۡ وَمَن نَّشَآءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِينَ ﴿٩﴾ لَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبٗا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ ﴿١٠﴾", "w": [["قبلك", "يا محمد."], ["أهل الذكر", "أهل الكتاب الأول."], ["جسداً لا يأكلون الطعام", "أجساداً لا تأكل الطعام، بل جعلناهم أجساداً آدمية تفتقر إلى الطعام والشراب."], ["الوعد", "الذي واعدناهم."], ["المسرفين", "في الظلم والشرك والمعاصي."], ["كتاباً", "هو القرآن العظيم."], ["فيه ذكركم", "ما تذكرون به ربكم، وما تُذكرون به من الشرف بين الناس."]], "m": "كانت اعتراضات قريش تدور حول: لِمَ يكون الرسول بشراً يأكل الطعام؟ لِمَ لا يكون له كنز أو جنة؟ لِمَ لا يأتينا بآية كما أُرسل الأولون؟ قال قتادة: قال أهل مكة: حوّل لنا الصفا ذهباً، فأتاه جبريل فقال: إن شئت كان الذي سألك قومك، ولكنه إن كان ثم لم يؤمنوا لم يُنظروا، وإن شئت استأنيت بقومك، قال: «بل أستأني بقومي». وما أرسلنا قبلك إلا رجالاً نوحي إليهم، فليسأل قومك أهل الكتاب من أحبار اليهود ورهبان النصارى إن كانوا لا يعلمون، فإنهم يعلمون أن الرسل كانوا بشراً. وما جعلناهم أجساداً لا تأكل الطعام، فلِمَ يعترضون على رسول يأكل الطعام ويمشي في الأسواق؟ ثم صدقناهم الوعد: إذا أُعطي أقوامهم ما طلبوا ثم كذّبوا أهلكناهم، فأنجيناهم ومن آمن بهم، وأهلكنا المسرفين في الكفر والعناد. لقد أنزلنا إليكم كتاباً عظيم الشأن، فيه ما تتذكّرون به فتهتدون، وفيه ذكركم وشرفكم بين الأمم لأنه نزل بلغتكم والناس لكم فيه تبع، أفلا تعقلون ما هو خير لكم؟", "h": ["تقرير مبدأ أن الرسل لا يكونون إلا بشراً ذكوراً لا إناثاً.", "تعيّن سؤال أهل العلم في كل ما لا يُعلم إلا من طريقهم من أمور الدين والآخرة.", "ذم الإسراف في كل شيء، وهو كالغلوّ في الشرك والظلم.", "القرآن ذكر يُذكر به الله تعالى لما فيه من دلائل التوحيد، وموعظة لما فيه من قصص الأولين، وشرف أي شرف لمن آمن به وعمل بما فيه من شرائع وآداب وأخلاق."], "k": "«لقد أنزلنا إليكم كتاباً فيه ذكركم»… شرفي في هذا الكتاب؛ فهل أعطيه من وقتي ما يليق به؟"}, {"lbl": "الآيات ١١ – ١٥", "q": "وَكَمۡ قَصَمۡنَا مِن قَرۡيَةٖ كَانَتۡ ظَالِمَةٗ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِينَ ﴿١١﴾ فَلَمَّآ أَحَسُّواْ بَأۡسَنَآ إِذَا هُم مِّنۡهَا يَرۡكُضُونَ ﴿١٢﴾ لَا تَرۡكُضُواْ وَٱرۡجِعُوٓاْ إِلَىٰ مَآ أُتۡرِفۡتُمۡ فِيهِ وَمَسَٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ ﴿١٣﴾ قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ ﴿١٤﴾ فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَٰهُمۡ حَصِيدًا خَٰمِدِينَ ﴿١٥﴾", "w": [["وكم قصمنا", "كثيراً من أهل القرى قصمناهم بإهلاكهم وتفتيت أجسامهم."], ["كانت ظالمة", "كان أهلها ظالمين."], ["يركضون", "فارّين هاربين."], ["إلى ما أُترفتم فيه", "من وافر الطعام والشراب والمسكن والمركب."], ["تُسألون", "عن شيء من دنياكم على عادتكم."], ["تلك دعواهم", "دعوتهم التي يردّدونها، وهي: يا ويلنا إنا كنا ظالمين."], ["حصيداً خامدين", "لم يبق منهم قائم، فهم كالزرع المحصود، خامدين لا حراك لهم كالنار إذا أُخمدت."]], "m": "يقول تعالى منذراً قريشاً أن يحلّ بها ما حلّ بغيرها: وكثيراً أهلكنا إبادة كاملة من أهل قرى كانوا ظالمين بالشرك والمعاصي والعناد، وأنشأنا بعدها قوماً آخرين خيراً منهم. فلما أحسّوا بأسنا بأسماعهم وأبصارهم إذا هم من قريتهم يركضون هاربين من الموت، والملائكة تقول لهم توبيخاً: لا تركضوا، وارجعوا إلى ما نُعّمتم فيه من الطعام والشراب والمسكن والمركب لعلكم تُسألون على العادة عن شيء من أمور دنياكم. فكان جوابهم: يا ويلنا إنا كنا ظالمين أنفسنا بالشرك والتكذيب، فما زالوا يردّدون ذلك حتى جعلناهم مجتثّين من أصولهم ساقطين في الأرض خامدين لا حراك لهم.", "h": ["التنديد بالظلم، وأعلى درجاته الشرك بالله.", "جواز الاستهزاء بالمشرك الظالم إذا حلّ به العذاب تقريعاً له وتوبيخاً.", "لا تنفع التوبة عند معاينة العذاب لو طلبها الهالكون.", "شدة الهول ورؤية العذاب قد تفقد صاحبها رشده وصوابه فيهذي ولا يدري ما يقول."], "k": "«فما زالت تلك دعواهم»… اعترفوا حين لا ينفع الاعتراف؛ فهل أعترف بذنبي الآن وهو ينفع؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 226;
insert into public.tdb_cards(topic, i, body) select 226, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ ﴿١﴾ مَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ ﴿٢﴾ لَاهِيَةٗ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ ظَلَمُواْ هَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ ﴿٣﴾ قَالَ رَبِّي يَعۡلَمُ ٱلۡقَوۡلَ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٤﴾ بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرٞ فَلۡيَأۡتِنَا بِـَٔايَةٖ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ ﴿٥﴾ مَآ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَآۖ أَفَهُمۡ يُؤۡمِنُونَ ﴿٦﴾", "w": [["اقترب للناس حسابهم", "قرب زمن حسابهم، وهو يوم القيامة."], ["وهم في غفلة", "عما هم صائرون إليه."], ["معرضون", "عن التأهّب ليوم الحساب بصالح الأعمال بعد ترك الشرك والمعاصي."], ["من ذكر من ربهم محدث", "من قرآن نازل من ربهم جديد النزول."], ["وهم يلعبون", "ساخرين مستهزئين."], ["لاهية قلوبهم", "مشغولة عنه بما لا يغني من الباطل والشر."], ["وأسرّوا النجوى", "أخفوا مناجاتهم بينهم."], ["أضغاث أحلام", "أخلاط رآها في المنام."], ["بل افتراه", "اختلقه وكذبه ولم يوح إليه."], ["أفهم يؤمنون", "لا يؤمنون، فالاستفهام للنفي."]], "m": "يخبر تعالى وقوله الحق: دنا وقت حساب الناس على أعمالهم وهم في غفلة عما ينتظرهم، معرضون عن التأهّب له بترك الشرك والتزوّد بالإيمان وصالح الأعمال. ما ينزل الله من قرآن يعظهم به إلا استمعوه وهم هازئون لاعبون غير متدبّرين، قلوبهم مشغولة عنه منصرفة عما تحمل الآيات من هدى ونور. وأسرّ الظالمون مناجاتهم: هل هذا إلا بشر مثلكم، فكيف تتابعونه؟ إن هو إلا ساحر، أفتأتون السحر وأنتم تبصرون؟ قل: ربي يعلم القول في السماء والأرض، وهو السميع لأقوالكم العليم بصدقي. بل قالوا في القرآن: أخلاط رؤيا منامية، بل اختلقه، بل هو شاعر، ينتقلون من قول إلى آخر لحيرتهم، فليأتنا بمعجزة كما أُرسل الأولون كناقة صالح وعصا موسى. قال تعالى: ما آمنت قبلهم من قرية أهلكناها لما جاءتها الآية فكذّبت، أفهم يؤمنون؟ لا، فشأنهم شأن غيرهم، فلا معنى لإعطائهم الآية ونحن نعلم أنهم لا يؤمنون.", "h": ["قرب الساعة.", "بيان ما كان عليه المشركون من غفلة ولهو وإعراض، والناس اليوم أكثر منهم في ذلك.", "بيان حيرة المشركين إزاء الوحي الإلهي والنبي ﷺ.", "المعجزات لم تكن يوماً سبباً في هداية الناس، بل كانت سبب إهلاكهم، إذ هذا طبع الإنسان إذا لم يرد الإيمان والهداية فإنه لا يهتدي ولو جاءته كل آية."], "k": "«اقترب للناس حسابهم وهم في غفلة معرضون»… كم من يومي مرّ في غفلة عن هذا الحساب؟"}, {"lbl": "الآيات ٧ – ١٠", "q": "وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ﴿٧﴾ وَمَا جَعَلۡنَٰهُمۡ جَسَدٗا لَّا يَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُواْ خَٰلِدِينَ ﴿٨﴾ ثُمَّ صَدَقۡنَٰهُمُ ٱلۡوَعۡدَ فَأَنجَيۡنَٰهُمۡ وَمَن نَّشَآءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِينَ ﴿٩﴾ لَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبٗا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ ﴿١٠﴾", "w": [["قبلك", "يا محمد."], ["أهل الذكر", "أهل الكتاب الأول."], ["جسداً لا يأكلون الطعام", "أجساداً لا تأكل الطعام، بل جعلناهم أجساداً آدمية تفتقر إلى الطعام والشراب."], ["الوعد", "الذي واعدناهم."], ["المسرفين", "في الظلم والشرك والمعاصي."], ["كتاباً", "هو القرآن العظيم."], ["فيه ذكركم", "ما تذكرون به ربكم، وما تُذكرون به من الشرف بين الناس."]], "m": "كانت اعتراضات قريش تدور حول: لِمَ يكون الرسول بشراً يأكل الطعام؟ لِمَ لا يكون له كنز أو جنة؟ لِمَ لا يأتينا بآية كما أُرسل الأولون؟ قال قتادة: قال أهل مكة: حوّل لنا الصفا ذهباً، فأتاه جبريل فقال: إن شئت كان الذي سألك قومك، ولكنه إن كان ثم لم يؤمنوا لم يُنظروا، وإن شئت استأنيت بقومك، قال: «بل أستأني بقومي». وما أرسلنا قبلك إلا رجالاً نوحي إليهم، فليسأل قومك أهل الكتاب من أحبار اليهود ورهبان النصارى إن كانوا لا يعلمون، فإنهم يعلمون أن الرسل كانوا بشراً. وما جعلناهم أجساداً لا تأكل الطعام، فلِمَ يعترضون على رسول يأكل الطعام ويمشي في الأسواق؟ ثم صدقناهم الوعد: إذا أُعطي أقوامهم ما طلبوا ثم كذّبوا أهلكناهم، فأنجيناهم ومن آمن بهم، وأهلكنا المسرفين في الكفر والعناد. لقد أنزلنا إليكم كتاباً عظيم الشأن، فيه ما تتذكّرون به فتهتدون، وفيه ذكركم وشرفكم بين الأمم لأنه نزل بلغتكم والناس لكم فيه تبع، أفلا تعقلون ما هو خير لكم؟", "h": ["تقرير مبدأ أن الرسل لا يكونون إلا بشراً ذكوراً لا إناثاً.", "تعيّن سؤال أهل العلم في كل ما لا يُعلم إلا من طريقهم من أمور الدين والآخرة.", "ذم الإسراف في كل شيء، وهو كالغلوّ في الشرك والظلم.", "القرآن ذكر يُذكر به الله تعالى لما فيه من دلائل التوحيد، وموعظة لما فيه من قصص الأولين، وشرف أي شرف لمن آمن به وعمل بما فيه من شرائع وآداب وأخلاق."], "k": "«لقد أنزلنا إليكم كتاباً فيه ذكركم»… شرفي في هذا الكتاب؛ فهل أعطيه من وقتي ما يليق به؟"}, {"lbl": "الآيات ١١ – ١٥", "q": "وَكَمۡ قَصَمۡنَا مِن قَرۡيَةٖ كَانَتۡ ظَالِمَةٗ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِينَ ﴿١١﴾ فَلَمَّآ أَحَسُّواْ بَأۡسَنَآ إِذَا هُم مِّنۡهَا يَرۡكُضُونَ ﴿١٢﴾ لَا تَرۡكُضُواْ وَٱرۡجِعُوٓاْ إِلَىٰ مَآ أُتۡرِفۡتُمۡ فِيهِ وَمَسَٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ ﴿١٣﴾ قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ ﴿١٤﴾ فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَٰهُمۡ حَصِيدًا خَٰمِدِينَ ﴿١٥﴾", "w": [["وكم قصمنا", "كثيراً من أهل القرى قصمناهم بإهلاكهم وتفتيت أجسامهم."], ["كانت ظالمة", "كان أهلها ظالمين."], ["يركضون", "فارّين هاربين."], ["إلى ما أُترفتم فيه", "من وافر الطعام والشراب والمسكن والمركب."], ["تُسألون", "عن شيء من دنياكم على عادتكم."], ["تلك دعواهم", "دعوتهم التي يردّدونها، وهي: يا ويلنا إنا كنا ظالمين."], ["حصيداً خامدين", "لم يبق منهم قائم، فهم كالزرع المحصود، خامدين لا حراك لهم كالنار إذا أُخمدت."]], "m": "يقول تعالى منذراً قريشاً أن يحلّ بها ما حلّ بغيرها: وكثيراً أهلكنا إبادة كاملة من أهل قرى كانوا ظالمين بالشرك والمعاصي والعناد، وأنشأنا بعدها قوماً آخرين خيراً منهم. فلما أحسّوا بأسنا بأسماعهم وأبصارهم إذا هم من قريتهم يركضون هاربين من الموت، والملائكة تقول لهم توبيخاً: لا تركضوا، وارجعوا إلى ما نُعّمتم فيه من الطعام والشراب والمسكن والمركب لعلكم تُسألون على العادة عن شيء من أمور دنياكم. فكان جوابهم: يا ويلنا إنا كنا ظالمين أنفسنا بالشرك والتكذيب، فما زالوا يردّدون ذلك حتى جعلناهم مجتثّين من أصولهم ساقطين في الأرض خامدين لا حراك لهم.", "h": ["التنديد بالظلم، وأعلى درجاته الشرك بالله.", "جواز الاستهزاء بالمشرك الظالم إذا حلّ به العذاب تقريعاً له وتوبيخاً.", "لا تنفع التوبة عند معاينة العذاب لو طلبها الهالكون.", "شدة الهول ورؤية العذاب قد تفقد صاحبها رشده وصوابه فيهذي ولا يدري ما يقول."], "k": "«فما زالت تلك دعواهم»… اعترفوا حين لا ينفع الاعتراف؛ فهل أعترف بذنبي الآن وهو ينفع؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (227, 21, 16, 29, 'سورة الأنبياء ١٦ – ٢٩', '«وما خلقنا السماء والأرض وما بينهما لاعبين»، و«لو كان فيهما آلهة إلا الله لفسدتا»، و«بل عباد مكرمون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 227) = $j$[{"lbl": "الآيات ١٦ – ٢٠", "q": "وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ ﴿١٦﴾ لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ لَهۡوٗا لَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ ﴿١٧﴾ بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ ﴿١٨﴾ وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ ﴿١٩﴾ يُسَبِّحُونَ ٱلَّيۡلَ وَٱلنَّهَارَ لَا يَفۡتُرُونَ ﴿٢٠﴾", "w": [["لاعبين", "عابثين لا مقصد حسن لنا في ذلك."], ["لهواً", "زوجة وولداً."], ["من لدنّا", "من عندنا من الحور العين أو الملائكة."], ["بل نقذف بالحق", "نرمي بالحق على الباطل."], ["فيدمغه", "يشجّ رأسه حتى تبلغ الشجّة دماغه فيهلك."], ["فإذا هو زاهق", "ذاهب مضمحلّ."], ["ولكم الويل مما تصفون", "لكم العذاب الشديد من أجل وصفكم الكاذب الله بأن له زوجة وولداً، والرسول بأنه ساحر ومفترٍ."], ["وله من في السماوات والأرض", "خلقاً وملكاً وتدبيراً لا شريك له في ذلك."], ["ولا يستحسرون", "لا يعيون ولا يتعبون فيتركون التسبيح."], ["لا يفترون", "عن التسبيح، لأنه منهم كالنفَس منا."]], "m": "إهلاكه تعالى الأمم الظالمة دليل أنه لم يخلق الإنسان والحياة عبثاً، بل ليُذكر ويُشكر: وما خلقنا السماء والأرض وما بينهما عابثين، بل بالحق، وهو وجوب عبادتنا بالذكر والشكر. لو أردنا أن نتخذ صاحبة أو ولداً، كما يقول المبطلون من العرب: أصهر الله إلى الجن فأنجب الملائكة، وكما يقول ضلّال النصارى في مريم وعيسى، لاتخذناه من عندنا من الحور العين والملائكة، ولكنا لم نرد ذلك ولا ينبغي لنا، إذ كل من في السماوات والأرض عبيد لنا، فكيف نتخذ مملوكاً ولداً ومملوكة زوجة، والناس لا يجعلون عبدهم ولداً؟ بل نرمي بحجج القرآن على هذه الأباطيل فتدمغها فإذا هي ذاهبة، ولكم العذاب أيها الكاذبون مما تصفون. وله من في السماوات والأرض ملكاً وتصرّفاً، فهو غني عن الصاحبة والولد، ومن عنده من الملائكة، وهم لا يُحصون، لا يستكبرون عن عبادته ولا يتعبون منها، يسبّحون الليل والنهار لا يفترون، كالآدميين في تنفّسهم وطرف أعينهم، لا يشغلهم عنه شاغل ولا يسأمون منه.", "h": ["تنزّه الرب تعالى عن اللهو واللعب والصاحبة والولد.", "حجج القرآن هي الحق، متى رمى بها الباطل دمغته فذهب واضمحل.", "إقامة البراهين العقلية على إبطال الباطل أمر محمود، وقد يكون لا بد منه.", "بيان غنى الله المطلق عن كل مخلوقاته.", "بيان حال الملائكة في عبادتهم وتسبيحهم لله تعالى."], "k": "«يسبّحون الليل والنهار لا يفترون»… الملائكة لا تملّ؛ فكم أعطي التسبيح من يومي؟"}, {"lbl": "الآيات ٢١ – ٢٥", "q": "أَمِ ٱتَّخَذُوٓاْ ءَالِهَةٗ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ ﴿٢١﴾ لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ ﴿٢٢﴾ لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ ﴿٢٣﴾ أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ وَذِكۡرُ مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ ﴿٢٤﴾ وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ ﴿٢٥﴾", "w": [["أم اتخذوا آلهة من الأرض", "من أحجارها ومعادنها كالذهب والفضة والنحاس والحجر."], ["هم ينشرون", "يحيون الأموات، إذ لا يكون إلهاً حقاً إلا من يحيي الموتى."], ["لو كان فيهما", "في السماوات والأرض."], ["لفسدتا", "لأن تعدّد الآلهة يقتضي التنازع عادة."], ["فسبحان الله", "تنزيه لله عما لا يليق بجلاله وكماله."], ["رب العرش", "خالقه ومالكه والمختص به."], ["عما يصفون", "من صفات النقص كالزوجة والولد والشريك."], ["لا يُسأل عما يفعل", "إذ هو الملك المتصرّف، وغيره يُسأل عن فعله لعجزه وجهله."], ["قل هاتوا برهانكم", "على ما اتخذتم من دونه من آلهة، ولا برهان لهم."], ["هذا ذكر من معي", "القرآن، ذكر أمتي."], ["وذكر من قبلي", "التوراة والإنجيل وغيرهما من كتب الله، الكل يشهد أنه لا إله إلا الله."], ["فاعبدون", "وحّدوني في العبادة فلا تعبدوا معي غيري."]], "m": "يوبّخ تعالى المشركين: أم اتخذوا من أحجار الأرض ومعادنها آلهة هم يحيون الموتى؟ كلا، والذي لا يحيي الموتى لا يستحق الألوهية. لو كان في السماوات والأرض آلهة غير الله لفسدتا، لأن تعدّد الآلهة يقتضي التنازع، هذا يريد أن يخلق كذا والآخر لا يريده، فيختل نظام الحياة، فانتظامها هذه القرون دالّ على وحدة الخالق الذي تجب له العبادة وحده، فسبحان الله رب العرش عما يصفون من الشريك والولد. لا يُسأل عما يفعل لعلمه وقدرته وملكه، وهم يُسألون ويحاسَبون، فكيف يكونون آلهة؟ أم اتخذوا من دونه آلهة؟ قل: هاتوا برهانكم، ومن أين لهم البرهان؟ هذا القرآن ذكر من معي، وذكر من قبلي التوراة والإنجيل، هل في واحد منها ما يثبت إلهاً مع الله؟ لا. بل أكثرهم لا يعلمون الحق فهم معرضون لجهلهم. وما أرسلنا من قبلك من رسول إلا نوحي إليه: أنه لا إله إلا أنا فاعبدون، فلو كان المشركون يعلمون هذا لما أشركوا.", "h": ["من أخص صفات الإله أن يخلق ويرزق ويحيي ويميت.", "وحدة النظام دالة على وحدة المنظِّم، ووحدة الوجود دالة على وحدة الموجِد، وهذا برهان التمانع الذي يقرّر منطقياً وجود الله ووجوب عبادته وحده.", "لا برهان على الشرك أبداً، ولا يصح في الذهن وجود دليل على صحة عبادة غير الله.", "القرآن والتوراة وكل كتب الله متضافرة على تقرير توحيد الله تعالى.", "تقرير توحيد الله تعالى وإبطال الشرك والتنديد بالمشركين."], "k": "«لا يُسأل عما يفعل وهم يُسألون»… أُسلّم لحكمه فيما لا أفهم، وأستعد لسؤاله فيما أفعل."}, {"lbl": "الآيات ٢٦ – ٢٩", "q": "وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗاۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادٞ مُّكۡرَمُونَ ﴿٢٦﴾ لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ يَعۡمَلُونَ ﴿٢٧﴾ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡيَتِهِۦ مُشۡفِقُونَ ﴿٢٨﴾ ۞وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ ﴿٢٩﴾", "w": [["ولداً", "من الملائكة، حيث قالوا: الملائكة بنات الله، تعالى الله عن ذلك."], ["سبحانه", "تنزيه له تعالى عن اتخاذ الولد."], ["بل عباد مكرمون", "هم الملائكة، ومن كان عبداً لا يكون ابناً ولا بنتاً."], ["لا يسبقونه بالقول", "لا يقولون حتى يقول هو، وهذا شأن العبد لا يتقدّم سيده."], ["وهم بأمره يعملون", "مطيعون متأدّبون لا يعملون إلا بإذنه."], ["ولا يشفعون إلا لمن ارتضى", "إلا لمن رضي تعالى أن يُشفع له."], ["من دونه", "من دون الله."], ["كذلك نجزي الظالمين", "لأنفسهم بالشرك والمعاصي."]], "m": "بعد إبطال الشرك أبطل قولهم: اتخذ الرحمن ولداً، وهو زعمهم أن الملائكة بنات الله، فنزّه نفسه: سبحانه، بل هم عباد مكرمون عنده، لا يقولون حتى يقول هو لكمال عبوديتهم، ولا يعملون إلا بإذنه، يعلم ما بين أيديهم وما خلفهم فعلمه محيط بهم، ولا يشفعون لأحد إلا لمن ارتضى أن يُشفع له، وهم من خشيته خائفون. ومن يقل منهم: إني إله من دون الله، فذلك نجزيه جهنم، كذلك نجزي الظالمين أنفسهم بالشرك والمعاصي. وبهذا بطلت فرية المشركين في جعلهم الملائكة بنات لله وعبادتهم ليشفعوا لهم.", "h": ["إبطال نسبة الولد إلى الله تعالى من قبل المشركين، وكذا اليهود والنصارى.", "بيان كمال عبودية الملائكة لله تعالى وكمال أدبهم وطاعتهم لربهم سبحانه.", "بطلان دعوى المشركين في شفاعة الملائكة لهم، إذ الملائكة لا يشفعون إلا لمن رضي الله تعالى أن يشفعوا له.", "تقرير وجود شفاعة يوم القيامة، ولكن بشروطها، وهي أن يكون الشافع قد أُذن له بالشفاعة، وأن يكون المشفوع له من أهل التوحيد، فأهل الشرك لا تنفعهم شفاعة."], "k": "«وهم من خشيته مشفقون»… الملائكة المكرمون خائفون؛ فما بال قلبي آمناً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 227;
insert into public.tdb_cards(topic, i, body) select 227, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٦ – ٢٠", "q": "وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ ﴿١٦﴾ لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ لَهۡوٗا لَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ ﴿١٧﴾ بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ ﴿١٨﴾ وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ ﴿١٩﴾ يُسَبِّحُونَ ٱلَّيۡلَ وَٱلنَّهَارَ لَا يَفۡتُرُونَ ﴿٢٠﴾", "w": [["لاعبين", "عابثين لا مقصد حسن لنا في ذلك."], ["لهواً", "زوجة وولداً."], ["من لدنّا", "من عندنا من الحور العين أو الملائكة."], ["بل نقذف بالحق", "نرمي بالحق على الباطل."], ["فيدمغه", "يشجّ رأسه حتى تبلغ الشجّة دماغه فيهلك."], ["فإذا هو زاهق", "ذاهب مضمحلّ."], ["ولكم الويل مما تصفون", "لكم العذاب الشديد من أجل وصفكم الكاذب الله بأن له زوجة وولداً، والرسول بأنه ساحر ومفترٍ."], ["وله من في السماوات والأرض", "خلقاً وملكاً وتدبيراً لا شريك له في ذلك."], ["ولا يستحسرون", "لا يعيون ولا يتعبون فيتركون التسبيح."], ["لا يفترون", "عن التسبيح، لأنه منهم كالنفَس منا."]], "m": "إهلاكه تعالى الأمم الظالمة دليل أنه لم يخلق الإنسان والحياة عبثاً، بل ليُذكر ويُشكر: وما خلقنا السماء والأرض وما بينهما عابثين، بل بالحق، وهو وجوب عبادتنا بالذكر والشكر. لو أردنا أن نتخذ صاحبة أو ولداً، كما يقول المبطلون من العرب: أصهر الله إلى الجن فأنجب الملائكة، وكما يقول ضلّال النصارى في مريم وعيسى، لاتخذناه من عندنا من الحور العين والملائكة، ولكنا لم نرد ذلك ولا ينبغي لنا، إذ كل من في السماوات والأرض عبيد لنا، فكيف نتخذ مملوكاً ولداً ومملوكة زوجة، والناس لا يجعلون عبدهم ولداً؟ بل نرمي بحجج القرآن على هذه الأباطيل فتدمغها فإذا هي ذاهبة، ولكم العذاب أيها الكاذبون مما تصفون. وله من في السماوات والأرض ملكاً وتصرّفاً، فهو غني عن الصاحبة والولد، ومن عنده من الملائكة، وهم لا يُحصون، لا يستكبرون عن عبادته ولا يتعبون منها، يسبّحون الليل والنهار لا يفترون، كالآدميين في تنفّسهم وطرف أعينهم، لا يشغلهم عنه شاغل ولا يسأمون منه.", "h": ["تنزّه الرب تعالى عن اللهو واللعب والصاحبة والولد.", "حجج القرآن هي الحق، متى رمى بها الباطل دمغته فذهب واضمحل.", "إقامة البراهين العقلية على إبطال الباطل أمر محمود، وقد يكون لا بد منه.", "بيان غنى الله المطلق عن كل مخلوقاته.", "بيان حال الملائكة في عبادتهم وتسبيحهم لله تعالى."], "k": "«يسبّحون الليل والنهار لا يفترون»… الملائكة لا تملّ؛ فكم أعطي التسبيح من يومي؟"}, {"lbl": "الآيات ٢١ – ٢٥", "q": "أَمِ ٱتَّخَذُوٓاْ ءَالِهَةٗ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ ﴿٢١﴾ لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ ﴿٢٢﴾ لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ ﴿٢٣﴾ أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ وَذِكۡرُ مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ ﴿٢٤﴾ وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ ﴿٢٥﴾", "w": [["أم اتخذوا آلهة من الأرض", "من أحجارها ومعادنها كالذهب والفضة والنحاس والحجر."], ["هم ينشرون", "يحيون الأموات، إذ لا يكون إلهاً حقاً إلا من يحيي الموتى."], ["لو كان فيهما", "في السماوات والأرض."], ["لفسدتا", "لأن تعدّد الآلهة يقتضي التنازع عادة."], ["فسبحان الله", "تنزيه لله عما لا يليق بجلاله وكماله."], ["رب العرش", "خالقه ومالكه والمختص به."], ["عما يصفون", "من صفات النقص كالزوجة والولد والشريك."], ["لا يُسأل عما يفعل", "إذ هو الملك المتصرّف، وغيره يُسأل عن فعله لعجزه وجهله."], ["قل هاتوا برهانكم", "على ما اتخذتم من دونه من آلهة، ولا برهان لهم."], ["هذا ذكر من معي", "القرآن، ذكر أمتي."], ["وذكر من قبلي", "التوراة والإنجيل وغيرهما من كتب الله، الكل يشهد أنه لا إله إلا الله."], ["فاعبدون", "وحّدوني في العبادة فلا تعبدوا معي غيري."]], "m": "يوبّخ تعالى المشركين: أم اتخذوا من أحجار الأرض ومعادنها آلهة هم يحيون الموتى؟ كلا، والذي لا يحيي الموتى لا يستحق الألوهية. لو كان في السماوات والأرض آلهة غير الله لفسدتا، لأن تعدّد الآلهة يقتضي التنازع، هذا يريد أن يخلق كذا والآخر لا يريده، فيختل نظام الحياة، فانتظامها هذه القرون دالّ على وحدة الخالق الذي تجب له العبادة وحده، فسبحان الله رب العرش عما يصفون من الشريك والولد. لا يُسأل عما يفعل لعلمه وقدرته وملكه، وهم يُسألون ويحاسَبون، فكيف يكونون آلهة؟ أم اتخذوا من دونه آلهة؟ قل: هاتوا برهانكم، ومن أين لهم البرهان؟ هذا القرآن ذكر من معي، وذكر من قبلي التوراة والإنجيل، هل في واحد منها ما يثبت إلهاً مع الله؟ لا. بل أكثرهم لا يعلمون الحق فهم معرضون لجهلهم. وما أرسلنا من قبلك من رسول إلا نوحي إليه: أنه لا إله إلا أنا فاعبدون، فلو كان المشركون يعلمون هذا لما أشركوا.", "h": ["من أخص صفات الإله أن يخلق ويرزق ويحيي ويميت.", "وحدة النظام دالة على وحدة المنظِّم، ووحدة الوجود دالة على وحدة الموجِد، وهذا برهان التمانع الذي يقرّر منطقياً وجود الله ووجوب عبادته وحده.", "لا برهان على الشرك أبداً، ولا يصح في الذهن وجود دليل على صحة عبادة غير الله.", "القرآن والتوراة وكل كتب الله متضافرة على تقرير توحيد الله تعالى.", "تقرير توحيد الله تعالى وإبطال الشرك والتنديد بالمشركين."], "k": "«لا يُسأل عما يفعل وهم يُسألون»… أُسلّم لحكمه فيما لا أفهم، وأستعد لسؤاله فيما أفعل."}, {"lbl": "الآيات ٢٦ – ٢٩", "q": "وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗاۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادٞ مُّكۡرَمُونَ ﴿٢٦﴾ لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ يَعۡمَلُونَ ﴿٢٧﴾ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡيَتِهِۦ مُشۡفِقُونَ ﴿٢٨﴾ ۞وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ ﴿٢٩﴾", "w": [["ولداً", "من الملائكة، حيث قالوا: الملائكة بنات الله، تعالى الله عن ذلك."], ["سبحانه", "تنزيه له تعالى عن اتخاذ الولد."], ["بل عباد مكرمون", "هم الملائكة، ومن كان عبداً لا يكون ابناً ولا بنتاً."], ["لا يسبقونه بالقول", "لا يقولون حتى يقول هو، وهذا شأن العبد لا يتقدّم سيده."], ["وهم بأمره يعملون", "مطيعون متأدّبون لا يعملون إلا بإذنه."], ["ولا يشفعون إلا لمن ارتضى", "إلا لمن رضي تعالى أن يُشفع له."], ["من دونه", "من دون الله."], ["كذلك نجزي الظالمين", "لأنفسهم بالشرك والمعاصي."]], "m": "بعد إبطال الشرك أبطل قولهم: اتخذ الرحمن ولداً، وهو زعمهم أن الملائكة بنات الله، فنزّه نفسه: سبحانه، بل هم عباد مكرمون عنده، لا يقولون حتى يقول هو لكمال عبوديتهم، ولا يعملون إلا بإذنه، يعلم ما بين أيديهم وما خلفهم فعلمه محيط بهم، ولا يشفعون لأحد إلا لمن ارتضى أن يُشفع له، وهم من خشيته خائفون. ومن يقل منهم: إني إله من دون الله، فذلك نجزيه جهنم، كذلك نجزي الظالمين أنفسهم بالشرك والمعاصي. وبهذا بطلت فرية المشركين في جعلهم الملائكة بنات لله وعبادتهم ليشفعوا لهم.", "h": ["إبطال نسبة الولد إلى الله تعالى من قبل المشركين، وكذا اليهود والنصارى.", "بيان كمال عبودية الملائكة لله تعالى وكمال أدبهم وطاعتهم لربهم سبحانه.", "بطلان دعوى المشركين في شفاعة الملائكة لهم، إذ الملائكة لا يشفعون إلا لمن رضي الله تعالى أن يشفعوا له.", "تقرير وجود شفاعة يوم القيامة، ولكن بشروطها، وهي أن يكون الشافع قد أُذن له بالشفاعة، وأن يكون المشفوع له من أهل التوحيد، فأهل الشرك لا تنفعهم شفاعة."], "k": "«وهم من خشيته مشفقون»… الملائكة المكرمون خائفون؛ فما بال قلبي آمناً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (228, 21, 30, 38, 'سورة الأنبياء ٣٠ – ٣٨', '«أن السماوات والأرض كانتا رتقاً ففتقناهما وجعلنا من الماء كل شيء حي»، و«كل نفس ذائقة الموت ونبلوكم بالشر والخير فتنة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 228) = $j$[{"lbl": "الآيات ٣٠ – ٣٣", "q": "أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ ﴿٣٠﴾ وَجَعَلۡنَا فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجٗا سُبُلٗا لَّعَلَّهُمۡ يَهۡتَدُونَ ﴿٣١﴾ وَجَعَلۡنَا ٱلسَّمَآءَ سَقۡفٗا مَّحۡفُوظٗاۖ وَهُمۡ عَنۡ ءَايَٰتِهَا مُعۡرِضُونَ ﴿٣٢﴾ وَهُوَ ٱلَّذِي خَلَقَ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ فِي فَلَكٖ يَسۡبَحُونَ ﴿٣٣﴾", "w": [["كانتا رتقاً", "كتلة واحدة منسدّة لا انفتاح فيها."], ["ففتقناهما", "جعلنا السماء سبع سماوات والأرض سبع أرضين."], ["رواسي", "جبالاً ثابتة."], ["أن تميد بهم", "أن تتحرك فتميل بهم."], ["فجاجاً سبلاً", "طرقاً واسعة يسلكونها تصل بهم إلى حيث يريدون."], ["لعلهم يهتدون", "إلى مقاصدهم في أسفارهم."], ["وهم عن آياتها", "من الشمس والقمر والليل والنهار معرضون."], ["كل في فلك يسبحون", "الفلك: كل شيء دائر."]], "m": "ما زال السياق في تقرير التوحيد: أولم ينظر الكافرون إلى مظاهر قدرته في المخلوقات العلوية والسفلية؟ فالسماوات والأرض كانتا كتلة واحدة فخلق الله منها السماوات والأرضين، كما أن السماء تتفتّق بإذنه عن الأمطار، والأرض تتفتّق عن النباتات المختلفة الألوان والطعوم، وجعلنا من الماء كل شيء حي من إنسان وحيوان ونبات، أليست هذه دالة على وجوب عبادته وتوحيده؟ أفلا يؤمنون؟ وجعلنا في الأرض جبالاً ثوابت كيلا تتحرّك بسكانها، وجعلنا فيها طرقاً سابلة لعلهم يهتدون إلى مقاصدهم، وجعلنا السماء سقفاً محفوظاً من السقوط ومن الشياطين، وهم عن آياتها من الشمس والقمر والليل والنهار معرضون لا يفكّرون فيها. وهو الذي خلق الليل والنهار والشمس والقمر، كل منهما في فلك خاص به يسبح الدهر كله، لا يخرج عنه، إذ لو خرج لحصل الدمار الشامل، فسبحان العليم الحكيم.", "h": ["بيان مظاهر قدرة الله وعلمه وحكمته الموجبة لتوحيده والإيمان به وطاعته.", "بيان الحكمة من خلق الجبال الرواسي.", "بيان دقة النظام الإلهي، وعظيم العلم والحكمة له سبحانه وتعالى.", "إعراض أكثر الناس عن آيات الله في الآفاق، كإعراضهم عن آياته القرآنية، هو سبب جهلهم وشركهم وشرّهم وفسادهم."], "k": "«وجعلنا من الماء كل شيء حي»… كوب ماء أشربه آية؛ فهل أتفكّر فيه وأشكر؟"}, {"lbl": "الآيات ٣٤ – ٣٨", "q": "وَمَا جَعَلۡنَا لِبَشَرٖ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِيْن مِّتَّ فَهُمُ ٱلۡخَٰلِدُونَ ﴿٣٤﴾ كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ وَإِلَيۡنَا تُرۡجَعُونَ ﴿٣٥﴾ وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ هُمۡ كَٰفِرُونَ ﴿٣٦﴾ خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٖۚ سَأُوْرِيكُمۡ ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ ﴿٣٧﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٣٨﴾", "w": [["الخلد", "البقاء في الدنيا."], ["ذائقة الموت", "ذائقة مرارة مفارقة الجسد."], ["ونبلوكم", "نختبركم."], ["بالشر والخير", "الشر كالفقر والمرض، والخير كالغنى والصحة."], ["فتنة", "لأجل الفتنة، لننظر أتصبرون وتشكرون أم تجزعون."], ["إن يتخذونك إلا هزواً", "ما يتخذونك إلا مهزوءاً بك."], ["يذكر آلهتكم", "يعيبها."], ["بذكر الرحمن هم كافرون", "حيث أنكروا اسم الرحمن لله تعالى وقالوا: وما الرحمن؟"], ["خُلق الإنسان من عجل", "خلق الله آدم في آخر ساعة من يوم الجمعة على عجل، فورث بنوه طبع العجلة عنه."], ["سأريكم آياتي", "سأريكم ما حملته آياتي من وعيد لكم بالعذاب في الدنيا."]], "m": "قال المشركون شامتين: إن محمداً سيموت، نتربّص به ريب المنون، فأخبر تعالى أنه لم يجعل لبشر من قبله الخلد، فإن مات فهل هم الخالدون؟ لا، فلا وجه للشماتة بالموت. كل نفس ذائقة مرارة الموت بمفارقة الروح للبدن، ليتلقّى العبد بعده جزاء عمله، ونختبركم بالشر والخير، من غنى وفقر ومرض وصحة وشدة ورخاء، ليُرى الصابر الشاكر والجزع الكافر، وإلينا ترجعون للحساب. وإذا رآك الذين كفروا ما يتخذونك إلا هزواً لجهلهم بمقامك، يقولون: أهذا الذي يعيب آلهتكم؟ وهم بذكر الرحمن كافرون، عجباً لهم يتألّمون لذكر آلهتهم بسوء، ولا يتألّمون لكفرهم بربهم حتى أنكروا اسم الرحمن. ولما استعجلوا العذاب أخبر أن الإنسان خُلق من عجل، فالعجلة من طبعه، وسأريكم آياتي بإنزال العذاب بكم، وأراهم ذلك في بدر، فلا تستعجلون. ويقولون: متى هذا الوعد إن كنتم صادقين؟ وهذا عائد إلى طبع العجلة وإلى جهلهم، وإلا فالعاقل يطالب بالرحمة لا بالعذاب.", "h": ["إبطال ما شاع من أن الخضر حي مخلّد لا يموت، لنفيه تعالى ذلك عن كل البشر.", "بيان العلّة من وجود خير وشر في هذه الحياة الدنيا، وهي الاختبار.", "بيان ما كان عليه المشركون من الاستهزاء بالرسول ﷺ.", "تقرير حقيقة أن الإنسان مطبوع على العجلة، فمن غيّر طبعه بالتربية فأصبح ذا أناة وتؤدة كان من أكمل الناس وأشرفهم."], "k": "«ونبلوكم بالشر والخير فتنة»… النعمة التي أنا فيها اختبار كالمحنة؛ فهل أنجح فيها بالشكر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 228;
