insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (229, 21, 39, 50, 'سورة الأنبياء ٣٩ – ٥٠', '«قل من يكلؤكم بالليل والنهار من الرحمن»، و«ونضع الموازين القسط ليوم القيامة»، و«وهذا ذكر مبارك أنزلناه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 229) = $j$[{"lbl": "الآيات ٣٩ – ٤٣", "q": "لَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ يُنصَرُونَ ﴿٣٩﴾ بَلۡ تَأۡتِيهِم بَغۡتَةٗ فَتَبۡهَتُهُمۡ فَلَا يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُنظَرُونَ ﴿٤٠﴾ وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٤١﴾ قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ ﴿٤٢﴾ أَمۡ لَهُمۡ ءَالِهَةٞ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ ﴿٤٣﴾", "w": [["لا يكفّون", "لا يمنعون ولا يدفعون النار عن وجوههم."], ["بغتة", "فجأة."], ["فتبهتهم", "تحيّرهم."], ["ولا هم يُنظرون", "لا يُمهلون ليتوبوا."], ["فحاق بالذين سخروا", "نزل بهم العذاب الذي كانوا به يستهزئون."], ["من يكلؤكم", "من يحفظكم ويحرسكم."], ["من الرحمن", "من عذابه إن أراد إنزاله بكم."], ["بل هم عن ذكر ربهم معرضون", "عن القرآن، فلا يستمعون إليه ولا يفكّرون فيه."], ["ولا هم منا يُصحبون", "لا يجدون من يجيرهم من عذابنا."]], "m": "لو يعلم الكافرون المستعجلون بالعذاب حين يُلقون في جهنم والنار تأكل وجوههم وظهورهم، لا يستطيعون منعها ولا يُنصرون، لما استعجلوا يوم القيامة. بل تأتيهم القيامة فجأة لا على علم بوقتها فتحيّرهم، فلا يستطيعون ردّها ولا يُمهلون ليتوبوا. ولقد استُهزئ برسل من قبلك فنزل بالساخرين ما كانوا به يستهزئون، تسلية له ﷺ ليصبر كما صبروا. قل للمستعجلين: من يحفظكم بالليل والنهار من عذاب الرحمن إن أراد أن يعذّبكم؟ لا أحد، فلِمَ لا تتوبون إلى التوحيد والطاعة؟ بل هم عن القرآن معرضون، وهذه علّة عدم استجابتهم. أم لهم آلهة تمنعهم من عذابنا؟ إن آلهتهم لا تستطيع نصر أنفسها، وليس هناك من يجيرهم منا.", "h": ["تقرير أن الساعة لا تأتي إلا بغتة.", "تقرير عقيدة البعث والجزاء.", "تسلية الرسول ﷺ بما كان عليه الرسل من قبله وما لاقوه من أممهم.", "بيان عجز آلهة المشركين عن نصرتهم بدفع العذاب عنهم متى حلّ بهم.", "بيان أن علّة إصرار المشركين على الشرك والكفر هو عدم إقبالهم على تدبّر القرآن الكريم وتفكّرهم في آياته وما تحمله من هدى ونور."], "k": "«قل من يكلؤكم بالليل والنهار من الرحمن»… حُرست طول الليل والنهار؛ فهل شكرت الحارس؟"}, {"lbl": "الآيات ٤٤ – ٤٧", "q": "بَلۡ مَتَّعۡنَا هَـٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ ﴿٤٤﴾ قُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ ﴿٤٥﴾ وَلَئِن مَّسَّتۡهُمۡ نَفۡحَةٞ مِّنۡ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ ﴿٤٦﴾ وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ ﴿٤٧﴾", "w": [["متّعنا هؤلاء وآباءهم", "بما أنعمنا عليهم من الخيرات."], ["حتى طال عليهم العمر", "فاغترّوا بذلك."], ["ننقصها من أطرافها", "بالفتح على النبي ﷺ وأصحابه المؤمنين."], ["إنما أنذركم بالوحي", "بأخبار الله تعالى التي يوحيها إليّ."], ["نفحة", "وقعة من عذاب خفيفة."], ["يا ويلنا إنا كنا ظالمين", "يا هلاكنا، إنا كنا ظالمين بالشرك والتكذيب."], ["الموازين القسط", "الموازين العادلة."], ["فلا تُظلم نفس شيئاً", "لا بنقص حسنة ولا بزيادة سيئة."], ["مثقال حبة", "زنة حبة من خردل."], ["وكفى بنا حاسبين", "محصين لكل شيء."]], "m": "ما زال السياق في إبطال دعاوى المشركين: بل متّعنا هؤلاء وآباءهم بالخيرات حتى طال عليهم العمر فاغترّوا بذلك. أفلا يرون أنا نأتي أرض الجزيرة ننقصها من أطرافها بدخول أهلها في الإسلام بلداً بعد بلد؟ أفهم الغالبون؟ بل الله هو الغالب. قل: إنما أنذركم عاقبة شرككم بالوحي الإلهي لا من تلقاء نفسي، ولا يسمع الصم الدعاء إذا ما يُنذرون، فحبّهم للشرك أصمّهم فاستوى إنذارهم وعدمه. ولئن مسّتهم وقعة خفيفة من عذاب ربك لصاحوا: يا ويلنا إنا كنا ظالمين، فكيف بهم إذا وُضعت الموازين العادلة يوم القيامة، فلا تُظلم نفس شيئاً، وإن كان مثقال حبة من خردل من حسنة أو سيئة أتينا بها، وكفى بنا محصين لأعمال العباد لعلمنا المحيط. ألا فلنتّق الله أيها العقلاء!", "h": ["طول العمر والرزق الواسع كثيراً ما يسبّب الغرور لصاحبه.", "حب الشيء يُعمي صاحبه حتى لا يرى إلا ما أحبه.", "بيان ضعف الإنسان، وأن أدنى عذاب ينزل به لا يتحمّله ويصرخ داعياً: يا هلاكاه.", "تقرير البعث والحساب والجزاء."], "k": "«وإن كان مثقال حبة من خردل أتينا بها»… حسنة صغيرة أستهين بها ستوزن؛ فلا أتركها."}, {"lbl": "الآيات ٤٨ – ٥٠", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ ﴿٤٨﴾ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ ﴿٤٩﴾ وَهَٰذَا ذِكۡرٞ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ ﴿٥٠﴾", "w": [["الفرقان", "التوراة، لأنها فارقة بين الحق والباطل كالقرآن."], ["وضياء", "يهدي إلى الحق في العقائد والشرائع."], ["وذكراً", "موعظة."], ["يخشون ربهم بالغيب", "يخافون ربهم وهم لا يرونه في الدنيا، فلا يعصونه بترك واجب ولا بفعل حرام."], ["وهم من الساعة مشفقون", "وهم من أهوال يوم القيامة وعذابه خائفون."], ["وهذا ذكر مبارك", "القرآن الكريم، تنال بركته قارئه والعامل به."], ["أفأنتم له منكرون", "الاستفهام للتوبيخ لمن أنكر أن القرآن كتاب الله."]], "m": "ولقد آتينا موسى وهارون الفرقان بين حقهما وباطل فرعون، كما فرّق بين التوحيد والشرك يوم بدر، وآتيناهما التوراة ضياءً يُستضاء به في معرفة الحلال والحرام والأحكام، وموعظة للمتقين، الذين يخافون ربهم وهم لا يرونه، وهم من أهوال الساعة خائفون. وهذا القرآن ذكر مبارك لا تُرفع بركته، فكل من قرأه وعمل بما فيه نالته بركته، الحرف منه بعشر حسنات، لا تنقضي عجائبه، هدى لمن استهدى، وشفاء لمن استشفى. أفأنتم له منكرون؟ يوبّخ العرب الذين كانوا يسألون اليهود عما في كتابهم ويصدّقونهم، ويكفرون بالقرآن الذي هو كتابهم وفيه ذكرهم وشرفهم.", "h": ["إظهار منّة الله تعالى على موسى وقومه، ومحمد ﷺ وأمته، بإنزال التوراة على موسى والقرآن على محمد ﷺ.", "بيان صفات المتقين، وهم الذين يخشون ربهم بالغيب فلا يعصونه بترك واجب ولا بفعل محرّم، وهم دائماً في إشفاق وخوف من يوم القيامة.", "الإشادة بالقرآن الكريم، حيث أنزله تعالى مباركاً.", "توبيخ وتقريع من يكفر بالقرآن وينكر ما فيه من الهدى والنور."], "k": "«الذين يخشون ربهم بالغيب»… في خلوتي حيث لا يراني أحد، هل أخشاه كما في العلن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 229;
insert into public.tdb_cards(topic, i, body) select 229, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٩ – ٤٣", "q": "لَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ يُنصَرُونَ ﴿٣٩﴾ بَلۡ تَأۡتِيهِم بَغۡتَةٗ فَتَبۡهَتُهُمۡ فَلَا يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُنظَرُونَ ﴿٤٠﴾ وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٤١﴾ قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ ﴿٤٢﴾ أَمۡ لَهُمۡ ءَالِهَةٞ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ ﴿٤٣﴾", "w": [["لا يكفّون", "لا يمنعون ولا يدفعون النار عن وجوههم."], ["بغتة", "فجأة."], ["فتبهتهم", "تحيّرهم."], ["ولا هم يُنظرون", "لا يُمهلون ليتوبوا."], ["فحاق بالذين سخروا", "نزل بهم العذاب الذي كانوا به يستهزئون."], ["من يكلؤكم", "من يحفظكم ويحرسكم."], ["من الرحمن", "من عذابه إن أراد إنزاله بكم."], ["بل هم عن ذكر ربهم معرضون", "عن القرآن، فلا يستمعون إليه ولا يفكّرون فيه."], ["ولا هم منا يُصحبون", "لا يجدون من يجيرهم من عذابنا."]], "m": "لو يعلم الكافرون المستعجلون بالعذاب حين يُلقون في جهنم والنار تأكل وجوههم وظهورهم، لا يستطيعون منعها ولا يُنصرون، لما استعجلوا يوم القيامة. بل تأتيهم القيامة فجأة لا على علم بوقتها فتحيّرهم، فلا يستطيعون ردّها ولا يُمهلون ليتوبوا. ولقد استُهزئ برسل من قبلك فنزل بالساخرين ما كانوا به يستهزئون، تسلية له ﷺ ليصبر كما صبروا. قل للمستعجلين: من يحفظكم بالليل والنهار من عذاب الرحمن إن أراد أن يعذّبكم؟ لا أحد، فلِمَ لا تتوبون إلى التوحيد والطاعة؟ بل هم عن القرآن معرضون، وهذه علّة عدم استجابتهم. أم لهم آلهة تمنعهم من عذابنا؟ إن آلهتهم لا تستطيع نصر أنفسها، وليس هناك من يجيرهم منا.", "h": ["تقرير أن الساعة لا تأتي إلا بغتة.", "تقرير عقيدة البعث والجزاء.", "تسلية الرسول ﷺ بما كان عليه الرسل من قبله وما لاقوه من أممهم.", "بيان عجز آلهة المشركين عن نصرتهم بدفع العذاب عنهم متى حلّ بهم.", "بيان أن علّة إصرار المشركين على الشرك والكفر هو عدم إقبالهم على تدبّر القرآن الكريم وتفكّرهم في آياته وما تحمله من هدى ونور."], "k": "«قل من يكلؤكم بالليل والنهار من الرحمن»… حُرست طول الليل والنهار؛ فهل شكرت الحارس؟"}, {"lbl": "الآيات ٤٤ – ٤٧", "q": "بَلۡ مَتَّعۡنَا هَـٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ ﴿٤٤﴾ قُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ ﴿٤٥﴾ وَلَئِن مَّسَّتۡهُمۡ نَفۡحَةٞ مِّنۡ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ ﴿٤٦﴾ وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ ﴿٤٧﴾", "w": [["متّعنا هؤلاء وآباءهم", "بما أنعمنا عليهم من الخيرات."], ["حتى طال عليهم العمر", "فاغترّوا بذلك."], ["ننقصها من أطرافها", "بالفتح على النبي ﷺ وأصحابه المؤمنين."], ["إنما أنذركم بالوحي", "بأخبار الله تعالى التي يوحيها إليّ."], ["نفحة", "وقعة من عذاب خفيفة."], ["يا ويلنا إنا كنا ظالمين", "يا هلاكنا، إنا كنا ظالمين بالشرك والتكذيب."], ["الموازين القسط", "الموازين العادلة."], ["فلا تُظلم نفس شيئاً", "لا بنقص حسنة ولا بزيادة سيئة."], ["مثقال حبة", "زنة حبة من خردل."], ["وكفى بنا حاسبين", "محصين لكل شيء."]], "m": "ما زال السياق في إبطال دعاوى المشركين: بل متّعنا هؤلاء وآباءهم بالخيرات حتى طال عليهم العمر فاغترّوا بذلك. أفلا يرون أنا نأتي أرض الجزيرة ننقصها من أطرافها بدخول أهلها في الإسلام بلداً بعد بلد؟ أفهم الغالبون؟ بل الله هو الغالب. قل: إنما أنذركم عاقبة شرككم بالوحي الإلهي لا من تلقاء نفسي، ولا يسمع الصم الدعاء إذا ما يُنذرون، فحبّهم للشرك أصمّهم فاستوى إنذارهم وعدمه. ولئن مسّتهم وقعة خفيفة من عذاب ربك لصاحوا: يا ويلنا إنا كنا ظالمين، فكيف بهم إذا وُضعت الموازين العادلة يوم القيامة، فلا تُظلم نفس شيئاً، وإن كان مثقال حبة من خردل من حسنة أو سيئة أتينا بها، وكفى بنا محصين لأعمال العباد لعلمنا المحيط. ألا فلنتّق الله أيها العقلاء!", "h": ["طول العمر والرزق الواسع كثيراً ما يسبّب الغرور لصاحبه.", "حب الشيء يُعمي صاحبه حتى لا يرى إلا ما أحبه.", "بيان ضعف الإنسان، وأن أدنى عذاب ينزل به لا يتحمّله ويصرخ داعياً: يا هلاكاه.", "تقرير البعث والحساب والجزاء."], "k": "«وإن كان مثقال حبة من خردل أتينا بها»… حسنة صغيرة أستهين بها ستوزن؛ فلا أتركها."}, {"lbl": "الآيات ٤٨ – ٥٠", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ ﴿٤٨﴾ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ ﴿٤٩﴾ وَهَٰذَا ذِكۡرٞ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ ﴿٥٠﴾", "w": [["الفرقان", "التوراة، لأنها فارقة بين الحق والباطل كالقرآن."], ["وضياء", "يهدي إلى الحق في العقائد والشرائع."], ["وذكراً", "موعظة."], ["يخشون ربهم بالغيب", "يخافون ربهم وهم لا يرونه في الدنيا، فلا يعصونه بترك واجب ولا بفعل حرام."], ["وهم من الساعة مشفقون", "وهم من أهوال يوم القيامة وعذابه خائفون."], ["وهذا ذكر مبارك", "القرآن الكريم، تنال بركته قارئه والعامل به."], ["أفأنتم له منكرون", "الاستفهام للتوبيخ لمن أنكر أن القرآن كتاب الله."]], "m": "ولقد آتينا موسى وهارون الفرقان بين حقهما وباطل فرعون، كما فرّق بين التوحيد والشرك يوم بدر، وآتيناهما التوراة ضياءً يُستضاء به في معرفة الحلال والحرام والأحكام، وموعظة للمتقين، الذين يخافون ربهم وهم لا يرونه، وهم من أهوال الساعة خائفون. وهذا القرآن ذكر مبارك لا تُرفع بركته، فكل من قرأه وعمل بما فيه نالته بركته، الحرف منه بعشر حسنات، لا تنقضي عجائبه، هدى لمن استهدى، وشفاء لمن استشفى. أفأنتم له منكرون؟ يوبّخ العرب الذين كانوا يسألون اليهود عما في كتابهم ويصدّقونهم، ويكفرون بالقرآن الذي هو كتابهم وفيه ذكرهم وشرفهم.", "h": ["إظهار منّة الله تعالى على موسى وقومه، ومحمد ﷺ وأمته، بإنزال التوراة على موسى والقرآن على محمد ﷺ.", "بيان صفات المتقين، وهم الذين يخشون ربهم بالغيب فلا يعصونه بترك واجب ولا بفعل محرّم، وهم دائماً في إشفاق وخوف من يوم القيامة.", "الإشادة بالقرآن الكريم، حيث أنزله تعالى مباركاً.", "توبيخ وتقريع من يكفر بالقرآن وينكر ما فيه من الهدى والنور."], "k": "«الذين يخشون ربهم بالغيب»… في خلوتي حيث لا يراني أحد، هل أخشاه كما في العلن؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (230, 21, 51, 65, 'سورة الأنبياء ٥١ – ٦٥', '«ولقد آتينا إبراهيم رشده»: «ما هذه التماثيل التي أنتم لها عاكفون»، وتكسير الأصنام، و«بل فعله كبيرهم هذا»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 230) = $j$[{"lbl": "الآيات ٥١ – ٥٨", "q": "۞وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ ﴿٥١﴾ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ ﴿٥٢﴾ قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ ﴿٥٣﴾ قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ ﴿٥٤﴾ قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّـٰعِبِينَ ﴿٥٥﴾ قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّـٰهِدِينَ ﴿٥٦﴾ وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ ﴿٥٧﴾ فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ ﴿٥٨﴾", "w": [["رشده", "هداه بمعرفة ربه والإيمان به ووجوب طاعته والتقرّب إليه."], ["التماثيل", "جمع تمثال، وهو الصورة المصنوعة على شبه إنسان أو حيوان."], ["التي أنتم لها عاكفون", "مقبلون عليها ملازمون لها تعبّداً."], ["أم أنت من اللاعبين", "الهازلين غير الجادّين فيما يقولون أو يفعلون."], ["ربكم رب السماوات", "المستحق للعبادة، مالك السماوات والأرض."], ["الذي فطرهن", "أنشأهن خلقاً وإيجاداً على غير مثال سابق."], ["لأكيدنّ أصنامكم", "لأحتالنّ على كسر أصنامكم وتحطيمها."], ["جذاذاً", "فتاتاً وقطعاً صغيرة."], ["إلا كبيراً لهم", "إلا أكبر صنم لهم فإنه لم يكسره."], ["لعلهم إليه يرجعون", "كي يرجعوا إليه فيؤمنوا بالله ويوحّدوه بعد أن يظهر لهم عجز آلهتهم."]], "m": "بعد ذكر ما منّ به على موسى وهارون ومحمد من الكتب، ذكر أنه منّ قبل ذلك على إبراهيم فآتاه رشده في صباه فعرّفه بربه وبطلان عبادة من سواه، وكنا عالمين بأهليّته للدعوة. إذ قال لأبيه آزر وقومه منكراً: ما هذه التماثيل التي أنتم ملازمون لها؟ قالوا: وجدنا آباءنا لها عابدين، فلم يذكروا برهاناً واكتفوا بالتقليد الأعمى، وهذا شأن كل من يعبد غير الله. قال: لقد كنتم أنتم وآباؤكم في ضلال واضح. قالوا: أجئتنا بالحق أم أنت لاعب غير جاد؟ قال: بل ربكم الحق رب السماوات والأرض الذي أنشأهن من غير مثال سابق، وأنا على ذلك من الشاهدين، وتالله لأحتالنّ على أصنامكم فأكسرها بعد أن ترجعوا عنها. فلما خرجوا إلى عيد لهم خارج المدينة أتاها فجعلها قطعاً متناثرة، إلا صنماً كبيراً تركه، لعلهم يرجعون إليه فيعبدون ربه حين يتبيّن لهم بطلان عبادة ما لا يدفع عن نفسه.", "h": ["مظاهر إنعام الله وإكرامه لمن اصطفى من عباده.", "تقرير النبوة والتوحيد، والتنديد بالشرك والمشركين.", "ذم التقليد، وأنه ليس بدليل ولا برهان للمقلّد على ما يعتقد أو يفعل.", "مشروعية الشهادة وفضلها في مواطن تعزّ فيها ويُحتاج إليها.", "تغيير المنكر باليد لمن قدر عليه مقدّم على تغييره باللسان، والجمع بينهما أفضل."], "k": "«وجدنا آباءنا لها عابدين»… عادة ورثتها بلا دليل؛ هل عرضتها على الوحي؟"}, {"lbl": "الآيات ٥٩ – ٦٥", "q": "قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّـٰلِمِينَ ﴿٥٩﴾ قَالُواْ سَمِعۡنَا فَتٗى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ ﴿٦٠﴾ قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ ﴿٦١﴾ قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَـٰٓإِبۡرَٰهِيمُ ﴿٦٢﴾ قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ ﴿٦٣﴾ فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّـٰلِمُونَ ﴿٦٤﴾ ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَـٰٓؤُلَآءِ يَنطِقُونَ ﴿٦٥﴾", "w": [["بآلهتنا", "بأصنامنا التي سمّوها آلهة لأنهم يعبدونها."], ["فتى يذكرهم", "يذكرهم بالعيب والانتقاص."], ["على أعين الناس", "ظاهراً يرونه بأعينهم."], ["يشهدون", "عليه بأنه الذي كسر الآلهة، ويشهدون العقوبة التي تنزل به."], ["أأنت فعلت هذا", "صيغة الاستنطاق والاستجواب."], ["بل فعله كبيرهم هذا", "أشار بإصبعه إلى الصنم الكبير الذي علّق به الفأس، وورّى بإصبعه تحاشياً للكذب."], ["فرجعوا إلى أنفسهم", "بعد التفكّر حكموا على أنفسهم بالظلم لعبادتهم ما لا ينطق."], ["نُكسوا على رءوسهم", "بعد اعترافهم بالحق رجعوا إلى إقرار الباطل، فكانوا كمن نُكس فجعل رأسه أسفل."], ["ما هؤلاء ينطقون", "فكيف تطلب منا أن نسألهم؟"]], "m": "استغلّ إبراهيم خروج القوم إلى عيدهم فكسر الآلهة وعلّق الفأس بكبيرها، فلما عادوا مساءً ليأخذوا الطعام الذي وضعوه بين يديها لتباركه في زعمهم وجدوها مهشّمة، فصاحوا: من فعل هذا بآلهتنا؟ إنه لمن الظالمين. قال بعضهم: سمعنا فتى يذكرها بعيب يقال له إبراهيم. قالوا: فأتوا به على أعين الناس لنحقّق معه، فإن ثبت عاقبناه ويشهد الناس عقوبته. فجاءوا به وقالوا: أأنت فعلت هذا بآلهتنا يا إبراهيم؟ قال: بل فعله كبيرهم هذا، يشير إليه تورية، فاسألوهم إن كانوا ينطقون، تقريعاً لهم. فرجعوا إلى أنفسهم باللائمة فقالوا: إنكم أنتم الظالمون حيث تألّهون ما لا ينطق ولا يدفع عن نفسه. ثم قلبهم الله رأساً على عقب فعادوا إلى الجدال بالباطل: لقد علمت يا إبراهيم ما هؤلاء ينطقون، فكيف تطلب منا أن نسألهم؟ وهو في ذاته اعتراف ببطلانها.", "h": ["الظلم معروف لدى البشر كلهم ومنكر بينهم، ولولا ظلمة النفوس لما أقرّوه بينهم.", "إقامة البيّنة على الدعاوى أمر مقرّر في عرف الناس، وجاءت به الشرائع من قبل.", "أسلوب المحاكمة يعتمد على الاستنطاق والاستجواب أولاً.", "مشروعية التورية خشية القول بالكذب."], "k": "«فرجعوا إلى أنفسهم… ثم نُكسوا على رءوسهم»… حين يلوح لي الحق، هل أثبت عليه أم أنتكس؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 230;
insert into public.tdb_cards(topic, i, body) select 230, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥١ – ٥٨", "q": "۞وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ ﴿٥١﴾ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ ﴿٥٢﴾ قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ ﴿٥٣﴾ قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ ﴿٥٤﴾ قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّـٰعِبِينَ ﴿٥٥﴾ قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّـٰهِدِينَ ﴿٥٦﴾ وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ ﴿٥٧﴾ فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ ﴿٥٨﴾", "w": [["رشده", "هداه بمعرفة ربه والإيمان به ووجوب طاعته والتقرّب إليه."], ["التماثيل", "جمع تمثال، وهو الصورة المصنوعة على شبه إنسان أو حيوان."], ["التي أنتم لها عاكفون", "مقبلون عليها ملازمون لها تعبّداً."], ["أم أنت من اللاعبين", "الهازلين غير الجادّين فيما يقولون أو يفعلون."], ["ربكم رب السماوات", "المستحق للعبادة، مالك السماوات والأرض."], ["الذي فطرهن", "أنشأهن خلقاً وإيجاداً على غير مثال سابق."], ["لأكيدنّ أصنامكم", "لأحتالنّ على كسر أصنامكم وتحطيمها."], ["جذاذاً", "فتاتاً وقطعاً صغيرة."], ["إلا كبيراً لهم", "إلا أكبر صنم لهم فإنه لم يكسره."], ["لعلهم إليه يرجعون", "كي يرجعوا إليه فيؤمنوا بالله ويوحّدوه بعد أن يظهر لهم عجز آلهتهم."]], "m": "بعد ذكر ما منّ به على موسى وهارون ومحمد من الكتب، ذكر أنه منّ قبل ذلك على إبراهيم فآتاه رشده في صباه فعرّفه بربه وبطلان عبادة من سواه، وكنا عالمين بأهليّته للدعوة. إذ قال لأبيه آزر وقومه منكراً: ما هذه التماثيل التي أنتم ملازمون لها؟ قالوا: وجدنا آباءنا لها عابدين، فلم يذكروا برهاناً واكتفوا بالتقليد الأعمى، وهذا شأن كل من يعبد غير الله. قال: لقد كنتم أنتم وآباؤكم في ضلال واضح. قالوا: أجئتنا بالحق أم أنت لاعب غير جاد؟ قال: بل ربكم الحق رب السماوات والأرض الذي أنشأهن من غير مثال سابق، وأنا على ذلك من الشاهدين، وتالله لأحتالنّ على أصنامكم فأكسرها بعد أن ترجعوا عنها. فلما خرجوا إلى عيد لهم خارج المدينة أتاها فجعلها قطعاً متناثرة، إلا صنماً كبيراً تركه، لعلهم يرجعون إليه فيعبدون ربه حين يتبيّن لهم بطلان عبادة ما لا يدفع عن نفسه.", "h": ["مظاهر إنعام الله وإكرامه لمن اصطفى من عباده.", "تقرير النبوة والتوحيد، والتنديد بالشرك والمشركين.", "ذم التقليد، وأنه ليس بدليل ولا برهان للمقلّد على ما يعتقد أو يفعل.", "مشروعية الشهادة وفضلها في مواطن تعزّ فيها ويُحتاج إليها.", "تغيير المنكر باليد لمن قدر عليه مقدّم على تغييره باللسان، والجمع بينهما أفضل."], "k": "«وجدنا آباءنا لها عابدين»… عادة ورثتها بلا دليل؛ هل عرضتها على الوحي؟"}, {"lbl": "الآيات ٥٩ – ٦٥", "q": "قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّـٰلِمِينَ ﴿٥٩﴾ قَالُواْ سَمِعۡنَا فَتٗى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ ﴿٦٠﴾ قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ ﴿٦١﴾ قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَـٰٓإِبۡرَٰهِيمُ ﴿٦٢﴾ قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ ﴿٦٣﴾ فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّـٰلِمُونَ ﴿٦٤﴾ ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَـٰٓؤُلَآءِ يَنطِقُونَ ﴿٦٥﴾", "w": [["بآلهتنا", "بأصنامنا التي سمّوها آلهة لأنهم يعبدونها."], ["فتى يذكرهم", "يذكرهم بالعيب والانتقاص."], ["على أعين الناس", "ظاهراً يرونه بأعينهم."], ["يشهدون", "عليه بأنه الذي كسر الآلهة، ويشهدون العقوبة التي تنزل به."], ["أأنت فعلت هذا", "صيغة الاستنطاق والاستجواب."], ["بل فعله كبيرهم هذا", "أشار بإصبعه إلى الصنم الكبير الذي علّق به الفأس، وورّى بإصبعه تحاشياً للكذب."], ["فرجعوا إلى أنفسهم", "بعد التفكّر حكموا على أنفسهم بالظلم لعبادتهم ما لا ينطق."], ["نُكسوا على رءوسهم", "بعد اعترافهم بالحق رجعوا إلى إقرار الباطل، فكانوا كمن نُكس فجعل رأسه أسفل."], ["ما هؤلاء ينطقون", "فكيف تطلب منا أن نسألهم؟"]], "m": "استغلّ إبراهيم خروج القوم إلى عيدهم فكسر الآلهة وعلّق الفأس بكبيرها، فلما عادوا مساءً ليأخذوا الطعام الذي وضعوه بين يديها لتباركه في زعمهم وجدوها مهشّمة، فصاحوا: من فعل هذا بآلهتنا؟ إنه لمن الظالمين. قال بعضهم: سمعنا فتى يذكرها بعيب يقال له إبراهيم. قالوا: فأتوا به على أعين الناس لنحقّق معه، فإن ثبت عاقبناه ويشهد الناس عقوبته. فجاءوا به وقالوا: أأنت فعلت هذا بآلهتنا يا إبراهيم؟ قال: بل فعله كبيرهم هذا، يشير إليه تورية، فاسألوهم إن كانوا ينطقون، تقريعاً لهم. فرجعوا إلى أنفسهم باللائمة فقالوا: إنكم أنتم الظالمون حيث تألّهون ما لا ينطق ولا يدفع عن نفسه. ثم قلبهم الله رأساً على عقب فعادوا إلى الجدال بالباطل: لقد علمت يا إبراهيم ما هؤلاء ينطقون، فكيف تطلب منا أن نسألهم؟ وهو في ذاته اعتراف ببطلانها.", "h": ["الظلم معروف لدى البشر كلهم ومنكر بينهم، ولولا ظلمة النفوس لما أقرّوه بينهم.", "إقامة البيّنة على الدعاوى أمر مقرّر في عرف الناس، وجاءت به الشرائع من قبل.", "أسلوب المحاكمة يعتمد على الاستنطاق والاستجواب أولاً.", "مشروعية التورية خشية القول بالكذب."], "k": "«فرجعوا إلى أنفسهم… ثم نُكسوا على رءوسهم»… حين يلوح لي الحق، هل أثبت عليه أم أنتكس؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (231, 21, 66, 77, 'سورة الأنبياء ٦٦ – ٧٧', '«قلنا يا نار كوني برداً وسلاماً على إبراهيم»، و«وجعلناهم أئمة يهدون بأمرنا»، ولوط ونوح ﵉', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 231) = $j$[{"lbl": "الآيات ٦٦ – ٧٢", "q": "قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـٔٗا وَلَا يَضُرُّكُمۡ ﴿٦٦﴾ أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ ﴿٦٧﴾ قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ ﴿٦٨﴾ قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ ﴿٦٩﴾ وَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ ﴿٧٠﴾ وَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ ﴿٧١﴾ وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةٗۖ وَكُلّٗا جَعَلۡنَا صَٰلِحِينَ ﴿٧٢﴾", "w": [["ما لا ينفعكم شيئاً", "آلهة لا تنفعكم شيئاً ولا تضرّكم إن أرادت ضرّكم."], ["أفٍّ لكم", "قبحاً لكم ولما تعبدون من دون الله."], ["قالوا حرّقوه", "أحرقوه بالنار انتصاراً لآلهتكم التي كسرها."], ["برداً وسلاماً", "على إبراهيم، فكانت كذلك فلم تحرق منه غير وثاقه."], ["كيداً", "تحريقه بالنار للتخلّص منه."], ["فجعلناهم الأخسرين", "خرج من النار ولم تحرقه ونجا من قبضتهم، وذهب كيدهم."], ["ونجّيناه ولوطاً", "لوط ابن أخيه هاران."], ["التي باركنا فيها", "أرض الشام."], ["ويعقوب نافلة", "زيادة على طلبه الولد، فطلب ولداً فأعطاه ما طلب وزاده."], ["وكلاً جعلنا صالحين", "جعلنا كل واحد منهم من الصالحين الذين يؤدّون حقوق الله وحقوق الناس كاملة."]], "m": "قال إبراهيم لقومه منكراً: أفتعبدون من دون الله آلهة علمتم أنها لا تنفعكم ولا تضرّكم، ولا تنطق إذا استُنطقت؟ قبحاً لكم ولتلك التماثيل، أفلا تعقلون قبح عبادة جماد لا يسمع ولا ينفع؟ قالوا: أحرقوه بالنار وانصروا آلهتكم التي أهانها إن كنتم مريدين نصرتها حقاً. فجمعوا الحطب وأجّجوا النار في بنيان خاص وألقوه فيه بمنجنيق لشدة حرّها، فقلنا: يا نار كوني برداً وسلاماً على إبراهيم، فلم تحرق غير وثاقه، ولو لم يقل وسلاماً لجاز أن تنقلب برداً يهلك به. وأرادوا به مكراً بإحراقه فخيّب الله مسعاهم وأنجى خليله، فخسروا في كل ما دبّروا. ونجّيناه وابن أخيه لوطاً إلى أرض الشام التي باركنا فيها للعالمين بكثرة الأشجار والأنهار والثمار، فنزل إبراهيم بفلسطين ولوط بالمؤتفكة. ووهبنا له إسحاق حين سأل الولد، وزدناه يعقوب نافلة، وكلاً جعلنا من الصالحين الذين أدّوا حقوق الرب وحقوق الناس كاملة.", "h": ["بيان قوة حجة إبراهيم ﵇ ومتانة أسلوبه في دعوته، وذلك مما آتاه ربه.", "مشروعية توبيخ أهل الباطل وتأنيبهم.", "إبطال مفعول النار، فلم تحرق إبراهيم إلا وثاقه لما أراد الله تعالى ذلك.", "قوة التوكّل على الله كانت سبب تلك المعجزة، إذ قال إبراهيم: حسبي الله ونعم الوكيل، فقال الله تعالى للنار: «كوني برداً وسلاماً على إبراهيم»، فكانت، وكفاه ما أهمّه بصدق توكّله عليه.", "تقرير التوحيد والتنديد بالشرك والمشركين.", "خروج إبراهيم من أرض العراق إلى أرض الشام كان أول هجرة في سبيل الله."], "k": "«حسبي الله ونعم الوكيل»… قالها في النار فكانت برداً؛ فأقولها في همّي بصدق."}, {"lbl": "الآيات ٧٣ – ٧٧", "q": "وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا عَٰبِدِينَ ﴿٧٣﴾ وَلُوطًا ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗا وَنَجَّيۡنَٰهُ مِنَ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَت تَّعۡمَلُ ٱلۡخَبَـٰٓئِثَۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَٰسِقِينَ ﴿٧٤﴾ وَأَدۡخَلۡنَٰهُ فِي رَحۡمَتِنَآۖ إِنَّهُۥ مِنَ ٱلصَّـٰلِحِينَ ﴿٧٥﴾ وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ ﴿٧٦﴾ وَنَصَرۡنَٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ ﴿٧٧﴾", "w": [["أئمة", "يُقتدى بهم في الخير."], ["يهدون بأمرنا", "يرشدون الناس ويعلّمونهم ما به كمالهم ونجاتهم بإذن الله لهم، حيث جعلهم رسلاً."], ["وكانوا لنا عابدين", "خاشعين مطيعين قائمين بأمرنا."], ["ولوطاً آتيناه حكماً وعلماً", "فصلاً بين الخصوم، وفقهاً في الدين."], ["تعمل الخبائث", "كاللواط وغيره من المفاسد."], ["فاسقين", "عصاة متمرّدين عن الشرع تاركين للعمل به."], ["ونوحاً إذ نادى من قبل", "اذكر نوحاً إذ دعا ربّه على قومه الكفرة."], ["من الكرب العظيم", "من الغرق الناتج عن الطوفان."]], "m": "ما زال السياق في أفضال الله على إبراهيم وولده: وجعلناهم أئمة هداة يُقتدى بهم، يهدون الناس إلى دين الله بأمرنا، وأوحينا إليهم أن يفعلوا الخيرات، كل نافع فيه مرضاة الله، وأن يقيموا الصلاة ويؤتوا الزكاة، وكانوا لنا مطيعين خاشعين. ولوطاً، وقد خرج مهاجراً مع عمه، آتيناه حكماً وعلماً ونبوة، ونجّيناه من القرية التي كانت تعمل الخبائث وأهلكنا أهلها، إنهم كانوا قوم سوء لا يصدر عنهم إلا ما يسوء، فاسقين عن أمرنا، وأدخلناه في رحمتنا الخاصة إنه من الصالحين. ونوحاً إذ نادى ربه من قبل إبراهيم: إني مغلوب فانتصر، فاستجبنا له فنجّيناه وأهله، إلا امرأته وولده كنعان لكفرهما، من الغرق، ونصرناه من القوم الذين كذّبوا بآياتنا فلم يمسّوه بسوء، إنهم كانوا قوم سوء فأغرقناهم أجمعين.", "h": ["فضل الدعوة إلى الله تعالى وشرف القائمين بها.", "فضل إقام الصلاة وإيتاء الزكاة وفعل الخيرات.", "ثناء الله تعالى على أوليائه وصالحي عباده بعبادتهم وخشوعهم له.", "الخبث إذا كثر في الأمة استوجبت الهلاك والدمار.", "التنديد بالفسق، والتحذير من عواقبه، فإنها مدمّرة والعياذ بالله.", "تقرير النبوة المحمدية وتأكيدها، إذ مثل هذا القصص لا يتأتّى إلا لمن يوحى إليه."], "k": "«وأوحينا إليهم فعل الخيرات»… أي خير صغير أفعله الآن قبل أن ينقضي اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 231;
insert into public.tdb_cards(topic, i, body) select 231, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٦ – ٧٢", "q": "قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـٔٗا وَلَا يَضُرُّكُمۡ ﴿٦٦﴾ أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ ﴿٦٧﴾ قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ ﴿٦٨﴾ قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ ﴿٦٩﴾ وَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ ﴿٧٠﴾ وَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ ﴿٧١﴾ وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةٗۖ وَكُلّٗا جَعَلۡنَا صَٰلِحِينَ ﴿٧٢﴾", "w": [["ما لا ينفعكم شيئاً", "آلهة لا تنفعكم شيئاً ولا تضرّكم إن أرادت ضرّكم."], ["أفٍّ لكم", "قبحاً لكم ولما تعبدون من دون الله."], ["قالوا حرّقوه", "أحرقوه بالنار انتصاراً لآلهتكم التي كسرها."], ["برداً وسلاماً", "على إبراهيم، فكانت كذلك فلم تحرق منه غير وثاقه."], ["كيداً", "تحريقه بالنار للتخلّص منه."], ["فجعلناهم الأخسرين", "خرج من النار ولم تحرقه ونجا من قبضتهم، وذهب كيدهم."], ["ونجّيناه ولوطاً", "لوط ابن أخيه هاران."], ["التي باركنا فيها", "أرض الشام."], ["ويعقوب نافلة", "زيادة على طلبه الولد، فطلب ولداً فأعطاه ما طلب وزاده."], ["وكلاً جعلنا صالحين", "جعلنا كل واحد منهم من الصالحين الذين يؤدّون حقوق الله وحقوق الناس كاملة."]], "m": "قال إبراهيم لقومه منكراً: أفتعبدون من دون الله آلهة علمتم أنها لا تنفعكم ولا تضرّكم، ولا تنطق إذا استُنطقت؟ قبحاً لكم ولتلك التماثيل، أفلا تعقلون قبح عبادة جماد لا يسمع ولا ينفع؟ قالوا: أحرقوه بالنار وانصروا آلهتكم التي أهانها إن كنتم مريدين نصرتها حقاً. فجمعوا الحطب وأجّجوا النار في بنيان خاص وألقوه فيه بمنجنيق لشدة حرّها، فقلنا: يا نار كوني برداً وسلاماً على إبراهيم، فلم تحرق غير وثاقه، ولو لم يقل وسلاماً لجاز أن تنقلب برداً يهلك به. وأرادوا به مكراً بإحراقه فخيّب الله مسعاهم وأنجى خليله، فخسروا في كل ما دبّروا. ونجّيناه وابن أخيه لوطاً إلى أرض الشام التي باركنا فيها للعالمين بكثرة الأشجار والأنهار والثمار، فنزل إبراهيم بفلسطين ولوط بالمؤتفكة. ووهبنا له إسحاق حين سأل الولد، وزدناه يعقوب نافلة، وكلاً جعلنا من الصالحين الذين أدّوا حقوق الرب وحقوق الناس كاملة.", "h": ["بيان قوة حجة إبراهيم ﵇ ومتانة أسلوبه في دعوته، وذلك مما آتاه ربه.", "مشروعية توبيخ أهل الباطل وتأنيبهم.", "إبطال مفعول النار، فلم تحرق إبراهيم إلا وثاقه لما أراد الله تعالى ذلك.", "قوة التوكّل على الله كانت سبب تلك المعجزة، إذ قال إبراهيم: حسبي الله ونعم الوكيل، فقال الله تعالى للنار: «كوني برداً وسلاماً على إبراهيم»، فكانت، وكفاه ما أهمّه بصدق توكّله عليه.", "تقرير التوحيد والتنديد بالشرك والمشركين.", "خروج إبراهيم من أرض العراق إلى أرض الشام كان أول هجرة في سبيل الله."], "k": "«حسبي الله ونعم الوكيل»… قالها في النار فكانت برداً؛ فأقولها في همّي بصدق."}, {"lbl": "الآيات ٧٣ – ٧٧", "q": "وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا عَٰبِدِينَ ﴿٧٣﴾ وَلُوطًا ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗا وَنَجَّيۡنَٰهُ مِنَ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَت تَّعۡمَلُ ٱلۡخَبَـٰٓئِثَۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَٰسِقِينَ ﴿٧٤﴾ وَأَدۡخَلۡنَٰهُ فِي رَحۡمَتِنَآۖ إِنَّهُۥ مِنَ ٱلصَّـٰلِحِينَ ﴿٧٥﴾ وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ ﴿٧٦﴾ وَنَصَرۡنَٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ ﴿٧٧﴾", "w": [["أئمة", "يُقتدى بهم في الخير."], ["يهدون بأمرنا", "يرشدون الناس ويعلّمونهم ما به كمالهم ونجاتهم بإذن الله لهم، حيث جعلهم رسلاً."], ["وكانوا لنا عابدين", "خاشعين مطيعين قائمين بأمرنا."], ["ولوطاً آتيناه حكماً وعلماً", "فصلاً بين الخصوم، وفقهاً في الدين."], ["تعمل الخبائث", "كاللواط وغيره من المفاسد."], ["فاسقين", "عصاة متمرّدين عن الشرع تاركين للعمل به."], ["ونوحاً إذ نادى من قبل", "اذكر نوحاً إذ دعا ربّه على قومه الكفرة."], ["من الكرب العظيم", "من الغرق الناتج عن الطوفان."]], "m": "ما زال السياق في أفضال الله على إبراهيم وولده: وجعلناهم أئمة هداة يُقتدى بهم، يهدون الناس إلى دين الله بأمرنا، وأوحينا إليهم أن يفعلوا الخيرات، كل نافع فيه مرضاة الله، وأن يقيموا الصلاة ويؤتوا الزكاة، وكانوا لنا مطيعين خاشعين. ولوطاً، وقد خرج مهاجراً مع عمه، آتيناه حكماً وعلماً ونبوة، ونجّيناه من القرية التي كانت تعمل الخبائث وأهلكنا أهلها، إنهم كانوا قوم سوء لا يصدر عنهم إلا ما يسوء، فاسقين عن أمرنا، وأدخلناه في رحمتنا الخاصة إنه من الصالحين. ونوحاً إذ نادى ربه من قبل إبراهيم: إني مغلوب فانتصر، فاستجبنا له فنجّيناه وأهله، إلا امرأته وولده كنعان لكفرهما، من الغرق، ونصرناه من القوم الذين كذّبوا بآياتنا فلم يمسّوه بسوء، إنهم كانوا قوم سوء فأغرقناهم أجمعين.", "h": ["فضل الدعوة إلى الله تعالى وشرف القائمين بها.", "فضل إقام الصلاة وإيتاء الزكاة وفعل الخيرات.", "ثناء الله تعالى على أوليائه وصالحي عباده بعبادتهم وخشوعهم له.", "الخبث إذا كثر في الأمة استوجبت الهلاك والدمار.", "التنديد بالفسق، والتحذير من عواقبه، فإنها مدمّرة والعياذ بالله.", "تقرير النبوة المحمدية وتأكيدها، إذ مثل هذا القصص لا يتأتّى إلا لمن يوحى إليه."], "k": "«وأوحينا إليهم فعل الخيرات»… أي خير صغير أفعله الآن قبل أن ينقضي اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (232, 21, 78, 91, 'سورة الأنبياء ٧٨ – ٩١', '«ففهّمناها سليمان»، و«أني مسّني الضر وأنت أرحم الراحمين»، و«لا إله إلا أنت سبحانك إني كنت من الظالمين»، و«رب لا تذرني فرداً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 232) = $j$[{"lbl": "الآيات ٧٨ – ٨٢", "q": "وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ ﴿٧٨﴾ فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ ﴿٧٩﴾ وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ ﴿٨٠﴾ وَلِسُلَيۡمَٰنَ ٱلرِّيحَ عَاصِفَةٗ تَجۡرِي بِأَمۡرِهِۦٓ إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَاۚ وَكُنَّا بِكُلِّ شَيۡءٍ عَٰلِمِينَ ﴿٨١﴾ وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلٗا دُونَ ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ ﴿٨٢﴾", "w": [["في الحرث", "في الكرم الذي رعته الماشية ليلاً."], ["نفشت فيه", "رعته ليلاً بدون راعٍ."], ["شاهدين", "حاضرين صدور حكمهم في القضية لا يخفى علينا."], ["ففهّمناها", "القضية التي جرى فيها الحكم."], ["وكلاً آتينا حكماً وعلماً", "كلاً من داود وولده سليمان أعطيناه النبوة وعلماً بأحكام الله وفقهها."], ["يسبّحن", "معه إذا سبّح."], ["وكنا فاعلين", "لما هو أغرب وأعجب من تسبيح الجبال والطير."], ["صنعة لبوس لكم", "الدروع، وهي من لباس الحرب."], ["لتحصنكم", "تقيكم وتحفظكم من ضرب السيوف وطعن الرماح."], ["فهل أنتم شاكرون", "اشكروا، فالاستفهام معناه الأمر."], ["إلى الأرض التي باركنا", "أرض الشام."], ["يغوصون", "في أعماق البحر لاستخراج الجواهر."], ["ويعملون عملاً دون ذلك", "دون الغوص كالبناء وبعض الصناعات."], ["وكنا لهم حافظين", "لأعمالهم حتى لا يفسدوها."]], "m": "ما زال السياق في ذكر إفضالات الله على من يشاء من عباده، وفيه تقرير نبوة محمد ﷺ: واذكر داود وسليمان إذ يحكمان في الكرم الذي رعته غنم القوم ليلاً فأتلفته، وكنا لحكمهم حاضرين: حكم داود بأن يأخذ صاحب الحرث الغنم مقابل ما أتلفته لأن قيمته تعادلها، وحكم سليمان بأن يأخذ صاحب الغنم الزرع يقوم عليه حتى يعود كما كان، ويأخذ صاحب الحرث الغنم يستغلّ صوفها ولبنها، فإذا عاد الكرم ردّها، ففهّمناها سليمان وهو أعدل، ولم يعاتب داود، وكلاً آتينا حكماً وعلماً، تلافياً لما قد يُظن أن داود دون ولده. وسخّرنا مع داود الجبال والطير يسبّحن معه إذا سبّح، وكنا فاعلين لما هو أعجب، وعلّمناه صنعة الدروع تقي لابسها الطعن والضرب، فهل أنتم شاكرون؟ والشكر بحمد الله وطاعته وصرف النعمة فيما أنعم بها لأجله. وسخّرنا لسليمان الريح شديدة السرعة تجري بأمره، يخرج غازياً أول النهار وتعود به آخره إلى أرض الشام، وكنا بكل شيء عالمين، ومن الشياطين من يغوصون له في أعماق البحار لاستخراج الجواهر، ويعملون له البناء والمحاريب والتماثيل والجفان، وكنا لأعمالهم حافظين حتى لا يفسدوها مكراً بعد عملها.", "h": ["وجوب نصب القضاة للحكم بين الناس.", "بيان حكم الماشية ترعى في حرث الناس، وإن كان شرعنا على خلاف شرع من سبقنا، فالحكم عندنا: إن رعت الماشية ليلاً قُوّم المُتلَف على صاحب الماشية ودفعه لصاحب الزرع، وإن رعت نهاراً فلا شيء لصاحب الزرع، لأن عليه أن يحفظ زرعه، لحديث «العجماء جُبار» وحديث ناقة البراء بن عازب.", "فضل التسبيح.", "وجوب صنع آلة الحرب وإعدادها للجهاد في سبيل الله.", "وجوب شكر الله تعالى على كل نعمة تستجدّ للعبد.", "بيان تسخير الله تعالى الجن لسليمان يعملون له أشياء.", "تقرير نبوة الرسول ﷺ، إذ من أرسل هؤلاء الرسل وأنعم عليهم بما أنعم لا يُستنكر عليه إرسال محمد رسولاً.", "كل ما يحدث في الكون من أحداث يحدث بعلم الله تعالى وتقديره ولحكمة تقتضيه."], "k": "«ففهّمناها سليمان وكلاً آتينا حكماً وعلماً»… حين يكون غيري أصوب مني، هل أقرّ له بلا حرج؟"}, {"lbl": "الآيات ٨٣ – ٨٦", "q": "۞وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّـٰحِمِينَ ﴿٨٣﴾ فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ ﴿٨٤﴾ وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّـٰبِرِينَ ﴿٨٥﴾ وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّـٰلِحِينَ ﴿٨٦﴾", "w": [["وأيوب", "واذكر أيوب."], ["إذ نادى ربه", "دعاه لما ابتُلي بفقد ماله وولده ومرض جسده."], ["مسّني الضر", "ما ضرّ بجسمه أو ماله أو ولده."], ["وذكرى للعابدين", "عظة للعابدين ليصبروا فيُثابوا."], ["وأدخلناهم في رحمتنا", "بأن نبّأناهم فانخرطوا في سلك الأنبياء."]], "m": "ما زال السياق في ذكر إنعام الله على عباده الصالحين: واذكر أيوب في شكره وصبره وسرعة أوبته، ابتليناه بالعافية والمال والولد فشكر، وابتليناه بالمرض وذهاب المال والأهل والولد فصبر، إذ نادى ربه ضارعاً بعد بلوغ البلاء منتهاه: رب أني مسّني الضر وأنت أرحم الراحمين، فاستجبنا له فكشفنا ما به من ضر، وآتيناه أهله من زوجة وولد ومثلهم معهم، وفي المال ذكر النبي ﷺ أنه كان يحثو في ثوبه، فقال له ربه في ذلك فقال: من ذا الذي يستغني عن بركتك يا رب؟ رحمة خاصة من عندنا، وجعلنا قصته موعظة للعابدين حين نبتليهم بالسراء والضراء فيشكرون ويصبرون ائتساءً به. واذكر إسماعيل وإدريس وذا الكفل، كل من الصابرين على عبادتنا الشاكرين لنعمائنا، وأدخلناهم في رحمتنا إنهم من الصالحين.", "h": ["علوّ مقام الصبر، ومثله الشكر، فالأول على البأساء والثاني على النعماء.", "فضيلة الدعاء، وهو باب الاستجابة وطريقها، من أُلهمه أُلهم الاستجابة.", "في سير الصالحين مواعظ، وفي قصص الماضين عبر.", "من ابتُلي بفقد مال أو أهل أو ولد فصبر كان له من الله الخلف، وما يقال عند المصيبة: «إنا لله وإنا إليه راجعون، اللهم أجرني في مصيبتي واخلف لي خيراً منها»."], "k": "«أني مسّني الضر وأنت أرحم الراحمين»… شكا إلى الله وحده بأدب؛ فإلى من أشكو أنا؟"}, {"lbl": "الآيات ٨٧ – ٩١", "q": "وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّـٰلِمِينَ ﴿٨٧﴾ فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ ﴿٨٨﴾ وَزَكَرِيَّآ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدٗا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ ﴿٨٩﴾ فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبٗا وَرَهَبٗاۖ وَكَانُواْ لَنَا خَٰشِعِينَ ﴿٩٠﴾ وَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ ﴿٩١﴾", "w": [["وذا النون", "يونس بن متّى ﵇، أُضيف إلى النون وهو الحوت."], ["إذ ذهب مغاضباً", "لربه تعالى، حيث لم يرجع إلى قومه لما بلغه أن الله رفع عنهم العذاب."], ["فظن أن لن نقدر عليه", "أن لن نحبسه ونضيّق عليه في بطن الحوت."], ["في الظلمات", "ظلمة الحوت وظلمة البحر وظلمة الليل."], ["ونجّيناه من الغم", "الكرب الذي أصابه وهو في بطن الحوت."], ["لا تذرني فرداً", "بلا ولد يرث عني النبوة والعلم والحكمة."], ["رغباً ورهباً", "طمعاً فينا وخوفاً منا."], ["أحصنت فرجها", "صانته وحفظته من الفاحشة."], ["من روحنا", "جبريل، حيث نفخ في كمّ درعها."], ["آية للعالمين", "علامة على قدرة الله تعالى ووجوب عبادته."]], "m": "واذكر ذا النون يونس، إذ ذهب مغاضباً لربه، حيث لم يصبر على البقاء مع قومه يدعوهم فسأل لهم العذاب، فلما تابوا ورُفع عنهم لم يرجع إليهم، فظن أن الله لا يحبسه في بطن الحوت، وهو حسن ظن منه بربه، ولكن لمخالفته أصابه ربه تطهيراً بأن ألقاه في ظلمات ثلاث، وألهمه الدعاء الذي به النجاة: لا إله إلا أنت سبحانك إني كنت من الظالمين، فاستجبنا له ونجّيناه من الغم الذي أصابه محبوساً لا أنيس ولا طعام، وكذلك ننجي المؤمنين مما يحلّ بهم من البلاء. واذكر زكريا إذ نادى ربه: رب لا تتركني فرداً بلا ولد يرثني في نبوّتي وعلمي، وأنت خير الوارثين، توسّلاً به، فاستجبنا له ووهبنا له يحيى، وأصلحنا له زوجه فجعلناها ولوداً بعد العقم، حسنة الخلق، إنهم كانوا يسارعون في الطاعات والقربات، ويدعوننا رغبة في رحمتنا ورهبة من عذابنا، وكانوا لنا خاشعين. واذكر التي أحصنت فرجها، مريم بنت عمران، فنفخنا فيها من روحنا، إذ أمرنا جبريل فنفخ في كمّ درعها، وجعلناها وابنها عيسى علامة كبرى على وجودنا وقدرتنا ووجوب توحيدنا للناس أجمعين.", "h": ["فضيلة دعوة ذي النون: «لا إله إلا أنت سبحانك إني كنت من الظالمين»، إذ ورد أنه ما دعا بها مؤمن إلا استُجيب له، وقوله تعالى: «وكذلك ننجي المؤمنين» يقوّي هذا.", "استحباب سؤال الولد لغرض صالح، لا من أجل الزينة واللهو به فقط.", "تقرير أن الزوجة الصالحة من حسنة الدنيا.", "فضيلة المسارعة في الخيرات، والدعاء برغبة ورهبة، والخشوع في العبادات، وخاصة في الصلاة والدعاء.", "فضيلة العفّة والإحصان للفرج.", "كون مريم وابنها آية، لأن مريم ولدت من غير فحل، ولأن عيسى كان كذلك، وكلّم الناس في المهد، وكان يحيي الموتى بإذن الله تعالى."], "k": "«لا إله إلا أنت سبحانك إني كنت من الظالمين»… في ظلمة همّي، أرددها معترفاً لا معترضاً."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 232;
insert into public.tdb_cards(topic, i, body) select 232, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٨ – ٨٢", "q": "وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ ﴿٧٨﴾ فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ ﴿٧٩﴾ وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ ﴿٨٠﴾ وَلِسُلَيۡمَٰنَ ٱلرِّيحَ عَاصِفَةٗ تَجۡرِي بِأَمۡرِهِۦٓ إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَاۚ وَكُنَّا بِكُلِّ شَيۡءٍ عَٰلِمِينَ ﴿٨١﴾ وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلٗا دُونَ ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ ﴿٨٢﴾", "w": [["في الحرث", "في الكرم الذي رعته الماشية ليلاً."], ["نفشت فيه", "رعته ليلاً بدون راعٍ."], ["شاهدين", "حاضرين صدور حكمهم في القضية لا يخفى علينا."], ["ففهّمناها", "القضية التي جرى فيها الحكم."], ["وكلاً آتينا حكماً وعلماً", "كلاً من داود وولده سليمان أعطيناه النبوة وعلماً بأحكام الله وفقهها."], ["يسبّحن", "معه إذا سبّح."], ["وكنا فاعلين", "لما هو أغرب وأعجب من تسبيح الجبال والطير."], ["صنعة لبوس لكم", "الدروع، وهي من لباس الحرب."], ["لتحصنكم", "تقيكم وتحفظكم من ضرب السيوف وطعن الرماح."], ["فهل أنتم شاكرون", "اشكروا، فالاستفهام معناه الأمر."], ["إلى الأرض التي باركنا", "أرض الشام."], ["يغوصون", "في أعماق البحر لاستخراج الجواهر."], ["ويعملون عملاً دون ذلك", "دون الغوص كالبناء وبعض الصناعات."], ["وكنا لهم حافظين", "لأعمالهم حتى لا يفسدوها."]], "m": "ما زال السياق في ذكر إفضالات الله على من يشاء من عباده، وفيه تقرير نبوة محمد ﷺ: واذكر داود وسليمان إذ يحكمان في الكرم الذي رعته غنم القوم ليلاً فأتلفته، وكنا لحكمهم حاضرين: حكم داود بأن يأخذ صاحب الحرث الغنم مقابل ما أتلفته لأن قيمته تعادلها، وحكم سليمان بأن يأخذ صاحب الغنم الزرع يقوم عليه حتى يعود كما كان، ويأخذ صاحب الحرث الغنم يستغلّ صوفها ولبنها، فإذا عاد الكرم ردّها، ففهّمناها سليمان وهو أعدل، ولم يعاتب داود، وكلاً آتينا حكماً وعلماً، تلافياً لما قد يُظن أن داود دون ولده. وسخّرنا مع داود الجبال والطير يسبّحن معه إذا سبّح، وكنا فاعلين لما هو أعجب، وعلّمناه صنعة الدروع تقي لابسها الطعن والضرب، فهل أنتم شاكرون؟ والشكر بحمد الله وطاعته وصرف النعمة فيما أنعم بها لأجله. وسخّرنا لسليمان الريح شديدة السرعة تجري بأمره، يخرج غازياً أول النهار وتعود به آخره إلى أرض الشام، وكنا بكل شيء عالمين، ومن الشياطين من يغوصون له في أعماق البحار لاستخراج الجواهر، ويعملون له البناء والمحاريب والتماثيل والجفان، وكنا لأعمالهم حافظين حتى لا يفسدوها مكراً بعد عملها.", "h": ["وجوب نصب القضاة للحكم بين الناس.", "بيان حكم الماشية ترعى في حرث الناس، وإن كان شرعنا على خلاف شرع من سبقنا، فالحكم عندنا: إن رعت الماشية ليلاً قُوّم المُتلَف على صاحب الماشية ودفعه لصاحب الزرع، وإن رعت نهاراً فلا شيء لصاحب الزرع، لأن عليه أن يحفظ زرعه، لحديث «العجماء جُبار» وحديث ناقة البراء بن عازب.", "فضل التسبيح.", "وجوب صنع آلة الحرب وإعدادها للجهاد في سبيل الله.", "وجوب شكر الله تعالى على كل نعمة تستجدّ للعبد.", "بيان تسخير الله تعالى الجن لسليمان يعملون له أشياء.", "تقرير نبوة الرسول ﷺ، إذ من أرسل هؤلاء الرسل وأنعم عليهم بما أنعم لا يُستنكر عليه إرسال محمد رسولاً.", "كل ما يحدث في الكون من أحداث يحدث بعلم الله تعالى وتقديره ولحكمة تقتضيه."], "k": "«ففهّمناها سليمان وكلاً آتينا حكماً وعلماً»… حين يكون غيري أصوب مني، هل أقرّ له بلا حرج؟"}, {"lbl": "الآيات ٨٣ – ٨٦", "q": "۞وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّـٰحِمِينَ ﴿٨٣﴾ فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ ﴿٨٤﴾ وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّـٰبِرِينَ ﴿٨٥﴾ وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّـٰلِحِينَ ﴿٨٦﴾", "w": [["وأيوب", "واذكر أيوب."], ["إذ نادى ربه", "دعاه لما ابتُلي بفقد ماله وولده ومرض جسده."], ["مسّني الضر", "ما ضرّ بجسمه أو ماله أو ولده."], ["وذكرى للعابدين", "عظة للعابدين ليصبروا فيُثابوا."], ["وأدخلناهم في رحمتنا", "بأن نبّأناهم فانخرطوا في سلك الأنبياء."]], "m": "ما زال السياق في ذكر إنعام الله على عباده الصالحين: واذكر أيوب في شكره وصبره وسرعة أوبته، ابتليناه بالعافية والمال والولد فشكر، وابتليناه بالمرض وذهاب المال والأهل والولد فصبر، إذ نادى ربه ضارعاً بعد بلوغ البلاء منتهاه: رب أني مسّني الضر وأنت أرحم الراحمين، فاستجبنا له فكشفنا ما به من ضر، وآتيناه أهله من زوجة وولد ومثلهم معهم، وفي المال ذكر النبي ﷺ أنه كان يحثو في ثوبه، فقال له ربه في ذلك فقال: من ذا الذي يستغني عن بركتك يا رب؟ رحمة خاصة من عندنا، وجعلنا قصته موعظة للعابدين حين نبتليهم بالسراء والضراء فيشكرون ويصبرون ائتساءً به. واذكر إسماعيل وإدريس وذا الكفل، كل من الصابرين على عبادتنا الشاكرين لنعمائنا، وأدخلناهم في رحمتنا إنهم من الصالحين.", "h": ["علوّ مقام الصبر، ومثله الشكر، فالأول على البأساء والثاني على النعماء.", "فضيلة الدعاء، وهو باب الاستجابة وطريقها، من أُلهمه أُلهم الاستجابة.", "في سير الصالحين مواعظ، وفي قصص الماضين عبر.", "من ابتُلي بفقد مال أو أهل أو ولد فصبر كان له من الله الخلف، وما يقال عند المصيبة: «إنا لله وإنا إليه راجعون، اللهم أجرني في مصيبتي واخلف لي خيراً منها»."], "k": "«أني مسّني الضر وأنت أرحم الراحمين»… شكا إلى الله وحده بأدب؛ فإلى من أشكو أنا؟"}, {"lbl": "الآيات ٨٧ – ٩١", "q": "وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّـٰلِمِينَ ﴿٨٧﴾ فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ ﴿٨٨﴾ وَزَكَرِيَّآ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدٗا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ ﴿٨٩﴾ فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبٗا وَرَهَبٗاۖ وَكَانُواْ لَنَا خَٰشِعِينَ ﴿٩٠﴾ وَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ ﴿٩١﴾", "w": [["وذا النون", "يونس بن متّى ﵇، أُضيف إلى النون وهو الحوت."], ["إذ ذهب مغاضباً", "لربه تعالى، حيث لم يرجع إلى قومه لما بلغه أن الله رفع عنهم العذاب."], ["فظن أن لن نقدر عليه", "أن لن نحبسه ونضيّق عليه في بطن الحوت."], ["في الظلمات", "ظلمة الحوت وظلمة البحر وظلمة الليل."], ["ونجّيناه من الغم", "الكرب الذي أصابه وهو في بطن الحوت."], ["لا تذرني فرداً", "بلا ولد يرث عني النبوة والعلم والحكمة."], ["رغباً ورهباً", "طمعاً فينا وخوفاً منا."], ["أحصنت فرجها", "صانته وحفظته من الفاحشة."], ["من روحنا", "جبريل، حيث نفخ في كمّ درعها."], ["آية للعالمين", "علامة على قدرة الله تعالى ووجوب عبادته."]], "m": "واذكر ذا النون يونس، إذ ذهب مغاضباً لربه، حيث لم يصبر على البقاء مع قومه يدعوهم فسأل لهم العذاب، فلما تابوا ورُفع عنهم لم يرجع إليهم، فظن أن الله لا يحبسه في بطن الحوت، وهو حسن ظن منه بربه، ولكن لمخالفته أصابه ربه تطهيراً بأن ألقاه في ظلمات ثلاث، وألهمه الدعاء الذي به النجاة: لا إله إلا أنت سبحانك إني كنت من الظالمين، فاستجبنا له ونجّيناه من الغم الذي أصابه محبوساً لا أنيس ولا طعام، وكذلك ننجي المؤمنين مما يحلّ بهم من البلاء. واذكر زكريا إذ نادى ربه: رب لا تتركني فرداً بلا ولد يرثني في نبوّتي وعلمي، وأنت خير الوارثين، توسّلاً به، فاستجبنا له ووهبنا له يحيى، وأصلحنا له زوجه فجعلناها ولوداً بعد العقم، حسنة الخلق، إنهم كانوا يسارعون في الطاعات والقربات، ويدعوننا رغبة في رحمتنا ورهبة من عذابنا، وكانوا لنا خاشعين. واذكر التي أحصنت فرجها، مريم بنت عمران، فنفخنا فيها من روحنا، إذ أمرنا جبريل فنفخ في كمّ درعها، وجعلناها وابنها عيسى علامة كبرى على وجودنا وقدرتنا ووجوب توحيدنا للناس أجمعين.", "h": ["فضيلة دعوة ذي النون: «لا إله إلا أنت سبحانك إني كنت من الظالمين»، إذ ورد أنه ما دعا بها مؤمن إلا استُجيب له، وقوله تعالى: «وكذلك ننجي المؤمنين» يقوّي هذا.", "استحباب سؤال الولد لغرض صالح، لا من أجل الزينة واللهو به فقط.", "تقرير أن الزوجة الصالحة من حسنة الدنيا.", "فضيلة المسارعة في الخيرات، والدعاء برغبة ورهبة، والخشوع في العبادات، وخاصة في الصلاة والدعاء.", "فضيلة العفّة والإحصان للفرج.", "كون مريم وابنها آية، لأن مريم ولدت من غير فحل، ولأن عيسى كان كذلك، وكلّم الناس في المهد، وكان يحيي الموتى بإذن الله تعالى."], "k": "«لا إله إلا أنت سبحانك إني كنت من الظالمين»… في ظلمة همّي، أرددها معترفاً لا معترضاً."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (233, 21, 92, 112, 'سورة الأنبياء ٩٢ – ١١٢', '«إن هذه أمتكم أمة واحدة»، و«إن الذين سبقت لهم منا الحسنى»، و«وما أرسلناك إلا رحمة للعالمين»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 233) = $j$[{"lbl": "الآيات ٩٢ – ٩٧", "q": "إِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ ﴿٩٢﴾ وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ ﴿٩٣﴾ فَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا كُفۡرَانَ لِسَعۡيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ ﴿٩٤﴾ وَحَرَٰمٌ عَلَىٰ قَرۡيَةٍ أَهۡلَكۡنَٰهَآ أَنَّهُمۡ لَا يَرۡجِعُونَ ﴿٩٥﴾ حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبٖ يَنسِلُونَ ﴿٩٦﴾ وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةٖ مِّنۡ هَٰذَا بَلۡ كُنَّا ظَٰلِمِينَ ﴿٩٧﴾", "w": [["هذه أمتكم", "ملّتكم، وهي الإسلام، ملة واحدة من عهد آدم إلى العهد المحمدي."], ["وأنا ربكم فاعبدون", "أنا إلهكم الحق، خلقتكم ورزقتكم، فاعبدوني ولا تعبدوا معي غيري."], ["وتقطّعوا أمرهم بينهم", "تفرّقوا في دينهم فأصبح لكل فرقة دين كاليهودية والنصرانية والمجوسية."], ["كل إلينا راجعون", "كل فرقة راجعة إلينا وسوف نجزيها بكسبها."], ["فلا كفران لسعيه", "لا نكران ولا جحود لعمله، بل يُجزى به وافياً."], ["وإنا له كاتبون", "إذ الكرام الكاتبون يكتبون أعمال العباد."], ["وحرام", "ممتنع."], ["يأجوج ومأجوج", "قبيلتان وراء سدّهما الذي سيُفتح عند قرب الساعة."], ["حدب", "مرتفع من الأرض."], ["ينسلون", "يسرعون المشي."], ["الوعد الحق", "يوم القيامة."], ["في غفلة من هذا", "من يوم القيامة وما فيه من أحداث."]], "m": "بعد ذكر أولئك الأنبياء قال تعالى للناس كلهم: إن هذه ملّتكم ملة واحدة من أول الرسل إلى خاتمهم، وهي الإسلام القائم على الإخلاص لله في العبادة، وأنا ربكم فاعبدون. وينعى على الناس تقطيعهم الإسلام إلى ملل شتى ونحل، كل إلينا راجعون فنجزيهم بما كسبوا. فمن يعمل من الصالحات المشروعة وهو مؤمن فلا جحود لعمله، بل يجزى به كاملاً، والملائكة تكتب أعماله بأمرنا. وممتنع على أهل قرية أهلكهم الله بذنوبهم أنهم لا يرجعون إليه يوم القيامة، بل يرجعون للحساب، وطريق رجوعهم: حتى إذا فُتح سدّ يأجوج ومأجوج، وهو من علامات الساعة الكبرى، وهم من كل مرتفع يسرعون يخرّبون، واقترب يوم الدين، فإذا أبصار الذين كفروا شاخصة بعد قيامهم من قبورهم يقولون متحسّرين: يا ويلنا، قد كنا في غفلة من هذا في الدنيا، بل كنا ظالمين، فاعترفوا حيث لا ينفع الاعتراف.", "h": ["وحدة الدين، وكون الإسلام هو دين البشرية كافة، لأنه قائم على أساس توحيد الله تعالى في عبادته التي شرعها ليُعبد بها.", "بيان ما حدث للبشرية من تمزيق الدين بينها بحسب الأهواء والأطماع والأغراض.", "وعد الله لأهل الإيمان والعمل الصالح بالجزاء الحسن، وهو الجنة.", "إذا قُضي بهلاك أمة تعذّرت عليها التوبة، وأمة يهلكها الله لا تعود إلى الحياة الدنيا بحال، والبشرية عائدة إلى ربها لحسابها وجزائها يوم القيامة."], "k": "«فمن يعمل من الصالحات وهو مؤمن فلا كفران لسعيه»… لا يضيع عمل صالح؛ فلأعمل ولو لم يره أحد."}, {"lbl": "الآيات ٩٨ – ١٠٤", "q": "إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ ﴿٩٨﴾ لَوۡ كَانَ هَـٰٓؤُلَآءِ ءَالِهَةٗ مَّا وَرَدُوهَاۖ وَكُلّٞ فِيهَا خَٰلِدُونَ ﴿٩٩﴾ لَهُمۡ فِيهَا زَفِيرٞ وَهُمۡ فِيهَا لَا يَسۡمَعُونَ ﴿١٠٠﴾ إِنَّ ٱلَّذِينَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ أُوْلَـٰٓئِكَ عَنۡهَا مُبۡعَدُونَ ﴿١٠١﴾ لَا يَسۡمَعُونَ حَسِيسَهَاۖ وَهُمۡ فِي مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَٰلِدُونَ ﴿١٠٢﴾ لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ هَٰذَا يَوۡمُكُمُ ٱلَّذِي كُنتُمۡ تُوعَدُونَ ﴿١٠٣﴾ يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ ﴿١٠٤﴾", "w": [["وما تعبدون من دون الله", "من الأوثان والأصنام."], ["حصب جهنم", "ما توقد به جهنم."], ["لو كان هؤلاء آلهة", "الأوثان التي يعبدها المشركون من قريش."], ["ما وردوها", "لحالوا بين عابديهم ودخول النار لو كانوا آلهة قادرين."], ["وكل فيها خالدون", "العابدون من الناس والمعبودون الباطلون."], ["لهم فيها زفير", "لأهل النار فيها أنين وتنفّس شديد."], ["سبقت لهم منا الحسنى", "كتب الله تعالى أزلاً أنهم أهل الجنة."], ["حسيسها", "حسّ صوتها."], ["لا يحزنهم الفزع الأكبر", "عند نفخة البعث، فإنهم يقومون من قبورهم آمنين."], ["كطيّ السجل للكتب", "يطوي الجبار سبحانه السماء طيّ الصحيفة."], ["كما بدأنا أول خلق نعيده", "يبعث الناس من قبورهم حفاة عراة غرلاً كما وُلدوا."]], "m": "يقول تعالى لمشركي قريش متوعّداً: إنكم وما تعبدون من دون الله من أصنام وقود جهنم أنتم لها واردون. لو كانت هذه التماثيل آلهة حقاً ما دخل عابدوها النار لأنها تخلّصهم منها، فلما دخلوها دلّ على بطلانها، وكل فيها خالدون، لهم فيها أنين شديد من العذاب، وهم فيها لا يسمعون لكثرة الأنين. ولما قال ابن الزِّبعرى: إن كنا وآلهتنا في جهنم فالملائكة وعيسى والعزير معنا لأنهم عُبدوا، نزل: إن الذين سبقت لهم منا الحسنى، ممن عُبد بغير رضاه وكان يعبدنا ويتقرّب إلينا، أولئك عن جهنم مبعدون، لا يسمعون حسّ صوتها، وهم في الجنة فيما اشتهت أنفسهم خالدون، لا يحزنهم الفزع الأكبر عند قيامهم من قبورهم، وتتلقّاهم الملائكة بالتهنئة: هذا يومكم الذي كنتم توعدون. يوم يطوي الجبار السماء بيمينه كطيّ الصحيفة، كما بدأنا أول خلق نعيده، فيخرج الناس حفاة عراة غرلاً، وعداً علينا إنا كنا فاعلين.", "h": ["تقرير التوحيد والنبوة والبعث والجزاء.", "من عُبد من دون الله بأمره أو برضاه سيكون هو ومن عبده وقوداً لجهنم، ومن لم يأمر ولم يرض فلا يدخل النار مع من عبده، بل العابد له وحده في النار.", "بيان عظمة الله وقدرته، إذ يطوي السماء بيمينه، والأرض في قبضته يوم القيامة.", "بعث الناس حفاة عراة غرلاً لم يُنزع منهم شيء ولا غلفة الذكر، إنجازاً لوعد الله في قوله: «كما بدأكم تعودون»."], "k": "«لا يحزنهم الفزع الأكبر»… أمان ذلك اليوم يُشترى اليوم؛ فبماذا أشتريه؟"}, {"lbl": "الآيات ١٠٥ – ١١٢", "q": "وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّـٰلِحُونَ ﴿١٠٥﴾ إِنَّ فِي هَٰذَا لَبَلَٰغٗا لِّقَوۡمٍ عَٰبِدِينَ ﴿١٠٦﴾ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ ﴿١٠٧﴾ قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ ﴿١٠٨﴾ فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَآءٖۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ أَم بَعِيدٞ مَّا تُوعَدُونَ ﴿١٠٩﴾ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ ﴿١١٠﴾ وَإِنۡ أَدۡرِي لَعَلَّهُۥ فِتۡنَةٞ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينٖ ﴿١١١﴾ قَٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ ﴿١١٢﴾", "w": [["ولقد كتبنا في الزبور", "في الكتب التي أنزلنا كصحف إبراهيم والتوراة والإنجيل والقرآن."], ["من بعد الذكر", "من بعد أن كتبنا ذلك في الذكر الذي هو اللوح المحفوظ."], ["أن الأرض", "أرض الجنة."], ["عبادي الصالحون", "أهل الإيمان والعمل الصالح من سائر الأمم من أتباع الرسل."], ["إن في هذا لبلاغاً", "إن في القرآن لكفاية وبلغة لدخول الجنة."], ["لقوم عابدين", "مطيعين لله ورسوله."], ["رحمة للعالمين", "للإنس والجن: فالمؤمنون يدخلون الجنة، والكافرون ينجون من عذاب الاستئصال الذي كان يصيب الأمم السابقة."], ["فهل أنتم مسلمون", "أسلموا، فالاستفهام للأمر."], ["آذنتكم على سواء", "أعلمتكم أنا وأنتم على سواء أنه لا تلاقي بيننا."], ["وإن أدري", "وما أدري."], ["فتنة لكم", "اختبار لكم."], ["على ما تصفون", "من الكذب من أن النبي ساحر وأن الله اتخذ ولداً."]], "m": "يخبر تعالى بوعده الذي كتبه في كتبه المنزلة بعد كتابته في اللوح المحفوظ: أن أرض الجنة يرثها عباده الصالحون. إن في هذا القرآن لكفاية لمن كان من العابدين لله بأداء فرائضه واجتناب نواهيه في الوصول إلى رضوانه والجنة. وما أرسلناك إلا رحمة للعالمين، إنسهم وجنّهم، مؤمنهم وكافرهم: فالمؤمنون باتباعه يدخلون الجنة، والكافرون يأمنون من عذاب الإبادة الذي كان ينزل بالأمم المكذّبة. قل: إنما يوحى إليّ أنما إلهكم إله واحد، فهل أنتم مسلمون له قلوبكم ووجوهكم؟ فإن أعرضوا فقل: أعلمتكم أنا وأنتم على سواء أنه لا تلاقي بيننا، وما أدري أقريب أم بعيد ما توعدون من العذاب، إنه يعلم طعنكم العلني في الإسلام، ويعلم ما تكتمون من عداوة، وما أدري لعل تأخير العذاب عنكم اختبار لعلكم تتوبون، أو متاع لكم إلى آجالكم. قال: رب احكم بيني وبين قومي المكذّبين بالحق، بنصري عليهم أو بإنزال نقمتك بهم، وربنا الرحمن المستعان على إبطال ما تصفون من الولد والشركاء والسحر والكذب.", "h": ["المؤمنون المتقون، وهم الصالحون، هم ورثة الجنة دار النعيم المقيم.", "في القرآن الكريم البلغة الكافية لمن آمن به وعمل بما فيه، بتحقيق ما يصبو إليه من سعادة الدار الآخرة.", "بيان فضل النبي ﷺ وكرامته على ربه، حيث جعله رحمة للعالمين.", "وجوب المفاصلة بين أهل الشرك وأهل التوحيد.", "وجوب الاستعانة بالله على كل ما يواجه العبد من صعاب وأتعاب."], "k": "«وما أرسلناك إلا رحمة للعالمين»… أتّبع نبي الرحمة؛ فهل أكون رحمة لمن حولي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 233;
insert into public.tdb_cards(topic, i, body) select 233, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٢ – ٩٧", "q": "إِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ ﴿٩٢﴾ وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ ﴿٩٣﴾ فَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا كُفۡرَانَ لِسَعۡيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ ﴿٩٤﴾ وَحَرَٰمٌ عَلَىٰ قَرۡيَةٍ أَهۡلَكۡنَٰهَآ أَنَّهُمۡ لَا يَرۡجِعُونَ ﴿٩٥﴾ حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبٖ يَنسِلُونَ ﴿٩٦﴾ وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةٖ مِّنۡ هَٰذَا بَلۡ كُنَّا ظَٰلِمِينَ ﴿٩٧﴾", "w": [["هذه أمتكم", "ملّتكم، وهي الإسلام، ملة واحدة من عهد آدم إلى العهد المحمدي."], ["وأنا ربكم فاعبدون", "أنا إلهكم الحق، خلقتكم ورزقتكم، فاعبدوني ولا تعبدوا معي غيري."], ["وتقطّعوا أمرهم بينهم", "تفرّقوا في دينهم فأصبح لكل فرقة دين كاليهودية والنصرانية والمجوسية."], ["كل إلينا راجعون", "كل فرقة راجعة إلينا وسوف نجزيها بكسبها."], ["فلا كفران لسعيه", "لا نكران ولا جحود لعمله، بل يُجزى به وافياً."], ["وإنا له كاتبون", "إذ الكرام الكاتبون يكتبون أعمال العباد."], ["وحرام", "ممتنع."], ["يأجوج ومأجوج", "قبيلتان وراء سدّهما الذي سيُفتح عند قرب الساعة."], ["حدب", "مرتفع من الأرض."], ["ينسلون", "يسرعون المشي."], ["الوعد الحق", "يوم القيامة."], ["في غفلة من هذا", "من يوم القيامة وما فيه من أحداث."]], "m": "بعد ذكر أولئك الأنبياء قال تعالى للناس كلهم: إن هذه ملّتكم ملة واحدة من أول الرسل إلى خاتمهم، وهي الإسلام القائم على الإخلاص لله في العبادة، وأنا ربكم فاعبدون. وينعى على الناس تقطيعهم الإسلام إلى ملل شتى ونحل، كل إلينا راجعون فنجزيهم بما كسبوا. فمن يعمل من الصالحات المشروعة وهو مؤمن فلا جحود لعمله، بل يجزى به كاملاً، والملائكة تكتب أعماله بأمرنا. وممتنع على أهل قرية أهلكهم الله بذنوبهم أنهم لا يرجعون إليه يوم القيامة، بل يرجعون للحساب، وطريق رجوعهم: حتى إذا فُتح سدّ يأجوج ومأجوج، وهو من علامات الساعة الكبرى، وهم من كل مرتفع يسرعون يخرّبون، واقترب يوم الدين، فإذا أبصار الذين كفروا شاخصة بعد قيامهم من قبورهم يقولون متحسّرين: يا ويلنا، قد كنا في غفلة من هذا في الدنيا، بل كنا ظالمين، فاعترفوا حيث لا ينفع الاعتراف.", "h": ["وحدة الدين، وكون الإسلام هو دين البشرية كافة، لأنه قائم على أساس توحيد الله تعالى في عبادته التي شرعها ليُعبد بها.", "بيان ما حدث للبشرية من تمزيق الدين بينها بحسب الأهواء والأطماع والأغراض.", "وعد الله لأهل الإيمان والعمل الصالح بالجزاء الحسن، وهو الجنة.", "إذا قُضي بهلاك أمة تعذّرت عليها التوبة، وأمة يهلكها الله لا تعود إلى الحياة الدنيا بحال، والبشرية عائدة إلى ربها لحسابها وجزائها يوم القيامة."], "k": "«فمن يعمل من الصالحات وهو مؤمن فلا كفران لسعيه»… لا يضيع عمل صالح؛ فلأعمل ولو لم يره أحد."}, {"lbl": "الآيات ٩٨ – ١٠٤", "q": "إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ ﴿٩٨﴾ لَوۡ كَانَ هَـٰٓؤُلَآءِ ءَالِهَةٗ مَّا وَرَدُوهَاۖ وَكُلّٞ فِيهَا خَٰلِدُونَ ﴿٩٩﴾ لَهُمۡ فِيهَا زَفِيرٞ وَهُمۡ فِيهَا لَا يَسۡمَعُونَ ﴿١٠٠﴾ إِنَّ ٱلَّذِينَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ أُوْلَـٰٓئِكَ عَنۡهَا مُبۡعَدُونَ ﴿١٠١﴾ لَا يَسۡمَعُونَ حَسِيسَهَاۖ وَهُمۡ فِي مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَٰلِدُونَ ﴿١٠٢﴾ لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ هَٰذَا يَوۡمُكُمُ ٱلَّذِي كُنتُمۡ تُوعَدُونَ ﴿١٠٣﴾ يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ ﴿١٠٤﴾", "w": [["وما تعبدون من دون الله", "من الأوثان والأصنام."], ["حصب جهنم", "ما توقد به جهنم."], ["لو كان هؤلاء آلهة", "الأوثان التي يعبدها المشركون من قريش."], ["ما وردوها", "لحالوا بين عابديهم ودخول النار لو كانوا آلهة قادرين."], ["وكل فيها خالدون", "العابدون من الناس والمعبودون الباطلون."], ["لهم فيها زفير", "لأهل النار فيها أنين وتنفّس شديد."], ["سبقت لهم منا الحسنى", "كتب الله تعالى أزلاً أنهم أهل الجنة."], ["حسيسها", "حسّ صوتها."], ["لا يحزنهم الفزع الأكبر", "عند نفخة البعث، فإنهم يقومون من قبورهم آمنين."], ["كطيّ السجل للكتب", "يطوي الجبار سبحانه السماء طيّ الصحيفة."], ["كما بدأنا أول خلق نعيده", "يبعث الناس من قبورهم حفاة عراة غرلاً كما وُلدوا."]], "m": "يقول تعالى لمشركي قريش متوعّداً: إنكم وما تعبدون من دون الله من أصنام وقود جهنم أنتم لها واردون. لو كانت هذه التماثيل آلهة حقاً ما دخل عابدوها النار لأنها تخلّصهم منها، فلما دخلوها دلّ على بطلانها، وكل فيها خالدون، لهم فيها أنين شديد من العذاب، وهم فيها لا يسمعون لكثرة الأنين. ولما قال ابن الزِّبعرى: إن كنا وآلهتنا في جهنم فالملائكة وعيسى والعزير معنا لأنهم عُبدوا، نزل: إن الذين سبقت لهم منا الحسنى، ممن عُبد بغير رضاه وكان يعبدنا ويتقرّب إلينا، أولئك عن جهنم مبعدون، لا يسمعون حسّ صوتها، وهم في الجنة فيما اشتهت أنفسهم خالدون، لا يحزنهم الفزع الأكبر عند قيامهم من قبورهم، وتتلقّاهم الملائكة بالتهنئة: هذا يومكم الذي كنتم توعدون. يوم يطوي الجبار السماء بيمينه كطيّ الصحيفة، كما بدأنا أول خلق نعيده، فيخرج الناس حفاة عراة غرلاً، وعداً علينا إنا كنا فاعلين.", "h": ["تقرير التوحيد والنبوة والبعث والجزاء.", "من عُبد من دون الله بأمره أو برضاه سيكون هو ومن عبده وقوداً لجهنم، ومن لم يأمر ولم يرض فلا يدخل النار مع من عبده، بل العابد له وحده في النار.", "بيان عظمة الله وقدرته، إذ يطوي السماء بيمينه، والأرض في قبضته يوم القيامة.", "بعث الناس حفاة عراة غرلاً لم يُنزع منهم شيء ولا غلفة الذكر، إنجازاً لوعد الله في قوله: «كما بدأكم تعودون»."], "k": "«لا يحزنهم الفزع الأكبر»… أمان ذلك اليوم يُشترى اليوم؛ فبماذا أشتريه؟"}, {"lbl": "الآيات ١٠٥ – ١١٢", "q": "وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّـٰلِحُونَ ﴿١٠٥﴾ إِنَّ فِي هَٰذَا لَبَلَٰغٗا لِّقَوۡمٍ عَٰبِدِينَ ﴿١٠٦﴾ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ ﴿١٠٧﴾ قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ ﴿١٠٨﴾ فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَآءٖۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ أَم بَعِيدٞ مَّا تُوعَدُونَ ﴿١٠٩﴾ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ ﴿١١٠﴾ وَإِنۡ أَدۡرِي لَعَلَّهُۥ فِتۡنَةٞ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينٖ ﴿١١١﴾ قَٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ ﴿١١٢﴾", "w": [["ولقد كتبنا في الزبور", "في الكتب التي أنزلنا كصحف إبراهيم والتوراة والإنجيل والقرآن."], ["من بعد الذكر", "من بعد أن كتبنا ذلك في الذكر الذي هو اللوح المحفوظ."], ["أن الأرض", "أرض الجنة."], ["عبادي الصالحون", "أهل الإيمان والعمل الصالح من سائر الأمم من أتباع الرسل."], ["إن في هذا لبلاغاً", "إن في القرآن لكفاية وبلغة لدخول الجنة."], ["لقوم عابدين", "مطيعين لله ورسوله."], ["رحمة للعالمين", "للإنس والجن: فالمؤمنون يدخلون الجنة، والكافرون ينجون من عذاب الاستئصال الذي كان يصيب الأمم السابقة."], ["فهل أنتم مسلمون", "أسلموا، فالاستفهام للأمر."], ["آذنتكم على سواء", "أعلمتكم أنا وأنتم على سواء أنه لا تلاقي بيننا."], ["وإن أدري", "وما أدري."], ["فتنة لكم", "اختبار لكم."], ["على ما تصفون", "من الكذب من أن النبي ساحر وأن الله اتخذ ولداً."]], "m": "يخبر تعالى بوعده الذي كتبه في كتبه المنزلة بعد كتابته في اللوح المحفوظ: أن أرض الجنة يرثها عباده الصالحون. إن في هذا القرآن لكفاية لمن كان من العابدين لله بأداء فرائضه واجتناب نواهيه في الوصول إلى رضوانه والجنة. وما أرسلناك إلا رحمة للعالمين، إنسهم وجنّهم، مؤمنهم وكافرهم: فالمؤمنون باتباعه يدخلون الجنة، والكافرون يأمنون من عذاب الإبادة الذي كان ينزل بالأمم المكذّبة. قل: إنما يوحى إليّ أنما إلهكم إله واحد، فهل أنتم مسلمون له قلوبكم ووجوهكم؟ فإن أعرضوا فقل: أعلمتكم أنا وأنتم على سواء أنه لا تلاقي بيننا، وما أدري أقريب أم بعيد ما توعدون من العذاب، إنه يعلم طعنكم العلني في الإسلام، ويعلم ما تكتمون من عداوة، وما أدري لعل تأخير العذاب عنكم اختبار لعلكم تتوبون، أو متاع لكم إلى آجالكم. قال: رب احكم بيني وبين قومي المكذّبين بالحق، بنصري عليهم أو بإنزال نقمتك بهم، وربنا الرحمن المستعان على إبطال ما تصفون من الولد والشركاء والسحر والكذب.", "h": ["المؤمنون المتقون، وهم الصالحون، هم ورثة الجنة دار النعيم المقيم.", "في القرآن الكريم البلغة الكافية لمن آمن به وعمل بما فيه، بتحقيق ما يصبو إليه من سعادة الدار الآخرة.", "بيان فضل النبي ﷺ وكرامته على ربه، حيث جعله رحمة للعالمين.", "وجوب المفاصلة بين أهل الشرك وأهل التوحيد.", "وجوب الاستعانة بالله على كل ما يواجه العبد من صعاب وأتعاب."], "k": "«وما أرسلناك إلا رحمة للعالمين»… أتّبع نبي الرحمة؛ فهل أكون رحمة لمن حولي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (234, 22, 1, 7, 'سورة الحج ١ – ٧', '«يا أيها الناس اتقوا ربكم إن زلزلة الساعة شيء عظيم»، و«إن كنتم في ريب من البعث فإنا خلقناكم من تراب»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 234) = $j$[{"lbl": "الآيات ١ – ٤", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمٞ ﴿١﴾ يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ ﴿٢﴾ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ شَيۡطَٰنٖ مَّرِيدٖ ﴿٣﴾ كُتِبَ عَلَيۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ ﴿٤﴾", "w": [["اتقوا ربكم", "اتقوا عذاب ربكم بالإيمان والتقوى."], ["إن زلزلة الساعة", "زلزلة الأرض عند مجيء الساعة."], ["تذهل كل مرضعة", "من شدة الهول والخوف تنسى رضيعها وتغفل عنه."], ["وتضع كل ذات حمل حملها", "تُسقط الحوامل ما في بطونهن من الخوف والفزع."], ["سكارى وما هم بسكارى", "ذاهلون فاقدون رشدهم وصوابهم كالسكارى، وما هم بسكارى من شراب."], ["يجادل في الله بغير علم", "يقول: إن الملائكة بنات الله، وإن الله لا يحيي الموتى."], ["شيطان مريد", "متجرّد من كل خير لا خير فيه البتة."], ["كُتب عليه أنه من تولاه", "قُضي فيه أن من اتبعه يضلّه عن الحق."]], "m": "بعد ذلك البيان في سورة الأنبياء نادى تعالى بالخطاب العام الذي يشمل العرب والعجم والكافر والمؤمن، في فاتحة سورة الحج التي نزل بعضها بمكة وبعضها بالمدينة: يا أيها الناس اتقوا عذاب ربكم بطاعته، فآمنوا به وبرسوله وأطيعوهما. إن زلزلة الساعة شيء عظيم، فكيف بالعذاب الذي يقع فيها؟ يوم ترونها تنسى المرضع رضيعها، وتُسقط الحامل حملها من شدة الفزع، وترى الناس فاقدين لعقولهم كالسكارى وما هم بسكارى من شراب، ولكن عذاب الله شديد فخافوه. ومن الناس، كالنضر بن الحارث وأمثاله، من يجادل في الله بغير علم بجلاله وشرائعه، فينسب له الولد، وينكر الرسالة والبعث، ويتبع في جداله كل شيطان متجرّد من الخير، قُضي فيه أن من تولّاه بالطاعة أضلّه عن الحق ويهديه إلى عذاب السعير.", "h": ["تقرير عقيدة البعث والجزاء بذكر أحوالهما وأهوالهما.", "حرمة الجدال بالباطل لإدحاض الحق وإبطاله.", "حرمة الكلام في ذات الله وصفاته بغير علم من وحي إلهي أو كلام نبوي صحيح.", "موالاة الشياطين واتباعهم يفضي بالموالي المتابع لهم إلى جهنم وعذاب السعير."], "k": "«تذهل كل مرضعة عما أرضعت»… هول تنسى فيه الأم رضيعها؛ فما الذي يشغلني عن الاستعداد له؟"}, {"lbl": "الآيات ٥ – ٧", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ ﴿٥﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٦﴾ وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٞ لَّا رَيۡبَ فِيهَا وَأَنَّ ٱللَّهَ يَبۡعَثُ مَن فِي ٱلۡقُبُورِ ﴿٧﴾", "w": [["في ريب من البعث", "الريب: الشك مع اضطراب النفس، والبعث: الحياة بعد الموت."], ["من نطفة", "قطرة المني."], ["علقة", "قطعة دم متجمّد تتحوّل إليه النطفة."], ["مضغة", "قطعة لحم قدر ما يمضغ المرء تتحوّل العلقة إليها."], ["مخلّقة وغير مخلّقة", "مصوّرة خلقاً تاماً، وغير مصوّرة، وهي السقط."], ["لنبيّن لكم", "قدرتنا على ما نشاء، ونعرّفكم بابتداء خلقكم."], ["ونقرّ في الأرحام ما نشاء", "نبقي في الرحم من نريد له البقاء إلى نهاية مدة الحمل ثم نخرجه طفلاً سوياً."], ["لتبلغوا أشدّكم", "كمال أبدانكم وتمام عقولكم."], ["إلى أرذل العمر", "سن الشيخوخة والهرم."], ["لكيلا يعلم من بعد علم شيئاً", "فيصير كالطفل في معارفه."], ["اهتزّت وربت", "تحرّكت بالنبات وارتفعت تربتها."], ["زوج بهيج", "نوع من النبات جميل المنظر."], ["ذلك بأن الله هو الحق", "الإله الحق الذي لا إله سواه."], ["يبعث من في القبور", "يحييهم ويخرجهم من قبورهم أحياء."]], "m": "لما كان الكفر بالبعث هو العائق عن الطاعة نادى الناس ليعرض عليهم أدلته العقلية: يا أيها الناس، إن كنتم في شك وحيرة من البعث فإنا خلقنا أصلكم آدم من تراب، ثم خلقناكم من نطفة، ثم من علقة، ثم من مضغة، فإن شاء الله جعلها طفلاً، وإن لم يشأ أسقطها، لنبيّن لكم قدرتنا وعلمنا فتعظّمونا وتطيعونا، ونقرّ في الأرحام ما نشاء إلى ميعاد الولادة، ثم نخرجكم أطفالاً لا علم لكم، ثم لتبلغوا تمام نماء أبدانكم وعقولكم، ومنكم من يُتوفّى قبل ذلك، ومنكم من يُردّ إلى أرذل العمر فيهرم ويصير كالطفل لا يعلم شيئاً بعد علم. فالذي خلقهم هكذا قادر على إحيائهم بعد موتهم، إذ ليست الإعادة بأصعب من البداية. ودليل آخر: ترى الأرض هامدة ميتة، فإذا أنزلنا عليها الماء تحرّكت وارتفعت تربتها وأنبتت من كل نوع جميل، فالتربة كالرحم، والمطر كماء الفحل، وخروج الزرع حياً كخروج الولد. ذلك بأن الله هو الإله الحق وما عداه باطل، وأنه يحيي الموتى، وأنه على كل شيء قدير، وأن الساعة آتية لا ريب فيها، وأن الله يبعث من في القبور.", "h": ["تقرير عقيدة البعث الآخر والجزاء على الأعمال يوم القيامة.", "بيان تطوّر خلق الإنسان ودلالته على قدرة الله وعلمه وحكمته.", "الاستدلال على الغائب بالحاضر المحسوس، وهذا من شأن العقلاء، فإن المعادلات الحسابية والجبرية قائمة على مثل ذلك.", "تقرير عقيدة التوحيد، وهي أنه لا إله إلا الله وأن محمداً رسول الله ﷺ."], "k": "«ومنكم من يُردّ إلى أرذل العمر»… قوّتي اليوم ستذبل؛ فبماذا أعمرها قبل أن تذهب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 234;
insert into public.tdb_cards(topic, i, body) select 234, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمٞ ﴿١﴾ يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ ﴿٢﴾ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ شَيۡطَٰنٖ مَّرِيدٖ ﴿٣﴾ كُتِبَ عَلَيۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ ﴿٤﴾", "w": [["اتقوا ربكم", "اتقوا عذاب ربكم بالإيمان والتقوى."], ["إن زلزلة الساعة", "زلزلة الأرض عند مجيء الساعة."], ["تذهل كل مرضعة", "من شدة الهول والخوف تنسى رضيعها وتغفل عنه."], ["وتضع كل ذات حمل حملها", "تُسقط الحوامل ما في بطونهن من الخوف والفزع."], ["سكارى وما هم بسكارى", "ذاهلون فاقدون رشدهم وصوابهم كالسكارى، وما هم بسكارى من شراب."], ["يجادل في الله بغير علم", "يقول: إن الملائكة بنات الله، وإن الله لا يحيي الموتى."], ["شيطان مريد", "متجرّد من كل خير لا خير فيه البتة."], ["كُتب عليه أنه من تولاه", "قُضي فيه أن من اتبعه يضلّه عن الحق."]], "m": "بعد ذلك البيان في سورة الأنبياء نادى تعالى بالخطاب العام الذي يشمل العرب والعجم والكافر والمؤمن، في فاتحة سورة الحج التي نزل بعضها بمكة وبعضها بالمدينة: يا أيها الناس اتقوا عذاب ربكم بطاعته، فآمنوا به وبرسوله وأطيعوهما. إن زلزلة الساعة شيء عظيم، فكيف بالعذاب الذي يقع فيها؟ يوم ترونها تنسى المرضع رضيعها، وتُسقط الحامل حملها من شدة الفزع، وترى الناس فاقدين لعقولهم كالسكارى وما هم بسكارى من شراب، ولكن عذاب الله شديد فخافوه. ومن الناس، كالنضر بن الحارث وأمثاله، من يجادل في الله بغير علم بجلاله وشرائعه، فينسب له الولد، وينكر الرسالة والبعث، ويتبع في جداله كل شيطان متجرّد من الخير، قُضي فيه أن من تولّاه بالطاعة أضلّه عن الحق ويهديه إلى عذاب السعير.", "h": ["تقرير عقيدة البعث والجزاء بذكر أحوالهما وأهوالهما.", "حرمة الجدال بالباطل لإدحاض الحق وإبطاله.", "حرمة الكلام في ذات الله وصفاته بغير علم من وحي إلهي أو كلام نبوي صحيح.", "موالاة الشياطين واتباعهم يفضي بالموالي المتابع لهم إلى جهنم وعذاب السعير."], "k": "«تذهل كل مرضعة عما أرضعت»… هول تنسى فيه الأم رضيعها؛ فما الذي يشغلني عن الاستعداد له؟"}, {"lbl": "الآيات ٥ – ٧", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ ﴿٥﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٦﴾ وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٞ لَّا رَيۡبَ فِيهَا وَأَنَّ ٱللَّهَ يَبۡعَثُ مَن فِي ٱلۡقُبُورِ ﴿٧﴾", "w": [["في ريب من البعث", "الريب: الشك مع اضطراب النفس، والبعث: الحياة بعد الموت."], ["من نطفة", "قطرة المني."], ["علقة", "قطعة دم متجمّد تتحوّل إليه النطفة."], ["مضغة", "قطعة لحم قدر ما يمضغ المرء تتحوّل العلقة إليها."], ["مخلّقة وغير مخلّقة", "مصوّرة خلقاً تاماً، وغير مصوّرة، وهي السقط."], ["لنبيّن لكم", "قدرتنا على ما نشاء، ونعرّفكم بابتداء خلقكم."], ["ونقرّ في الأرحام ما نشاء", "نبقي في الرحم من نريد له البقاء إلى نهاية مدة الحمل ثم نخرجه طفلاً سوياً."], ["لتبلغوا أشدّكم", "كمال أبدانكم وتمام عقولكم."], ["إلى أرذل العمر", "سن الشيخوخة والهرم."], ["لكيلا يعلم من بعد علم شيئاً", "فيصير كالطفل في معارفه."], ["اهتزّت وربت", "تحرّكت بالنبات وارتفعت تربتها."], ["زوج بهيج", "نوع من النبات جميل المنظر."], ["ذلك بأن الله هو الحق", "الإله الحق الذي لا إله سواه."], ["يبعث من في القبور", "يحييهم ويخرجهم من قبورهم أحياء."]], "m": "لما كان الكفر بالبعث هو العائق عن الطاعة نادى الناس ليعرض عليهم أدلته العقلية: يا أيها الناس، إن كنتم في شك وحيرة من البعث فإنا خلقنا أصلكم آدم من تراب، ثم خلقناكم من نطفة، ثم من علقة، ثم من مضغة، فإن شاء الله جعلها طفلاً، وإن لم يشأ أسقطها، لنبيّن لكم قدرتنا وعلمنا فتعظّمونا وتطيعونا، ونقرّ في الأرحام ما نشاء إلى ميعاد الولادة، ثم نخرجكم أطفالاً لا علم لكم، ثم لتبلغوا تمام نماء أبدانكم وعقولكم، ومنكم من يُتوفّى قبل ذلك، ومنكم من يُردّ إلى أرذل العمر فيهرم ويصير كالطفل لا يعلم شيئاً بعد علم. فالذي خلقهم هكذا قادر على إحيائهم بعد موتهم، إذ ليست الإعادة بأصعب من البداية. ودليل آخر: ترى الأرض هامدة ميتة، فإذا أنزلنا عليها الماء تحرّكت وارتفعت تربتها وأنبتت من كل نوع جميل، فالتربة كالرحم، والمطر كماء الفحل، وخروج الزرع حياً كخروج الولد. ذلك بأن الله هو الإله الحق وما عداه باطل، وأنه يحيي الموتى، وأنه على كل شيء قدير، وأن الساعة آتية لا ريب فيها، وأن الله يبعث من في القبور.", "h": ["تقرير عقيدة البعث الآخر والجزاء على الأعمال يوم القيامة.", "بيان تطوّر خلق الإنسان ودلالته على قدرة الله وعلمه وحكمته.", "الاستدلال على الغائب بالحاضر المحسوس، وهذا من شأن العقلاء، فإن المعادلات الحسابية والجبرية قائمة على مثل ذلك.", "تقرير عقيدة التوحيد، وهي أنه لا إله إلا الله وأن محمداً رسول الله ﷺ."], "k": "«ومنكم من يُردّ إلى أرذل العمر»… قوّتي اليوم ستذبل؛ فبماذا أعمرها قبل أن تذهب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (235, 22, 8, 18, 'سورة الحج ٨ – ١٨', '«ومن الناس من يعبد الله على حرف»، و«إن الله يفصل بينهم يوم القيامة»، و«ألم تر أن الله يسجد له من في السماوات ومن في الأرض»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 235) = $j$[{"lbl": "الآيات ٨ – ١٣", "q": "وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ ﴿٨﴾ ثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَنُذِيقُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ عَذَابَ ٱلۡحَرِيقِ ﴿٩﴾ ذَٰلِكَ بِمَا قَدَّمَتۡ يَدَاكَ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ ﴿١٠﴾ وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ ﴿١١﴾ يَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ ﴿١٢﴾ يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ ﴿١٣﴾", "w": [["يجادل في الله", "في شأن الله، فينسب إليه ما هو منه براء كالشريك والولد والعجز عن إحياء الموتى."], ["بغير علم", "بدون علم من الله ورسوله."], ["ولا كتاب منير", "ولا كتاب من كتب الله ذي نور يكشف الحقائق."], ["ثاني عطفه", "لاوي عنقه تكبّراً، والعطف: الجانب."], ["له في الدنيا خزي", "وقد أذاقه الله يوم بدر."], ["بظلّام للعبيد", "بذي ظلم للعبيد فيعذّبهم بغير ظلم منهم لأنفسهم."], ["يعبد الله على حرف", "على شك في الإسلام لجهلهم به."], ["اطمأن به", "سكنت نفسه إلى الإسلام ورضي به."], ["وإن أصابته فتنة", "ابتلاء بنقص مال أو مرض في جسم ونحوه."], ["انقلب على وجهه", "رجع عن الإسلام إلى ما كان عليه من الكفر."], ["ما لا يضرّه وما لا ينفعه", "صنماً لا يضرّه إن لم يعبده، ولا ينفعه إن عبده."], ["لبئس المولى", "قبح هذا الناصر من ناصر."], ["ولبئس العشير", "المعاشر، وهو الصاحب الملازم."]], "m": "هذه شخصية ثانية بعد النضر بن الحارث، هي شخصية أبي جهل: ومن الناس من يجادل في الله بالجهل بلا علم من وحي ولا هدى ولا كتاب إلهي منير، يثبت لله الولد والشركاء، يمشي لاوياً عنقه مائلاً إلى جنبه كبراً، لا ليطلب الهدى، بل ليضل غيره عن الإسلام، له في الدنيا خزي، وقد أذاقه الله ذلك يوم بدر، ونذيقه يوم القيامة عذاب الحريق، ويقال له: ذلك بما قدّمت يداك من الشرك والظلم، وأن الله ليس بظلّام للعبيد. وشخصية ثالثة: بعض الأعراب كانوا يدخلون في الإسلام عن شك وطمع لا عن علم واقتناع، فإن أصابهم خير من مال وعافية اطمأنوا إليه، وإن أصابتهم فتنة في نفس أو مال أو ولد ارتدّوا، فخسروا الدنيا والآخرة، ذلك هو الخسران المبين، ولو بقوا على الإسلام لفازوا ولأخلف الله عليهم. يدعو المرتد من دون الله صنماً لا يضرّه لو تركه ولا ينفعه إن عبده، ذلك هو الضلال البعيد، يدعو من ضرّه يوم القيامة أقرب من نفعه إذ يتبرّأ منه، لبئس الناصر ولبئس الصاحب الملازم.", "h": ["قبح جدال الجاهل فيما ليس له به علم.", "ذم الكبر والخيلاء، سواء من كافر أو من مؤمن.", "عدم جدوى عبادة صاحبها شاكّ في نفعها، غير مؤمن بوجوبها ومشروعيتها.", "لا يصح دين مع الشك.", "تقرير التوحيد والتنديد بالشرك والمشركين."], "k": "«فإن أصابه خير اطمأن به وإن أصابته فتنة انقلب على وجهه»… هل عبادتي ثابتة في الضيق كما في السعة؟"}, {"lbl": "الآيات ١٤ – ١٧", "q": "إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ ﴿١٤﴾ مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ فَلۡيَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لۡيَقۡطَعۡ فَلۡيَنظُرۡ هَلۡ يُذۡهِبَنَّ كَيۡدُهُۥ مَا يَغِيظُ ﴿١٥﴾ وَكَذَٰلِكَ أَنزَلۡنَٰهُ ءَايَٰتِۭ بَيِّنَٰتٖ وَأَنَّ ٱللَّهَ يَهۡدِي مَن يُرِيدُ ﴿١٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّـٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿١٧﴾", "w": [["وعملوا الصالحات", "الفرائض والنوافل وأفعال الخير."], ["يفعل ما يريد", "من إكرام المطيع وإهانة العاصي."], ["أن لن ينصره الله", "أي محمداً ﷺ."], ["فليمدد بسبب", "بحبل."], ["إلى السماء", "سقف بيته، وليختنق غيظاً."], ["هل يذهبنّ كيده", "في عدم نصرة النبي ﷺ الذي يغيظه."], ["وكذلك أنزلناه", "مثل إنزالنا تلك الآيات السابقة أنزلنا القرآن."], ["هادوا", "اليهود."], ["والصابئين", "فرقة من النصارى."], ["والمجوس", "عبدة النار والكواكب."], ["على كل شيء شهيد", "عالم به حافظ له."]], "m": "بعد ذكر جزاء الكافرين والمتردّدين أخبر أنه يدخل الذين آمنوا وعملوا الصالحات من الفرائض والنوافل جنات تجري من تحتها الأنهار، إن الله يفعل ما يريد من تعذيب من كفر ورحمة من آمن. من كان يظن أن الله لن ينصر رسوله ودينه فلذا يتردّد ولم يؤمن، كبني أسد وغطفان، فليأت بحبل يربطه في سقف بيته ثم يختنق، ولينظر هل يُذهب كيده هذا ما يغيظه من نصر الله لرسوله؟ وكذلك أنزلنا القرآن آيات واضحات تحمل الهدى لمن آمن بها، وأن الله يهدي من يريد هدايته بتوفيقه للنظر فيعرف الحق. إن الذين آمنوا، واليهود، والصابئين، والنصارى، والمجوس، والذين أشركوا من عبدة الأوثان، إن الله يفصل بينهم يوم القيامة، فيدخل المؤمنين الجنة، وأهل تلك الملل الباطلة النار، فالأديان ستة: واحد للرحمن وخمسة للشيطان، إن الله على كل شيء شهيد، فقد أنزل كتابه وبعث رسوله ورغّب ورهّب.", "h": ["كل الأديان من وحي الشيطان وأهلها خاسرون إلا الإسلام، فهو دين الله الحق، وأهله هم الفائزون، أهله القائمون عليه عقيدة وعبادة وحكماً وقضاءً.", "أن الله ناصر دينه ومكرم أهله، ومن غاظه ذلك ولم يرضه فليختنق.", "تقرير عقيدة البعث والجزاء.", "تقرير إرادة الله ومشيئته، فهو تعالى يفعل ما يشاء ويهدي من يريد."], "k": "«إن الله يفصل بينهم يوم القيامة»… الخلاف سيُفصل فيه هناك؛ فهل أعدّ لنفسي حجة يومها؟"}, {"lbl": "الآية ١٨", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩ ﴿١٨﴾", "w": [["ألم تر", "ألم تر بقلبك فتعلم."], ["يسجد له", "يخضع ويذل له."], ["من في السماوات", "من الملائكة."], ["والدواب", "سائر الحيوانات التي تدب على الأرض."], ["حقّ عليه العذاب", "وجب عليه العذاب فهو واقع به لا بد."], ["فما له من مكرم", "ليس له من يسعده وقد أشقاه الله."]], "m": "يقول تعالى لرسوله: ألم تعلم أن الله يسجد له من في السماوات من الملائكة، ومن في الأرض من الجن، والشمس والقمر والنجوم والجبال والشجر والدواب، وكثير من الناس، وهم المؤمنون المطيعون، وكثير من الناس وجب عليهم العذاب فلا يسجدون سجود عبادة وقربة، أما سجود الخضوع فظلالهم تسجد لله بالصباح والمساء. ومن أراد الله إهانته وإشقاءه فما له من مكرم يرفع العذاب عنه، إن الله يفعل ما يشاء، فالخلق خلقه وهو المتصرّف فيهم، فعلى عباده أن يرجعوا إليه بالتوبة سائلين رحمته مشفقين من عذابه.", "h": ["تقرير ربوبية الله وألوهيته.", "سجود المخلوقات بحسب ذواتها وما أراد الله تعالى منها.", "كل شيء خاضع لله إلا الإنسان، فأكثر أفراده عصاة له متمرّدون عليه، وبذلك استوجبوا العذاب المهين.", "التالي لهذه الآية والمستمع لتلاوته يُسنّ لهم أن يسجدوا لله تعالى إذا بلغوا قوله تعالى: «إن الله يفعل ما يشاء»."], "k": "«وكثير من الناس»… الكون كله ساجد؛ فهل أكون مع الساجدين أم مع من حقّ عليه العذاب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 235;
insert into public.tdb_cards(topic, i, body) select 235, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨ – ١٣", "q": "وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ ﴿٨﴾ ثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَنُذِيقُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ عَذَابَ ٱلۡحَرِيقِ ﴿٩﴾ ذَٰلِكَ بِمَا قَدَّمَتۡ يَدَاكَ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ ﴿١٠﴾ وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ ﴿١١﴾ يَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ ﴿١٢﴾ يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ ﴿١٣﴾", "w": [["يجادل في الله", "في شأن الله، فينسب إليه ما هو منه براء كالشريك والولد والعجز عن إحياء الموتى."], ["بغير علم", "بدون علم من الله ورسوله."], ["ولا كتاب منير", "ولا كتاب من كتب الله ذي نور يكشف الحقائق."], ["ثاني عطفه", "لاوي عنقه تكبّراً، والعطف: الجانب."], ["له في الدنيا خزي", "وقد أذاقه الله يوم بدر."], ["بظلّام للعبيد", "بذي ظلم للعبيد فيعذّبهم بغير ظلم منهم لأنفسهم."], ["يعبد الله على حرف", "على شك في الإسلام لجهلهم به."], ["اطمأن به", "سكنت نفسه إلى الإسلام ورضي به."], ["وإن أصابته فتنة", "ابتلاء بنقص مال أو مرض في جسم ونحوه."], ["انقلب على وجهه", "رجع عن الإسلام إلى ما كان عليه من الكفر."], ["ما لا يضرّه وما لا ينفعه", "صنماً لا يضرّه إن لم يعبده، ولا ينفعه إن عبده."], ["لبئس المولى", "قبح هذا الناصر من ناصر."], ["ولبئس العشير", "المعاشر، وهو الصاحب الملازم."]], "m": "هذه شخصية ثانية بعد النضر بن الحارث، هي شخصية أبي جهل: ومن الناس من يجادل في الله بالجهل بلا علم من وحي ولا هدى ولا كتاب إلهي منير، يثبت لله الولد والشركاء، يمشي لاوياً عنقه مائلاً إلى جنبه كبراً، لا ليطلب الهدى، بل ليضل غيره عن الإسلام، له في الدنيا خزي، وقد أذاقه الله ذلك يوم بدر، ونذيقه يوم القيامة عذاب الحريق، ويقال له: ذلك بما قدّمت يداك من الشرك والظلم، وأن الله ليس بظلّام للعبيد. وشخصية ثالثة: بعض الأعراب كانوا يدخلون في الإسلام عن شك وطمع لا عن علم واقتناع، فإن أصابهم خير من مال وعافية اطمأنوا إليه، وإن أصابتهم فتنة في نفس أو مال أو ولد ارتدّوا، فخسروا الدنيا والآخرة، ذلك هو الخسران المبين، ولو بقوا على الإسلام لفازوا ولأخلف الله عليهم. يدعو المرتد من دون الله صنماً لا يضرّه لو تركه ولا ينفعه إن عبده، ذلك هو الضلال البعيد، يدعو من ضرّه يوم القيامة أقرب من نفعه إذ يتبرّأ منه، لبئس الناصر ولبئس الصاحب الملازم.", "h": ["قبح جدال الجاهل فيما ليس له به علم.", "ذم الكبر والخيلاء، سواء من كافر أو من مؤمن.", "عدم جدوى عبادة صاحبها شاكّ في نفعها، غير مؤمن بوجوبها ومشروعيتها.", "لا يصح دين مع الشك.", "تقرير التوحيد والتنديد بالشرك والمشركين."], "k": "«فإن أصابه خير اطمأن به وإن أصابته فتنة انقلب على وجهه»… هل عبادتي ثابتة في الضيق كما في السعة؟"}, {"lbl": "الآيات ١٤ – ١٧", "q": "إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ ﴿١٤﴾ مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ فَلۡيَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لۡيَقۡطَعۡ فَلۡيَنظُرۡ هَلۡ يُذۡهِبَنَّ كَيۡدُهُۥ مَا يَغِيظُ ﴿١٥﴾ وَكَذَٰلِكَ أَنزَلۡنَٰهُ ءَايَٰتِۭ بَيِّنَٰتٖ وَأَنَّ ٱللَّهَ يَهۡدِي مَن يُرِيدُ ﴿١٦﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّـٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ﴿١٧﴾", "w": [["وعملوا الصالحات", "الفرائض والنوافل وأفعال الخير."], ["يفعل ما يريد", "من إكرام المطيع وإهانة العاصي."], ["أن لن ينصره الله", "أي محمداً ﷺ."], ["فليمدد بسبب", "بحبل."], ["إلى السماء", "سقف بيته، وليختنق غيظاً."], ["هل يذهبنّ كيده", "في عدم نصرة النبي ﷺ الذي يغيظه."], ["وكذلك أنزلناه", "مثل إنزالنا تلك الآيات السابقة أنزلنا القرآن."], ["هادوا", "اليهود."], ["والصابئين", "فرقة من النصارى."], ["والمجوس", "عبدة النار والكواكب."], ["على كل شيء شهيد", "عالم به حافظ له."]], "m": "بعد ذكر جزاء الكافرين والمتردّدين أخبر أنه يدخل الذين آمنوا وعملوا الصالحات من الفرائض والنوافل جنات تجري من تحتها الأنهار، إن الله يفعل ما يريد من تعذيب من كفر ورحمة من آمن. من كان يظن أن الله لن ينصر رسوله ودينه فلذا يتردّد ولم يؤمن، كبني أسد وغطفان، فليأت بحبل يربطه في سقف بيته ثم يختنق، ولينظر هل يُذهب كيده هذا ما يغيظه من نصر الله لرسوله؟ وكذلك أنزلنا القرآن آيات واضحات تحمل الهدى لمن آمن بها، وأن الله يهدي من يريد هدايته بتوفيقه للنظر فيعرف الحق. إن الذين آمنوا، واليهود، والصابئين، والنصارى، والمجوس، والذين أشركوا من عبدة الأوثان، إن الله يفصل بينهم يوم القيامة، فيدخل المؤمنين الجنة، وأهل تلك الملل الباطلة النار، فالأديان ستة: واحد للرحمن وخمسة للشيطان، إن الله على كل شيء شهيد، فقد أنزل كتابه وبعث رسوله ورغّب ورهّب.", "h": ["كل الأديان من وحي الشيطان وأهلها خاسرون إلا الإسلام، فهو دين الله الحق، وأهله هم الفائزون، أهله القائمون عليه عقيدة وعبادة وحكماً وقضاءً.", "أن الله ناصر دينه ومكرم أهله، ومن غاظه ذلك ولم يرضه فليختنق.", "تقرير عقيدة البعث والجزاء.", "تقرير إرادة الله ومشيئته، فهو تعالى يفعل ما يشاء ويهدي من يريد."], "k": "«إن الله يفصل بينهم يوم القيامة»… الخلاف سيُفصل فيه هناك؛ فهل أعدّ لنفسي حجة يومها؟"}, {"lbl": "الآية ١٨", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩ ﴿١٨﴾", "w": [["ألم تر", "ألم تر بقلبك فتعلم."], ["يسجد له", "يخضع ويذل له."], ["من في السماوات", "من الملائكة."], ["والدواب", "سائر الحيوانات التي تدب على الأرض."], ["حقّ عليه العذاب", "وجب عليه العذاب فهو واقع به لا بد."], ["فما له من مكرم", "ليس له من يسعده وقد أشقاه الله."]], "m": "يقول تعالى لرسوله: ألم تعلم أن الله يسجد له من في السماوات من الملائكة، ومن في الأرض من الجن، والشمس والقمر والنجوم والجبال والشجر والدواب، وكثير من الناس، وهم المؤمنون المطيعون، وكثير من الناس وجب عليهم العذاب فلا يسجدون سجود عبادة وقربة، أما سجود الخضوع فظلالهم تسجد لله بالصباح والمساء. ومن أراد الله إهانته وإشقاءه فما له من مكرم يرفع العذاب عنه، إن الله يفعل ما يشاء، فالخلق خلقه وهو المتصرّف فيهم، فعلى عباده أن يرجعوا إليه بالتوبة سائلين رحمته مشفقين من عذابه.", "h": ["تقرير ربوبية الله وألوهيته.", "سجود المخلوقات بحسب ذواتها وما أراد الله تعالى منها.", "كل شيء خاضع لله إلا الإنسان، فأكثر أفراده عصاة له متمرّدون عليه، وبذلك استوجبوا العذاب المهين.", "التالي لهذه الآية والمستمع لتلاوته يُسنّ لهم أن يسجدوا لله تعالى إذا بلغوا قوله تعالى: «إن الله يفعل ما يشاء»."], "k": "«وكثير من الناس»… الكون كله ساجد؛ فهل أكون مع الساجدين أم مع من حقّ عليه العذاب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (236, 22, 19, 29, 'سورة الحج ١٩ – ٢٩', '«هذان خصمان اختصموا في ربهم»، و«ومن يرد فيه بإلحاد بظلم»، و«وأذّن في الناس بالحج يأتوك رجالاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 236) = $j$[{"lbl": "الآيات ١٩ – ٢٤", "q": "۞هَٰذَانِ خَصۡمَانِ ٱخۡتَصَمُواْ فِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابٞ مِّن نَّارٖ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ ﴿١٩﴾ يُصۡهَرُ بِهِۦ مَا فِي بُطُونِهِمۡ وَٱلۡجُلُودُ ﴿٢٠﴾ وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدٖ ﴿٢١﴾ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ﴿٢٢﴾ إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ ﴿٢٣﴾ وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ ﴿٢٤﴾", "w": [["خصمان", "خصم مؤمن وخصم كافر، كل واحد يريد أن يخصم صاحبه."], ["اختصموا في ربهم", "في دينه."], ["قُطّعت لهم ثياب", "فُصّلت لهم ثياب من نار على قدر أجسامهم."], ["يُصهر به ما في بطونهم", "يُذاب بالحميم، وهو الماء الحار، من شحوم وغيرها."], ["مقامع من حديد", "جمع مقمعة، وهي آلة من حديد يُضربون بها."], ["وذوقوا عذاب الحريق", "يقال لهم توبيخاً: ذوقوا عذاب النار."], ["ولؤلؤاً", "أساور من لؤلؤ محلّاة بالذهب."], ["إلى الطيب من القول", "هو شهادة أن لا إله إلا الله."], ["إلى صراط الحميد", "إلى الإسلام، إذ هو طريق الله الموصل إلى رضاه وجنته."]], "m": "هذان خصمان: المسلمون وأهل الشرك والكفر، اختصموا في دين ربهم، كل يدّعي أنه على الحق، ونزلت في الذين تبارزوا يوم بدر: حمزة وعلي وعبيدة بن الحارث، وعتبة وشيبة ابنا ربيعة والوليد بن عتبة، وعمومها يشمل كل خصومة بين أهل الإيمان وأهل الكفر، ويفصل الله بينهم يوم القيامة: فالذين كفروا فُصّلت لهم ثياب من نار، يُصبّ من فوق رءوسهم الماء المتناهي في الحرارة، يُذاب به ما في بطونهم والجلود، ولهم مقامع من حديد يُضربون بها، كلما أرادوا أن يخرجوا منها من غمّ عظيم أُعيدوا فيها، ويقال لهم: ذوقوا عذاب الحريق. وأما الخصم المؤمن فإن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار، يُحلّون فيها أساور من ذهب ولؤلؤاً، ولباسهم فيها حرير، وهُدوا في الدنيا إلى الطيب من القول، لا إله إلا الله وسائر الأذكار وكل كلام طيب، وهُدوا إلى صراط الحميد، الإسلام، بتوفيق ربهم.", "h": ["المؤمن خصم الكافر، والكافر خصم المؤمن، في كل زمان ومكان، والآية نزلت في المبارزين يوم بدر، فنصر الله الخصم المؤمن على الكافر.", "بيان جزاء كل من الكافرين والمؤمنين في الدار الآخرة.", "تقرير عقيدة البعث والجزاء بذكر أحوال الآخرة وما للناس فيها.", "بيان الطيب من القول، وهو كلمة التوحيد وذكر الله تعالى.", "بيان صراط الحميد، وهو الإسلام."], "k": "«وهُدوا إلى الطيب من القول»… كلامي اليوم، كم فيه من الطيب، وكم من غيره؟"}, {"lbl": "الآية ٢٥", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۭ بِظُلۡمٖ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمٖ ﴿٢٥﴾", "w": [["كفروا", "جحدوا توحيد الله وكذّبوا رسوله."], ["ويصدّون عن سبيل الله", "يمنعون الناس من الإسلام ويصرفونهم عنه."], ["والمسجد الحرام", "مكة المكرمة، والمسجد الحرام ضمنها."], ["العاكف", "المقيم بمكة للتعبّد في المسجد الحرام."], ["والباد", "الطارئ على مكة النازح إليها."], ["بإلحاد بظلم", "ميلاً عن الحق ملتبساً بظلم لنفسه أو لغيره."]], "m": "تحمل الآية وعيداً شديداً لكل من كفر بتوحيد الله وكذّب رسوله وصرف الناس عن الإسلام، وعن دخول المسجد الحرام للطواف والإقامة للتعبّد، وهي وإن تناولت المشركين الذين صدّوا رسول الله ﷺ وأصحابه عام الحديبية فإنها عامة في كل من كفر وصدّ إلى يوم القيامة. والمسجد الحرام جعله الله موضع تنسّك لكل من أتاه، المقيم فيه والطارئ عليه سواء في حق الإقامة للتعبّد. ومن يعتزم فيه الميل عن الحق بظلم يرتكبه، كالشرك وسائر الذنوب القاصرة على فاعلها أو المتعدّية إلى غيره، نذقه من عذاب أليم.", "h": ["التنديد بالكفر والصدّ عن سبيل الله والمسجد الحرام والظلم فيه، والوعيد الشديد لفاعل ذلك.", "مكة بلد الله وحرمه، من حق كل مسلم أن يقيم بها للتعبّد والتنسّك ما لم يظلم وينتهك حرمة الحرم بالذنوب والمعاصي، وخاصة الشرك والظلم والضلال.", "عظيم شأن الحرم، حيث يؤاخذ فيه على مجرد العزم على الفعل ولو لم يفعل."], "k": "«ومن يرد فيه بإلحاد بظلم»… مجرد الإرادة يُحاسب عليها هناك؛ فكيف أطهّر نيّتي إذا قصدت البيت؟"}, {"lbl": "الآيات ٢٦ – ٢٩", "q": "وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـٔٗا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ ﴿٢٦﴾ وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ ﴿٢٧﴾ لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ ﴿٢٨﴾ ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ وَلۡيُوفُواْ نُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ ﴿٢٩﴾", "w": [["وإذ بوّأنا لإبراهيم", "اذكر إذ أنزلنا إبراهيم بمكة مبيّنين له مكان البيت."], ["أن لا تشرك بي شيئاً", "وصّيناه ألا تشرك بي شيئاً."], ["وطهّر بيتي", "نظّفه من أقذار الشرك وأنجاس المشركين."], ["وأذّن في الناس بالحج", "أعلن في الناس بأعلى صوتك."], ["رجالاً وعلى كل ضامر", "مشاة وركباناً على ضوامر الإبل."], ["فجّ عميق", "طريق واسع بعيد الغور في قارّات الأرض."], ["في أيام معلومات", "هي أيام التشريق."], ["بهيمة الأنعام", "الإبل والبقر والغنم، إذ لا يصح الهدي إلا منها."], ["البائس الفقير", "من اشتد به الفقر."], ["ليقضوا تفثهم", "ليزيلوا أوساخهم المترتبة على مدة الإحرام."], ["وليوفوا نذورهم", "بأن يذبحوا وينحروا ما نذروه لله من هدايا وضحايا."]], "m": "اذكر لقومك المنتسبين إلى إبراهيم زوراً، وهو موحّد وهم مشركون، كيف أنزله ربه مكان البيت ليبنيه، ووصّاه ألا يشرك به شيئاً، وأن يطهّره من الأقذار الحسية والمعنوية للطائفين والقائمين والركّع السجود، ليذكر قومك هذا وقد نصبوا حول البيت الأصنام وصدّوك عنه. وأذّن في الناس: أيها الناس، إن ربكم قد بنى لكم بيتاً فحجّوه، ففعل، فأسمع الله صوته من كتب لهم الحج، عليك النداء وعلينا البلاغ، يأتوك مشاة وعلى كل ناقة مهزولة يأتين من كل طريق بعيد، ليشهدوا منافع لهم دينية كمغفرة الذنوب واستجابة الدعاء وتعلّم الدين، ودنيوية كربح التجارة، ويذكروا اسم الله شاكرين في أيام الحج بالصلاة والذكر والدعاء، وعلى ما رزقهم من بهيمة الأنعام عند النحر والذبح: بسم الله والله أكبر، فكلوا منها، وأطعموا البائس الفقير، ثم ليزيلوا الشعث والوسخ الذي لازمهم مدة الإحرام، وليوفوا ما نذروه من هدي، وليطوفوا طواف الإفاضة بالبيت العتيق، وهو ركن الحج لا يصح إلا بعد الوقوف بعرفة ورمي جمرة العقبة.", "h": ["وجوب بناء البيت وإعلائه كلما سقط وتهدّم، ووجوب تطهيره من كل ما يؤذي الطائفين والعاكفين من الشرك والمعاصي، ومن الأقذار كالأبوال والدماء ونحوها.", "مشروعية فتح مكاتب للدعاية للحج.", "جواز الاتجار أثناء إقامته في الحج.", "وجوب شكر الله تعالى وذكره.", "جواز الأكل من الهدي ومن ذبائح التطوع، بل استحبابه.", "وجوب الحلق أو التقصير بعد رمي جمرة العقبة.", "وجوب الوفاء بالنذور الشرعية، أما النذور للأولياء فهي شرك ولا يجوز الوفاء بها.", "تقرير طواف الإفاضة وبيان زمنه، وهو بعد الوقوف بعرفة ورمي جمرة العقبة."], "k": "«وأذّن في الناس بالحج يأتوك رجالاً»… نداء إبراهيم يبلغني الآن؛ فهل نويت الإجابة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 236;
insert into public.tdb_cards(topic, i, body) select 236, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٩ – ٢٤", "q": "۞هَٰذَانِ خَصۡمَانِ ٱخۡتَصَمُواْ فِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابٞ مِّن نَّارٖ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ ﴿١٩﴾ يُصۡهَرُ بِهِۦ مَا فِي بُطُونِهِمۡ وَٱلۡجُلُودُ ﴿٢٠﴾ وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدٖ ﴿٢١﴾ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ﴿٢٢﴾ إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ ﴿٢٣﴾ وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ ﴿٢٤﴾", "w": [["خصمان", "خصم مؤمن وخصم كافر، كل واحد يريد أن يخصم صاحبه."], ["اختصموا في ربهم", "في دينه."], ["قُطّعت لهم ثياب", "فُصّلت لهم ثياب من نار على قدر أجسامهم."], ["يُصهر به ما في بطونهم", "يُذاب بالحميم، وهو الماء الحار، من شحوم وغيرها."], ["مقامع من حديد", "جمع مقمعة، وهي آلة من حديد يُضربون بها."], ["وذوقوا عذاب الحريق", "يقال لهم توبيخاً: ذوقوا عذاب النار."], ["ولؤلؤاً", "أساور من لؤلؤ محلّاة بالذهب."], ["إلى الطيب من القول", "هو شهادة أن لا إله إلا الله."], ["إلى صراط الحميد", "إلى الإسلام، إذ هو طريق الله الموصل إلى رضاه وجنته."]], "m": "هذان خصمان: المسلمون وأهل الشرك والكفر، اختصموا في دين ربهم، كل يدّعي أنه على الحق، ونزلت في الذين تبارزوا يوم بدر: حمزة وعلي وعبيدة بن الحارث، وعتبة وشيبة ابنا ربيعة والوليد بن عتبة، وعمومها يشمل كل خصومة بين أهل الإيمان وأهل الكفر، ويفصل الله بينهم يوم القيامة: فالذين كفروا فُصّلت لهم ثياب من نار، يُصبّ من فوق رءوسهم الماء المتناهي في الحرارة، يُذاب به ما في بطونهم والجلود، ولهم مقامع من حديد يُضربون بها، كلما أرادوا أن يخرجوا منها من غمّ عظيم أُعيدوا فيها، ويقال لهم: ذوقوا عذاب الحريق. وأما الخصم المؤمن فإن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار، يُحلّون فيها أساور من ذهب ولؤلؤاً، ولباسهم فيها حرير، وهُدوا في الدنيا إلى الطيب من القول، لا إله إلا الله وسائر الأذكار وكل كلام طيب، وهُدوا إلى صراط الحميد، الإسلام، بتوفيق ربهم.", "h": ["المؤمن خصم الكافر، والكافر خصم المؤمن، في كل زمان ومكان، والآية نزلت في المبارزين يوم بدر، فنصر الله الخصم المؤمن على الكافر.", "بيان جزاء كل من الكافرين والمؤمنين في الدار الآخرة.", "تقرير عقيدة البعث والجزاء بذكر أحوال الآخرة وما للناس فيها.", "بيان الطيب من القول، وهو كلمة التوحيد وذكر الله تعالى.", "بيان صراط الحميد، وهو الإسلام."], "k": "«وهُدوا إلى الطيب من القول»… كلامي اليوم، كم فيه من الطيب، وكم من غيره؟"}, {"lbl": "الآية ٢٥", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۭ بِظُلۡمٖ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمٖ ﴿٢٥﴾", "w": [["كفروا", "جحدوا توحيد الله وكذّبوا رسوله."], ["ويصدّون عن سبيل الله", "يمنعون الناس من الإسلام ويصرفونهم عنه."], ["والمسجد الحرام", "مكة المكرمة، والمسجد الحرام ضمنها."], ["العاكف", "المقيم بمكة للتعبّد في المسجد الحرام."], ["والباد", "الطارئ على مكة النازح إليها."], ["بإلحاد بظلم", "ميلاً عن الحق ملتبساً بظلم لنفسه أو لغيره."]], "m": "تحمل الآية وعيداً شديداً لكل من كفر بتوحيد الله وكذّب رسوله وصرف الناس عن الإسلام، وعن دخول المسجد الحرام للطواف والإقامة للتعبّد، وهي وإن تناولت المشركين الذين صدّوا رسول الله ﷺ وأصحابه عام الحديبية فإنها عامة في كل من كفر وصدّ إلى يوم القيامة. والمسجد الحرام جعله الله موضع تنسّك لكل من أتاه، المقيم فيه والطارئ عليه سواء في حق الإقامة للتعبّد. ومن يعتزم فيه الميل عن الحق بظلم يرتكبه، كالشرك وسائر الذنوب القاصرة على فاعلها أو المتعدّية إلى غيره، نذقه من عذاب أليم.", "h": ["التنديد بالكفر والصدّ عن سبيل الله والمسجد الحرام والظلم فيه، والوعيد الشديد لفاعل ذلك.", "مكة بلد الله وحرمه، من حق كل مسلم أن يقيم بها للتعبّد والتنسّك ما لم يظلم وينتهك حرمة الحرم بالذنوب والمعاصي، وخاصة الشرك والظلم والضلال.", "عظيم شأن الحرم، حيث يؤاخذ فيه على مجرد العزم على الفعل ولو لم يفعل."], "k": "«ومن يرد فيه بإلحاد بظلم»… مجرد الإرادة يُحاسب عليها هناك؛ فكيف أطهّر نيّتي إذا قصدت البيت؟"}, {"lbl": "الآيات ٢٦ – ٢٩", "q": "وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـٔٗا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ ﴿٢٦﴾ وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ ﴿٢٧﴾ لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ ﴿٢٨﴾ ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ وَلۡيُوفُواْ نُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ ﴿٢٩﴾", "w": [["وإذ بوّأنا لإبراهيم", "اذكر إذ أنزلنا إبراهيم بمكة مبيّنين له مكان البيت."], ["أن لا تشرك بي شيئاً", "وصّيناه ألا تشرك بي شيئاً."], ["وطهّر بيتي", "نظّفه من أقذار الشرك وأنجاس المشركين."], ["وأذّن في الناس بالحج", "أعلن في الناس بأعلى صوتك."], ["رجالاً وعلى كل ضامر", "مشاة وركباناً على ضوامر الإبل."], ["فجّ عميق", "طريق واسع بعيد الغور في قارّات الأرض."], ["في أيام معلومات", "هي أيام التشريق."], ["بهيمة الأنعام", "الإبل والبقر والغنم، إذ لا يصح الهدي إلا منها."], ["البائس الفقير", "من اشتد به الفقر."], ["ليقضوا تفثهم", "ليزيلوا أوساخهم المترتبة على مدة الإحرام."], ["وليوفوا نذورهم", "بأن يذبحوا وينحروا ما نذروه لله من هدايا وضحايا."]], "m": "اذكر لقومك المنتسبين إلى إبراهيم زوراً، وهو موحّد وهم مشركون، كيف أنزله ربه مكان البيت ليبنيه، ووصّاه ألا يشرك به شيئاً، وأن يطهّره من الأقذار الحسية والمعنوية للطائفين والقائمين والركّع السجود، ليذكر قومك هذا وقد نصبوا حول البيت الأصنام وصدّوك عنه. وأذّن في الناس: أيها الناس، إن ربكم قد بنى لكم بيتاً فحجّوه، ففعل، فأسمع الله صوته من كتب لهم الحج، عليك النداء وعلينا البلاغ، يأتوك مشاة وعلى كل ناقة مهزولة يأتين من كل طريق بعيد، ليشهدوا منافع لهم دينية كمغفرة الذنوب واستجابة الدعاء وتعلّم الدين، ودنيوية كربح التجارة، ويذكروا اسم الله شاكرين في أيام الحج بالصلاة والذكر والدعاء، وعلى ما رزقهم من بهيمة الأنعام عند النحر والذبح: بسم الله والله أكبر، فكلوا منها، وأطعموا البائس الفقير، ثم ليزيلوا الشعث والوسخ الذي لازمهم مدة الإحرام، وليوفوا ما نذروه من هدي، وليطوفوا طواف الإفاضة بالبيت العتيق، وهو ركن الحج لا يصح إلا بعد الوقوف بعرفة ورمي جمرة العقبة.", "h": ["وجوب بناء البيت وإعلائه كلما سقط وتهدّم، ووجوب تطهيره من كل ما يؤذي الطائفين والعاكفين من الشرك والمعاصي، ومن الأقذار كالأبوال والدماء ونحوها.", "مشروعية فتح مكاتب للدعاية للحج.", "جواز الاتجار أثناء إقامته في الحج.", "وجوب شكر الله تعالى وذكره.", "جواز الأكل من الهدي ومن ذبائح التطوع، بل استحبابه.", "وجوب الحلق أو التقصير بعد رمي جمرة العقبة.", "وجوب الوفاء بالنذور الشرعية، أما النذور للأولياء فهي شرك ولا يجوز الوفاء بها.", "تقرير طواف الإفاضة وبيان زمنه، وهو بعد الوقوف بعرفة ورمي جمرة العقبة."], "k": "«وأذّن في الناس بالحج يأتوك رجالاً»… نداء إبراهيم يبلغني الآن؛ فهل نويت الإجابة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (237, 22, 30, 37, 'سورة الحج ٣٠ – ٣٧', '«ومن يعظّم حرمات الله… ومن يعظّم شعائر الله فإنها من تقوى القلوب»، و«لن ينال الله لحومها ولا دماؤها ولكن يناله التقوى منكم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 237) = $j$[{"lbl": "الآيات ٣٠ – ٣٣", "q": "ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ ﴿٣٠﴾ حُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ ﴿٣١﴾ ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَـٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ ﴿٣٢﴾ لَكُمۡ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ مَحِلُّهَآ إِلَى ٱلۡبَيۡتِ ٱلۡعَتِيقِ ﴿٣٣﴾", "w": [["ذلك", "الأمر ذلك الذي ذكرت."], ["حرمات الله", "جمع حرمة، ما حرّم الله انتهاكه من قول أو فعل."], ["فهو خير له عند ربه", "خير في الآخرة لمن يعظّم حرمات الله فلا ينتهكها."], ["إلا ما يتلى عليكم", "تحريمه في سور البقرة والمائدة والأنعام."], ["فاجتنبوا الرجس من الأوثان", "اجتنبوا عبادة الأوثان."], ["واجتنبوا قول الزور", "الكذب، وأعظمه ما كان على الله، والشرك، وشهادة الزور."], ["حنفاء لله", "موحّدين له مائلين عن كل دين إلى الإسلام."], ["خرّ", "سقط."], ["فتخطفه الطير", "تأخذه بسرعة."], ["شعائر الله", "أعلام دينه، وهي هنا البُدن، بأن تُختار الحسنة السمينة منها."], ["فإنها من تقوى القلوب", "تعظيمها ناشئ من تقوى القلوب."], ["لكم فيها منافع", "منها ركوبها والحمل عليها بما لا يضرّها وشرب لبنها."], ["إلى أجل مسمى", "وقت معيّن، وهو نحرها بالحرم أيام التشريق."], ["ثم محلها إلى البيت", "عند البيت العتيق، وهو مكة والحرم."]], "m": "ما زال السياق في مناسك الحج: الأمر ذلك الذي علمتم من قضاء التفث والنحر والذبح، ومن يعظّم حرمات الله فلا ينتهكها فهو خير له عند ربه. وأُحلّت لكم الإبل والبقر والغنم أكلاً وانتفاعاً إلا ما يتلى عليكم تحريمه من الميتة والدم ولحم الخنزير وما أُهلّ لغير الله به. فاجتنبوا عبادة الأوثان فإنها رجس، واجتنبوا قول الزور، الكذب مطلقاً وشهادة الزور، وأعظمه الكذب على الله بنسبة الولد والشريك إليه، كونوا موحّدين لله مائلين عن كل الأديان إلى دينه غير مشركين به. ومن يشرك بالله فكأنما سقط من السماء بعد أن رُفع إليها، فتخطفه الطير بسرعة كما تفعل البازات بصغار الطيور، أو تهوي به الريح في مكان بعيد فلا يُعثر عليه أبداً، هذا شأن المشرك بعد أن كان في سماء الطهر بسلامة فطرته فانتكس في حمأة الشرك. ذلك، ومن يعظّم أعلام دينه من المناسك، وبخاصة البُدن التي تُهدى للحرم باستحسانها واستسمانها، فإن ذلك من تقوى القلوب، والرسول ﷺ يشير إلى صدره ويقول: «التقوى ها هنا» ثلاثاً. لكم في الهدايا منافع تركبونها وتحملون عليها ما لا يضرّها وتشربون من ألبانها إلى وقت نحرها، ثم محلّها عند البيت العتيق.", "h": ["وجوب تعظيم حرمات الله لما فيها من الخير العظيم.", "تقرير حلّ بهيمة الأنعام بشرط ذكر اسم الله عند ذبحها أو نحرها.", "حرمة قول الزور وشهادة الزور، وفي الأثر: «عُدلت شهادة الزور الشرك بالله».", "وجوب ترك عبادة الأوثان، ووجوب البعد عنها وترك كل ما يمتّ إليها بصلة.", "بيان عقوبة الشرك وخسران المشرك.", "تعظيم شعائر الله، وخاصة البُدن، من تقوى قلوب أصحابها.", "جواز الانتفاع بالبُدن الهدايا بركوبها وشرب لبنها والحمل عليها إلى غاية نحرها."], "k": "«فإنها من تقوى القلوب»… كيف أعظّم شعائر الله في صلاتي وصيامي وأضحيتي؟"}, {"lbl": "الآيات ٣٤ – ٣٧", "q": "وَلِكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكٗا لِّيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ ﴿٣٤﴾ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّـٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿٣٥﴾ وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَـٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرٞۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٣٦﴾ لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ ﴿٣٧﴾", "w": [["منسكاً", "ذبائح من بهيمة الأنعام يتقرّبون بها إلى الله، ومكان الذبح يقال له منسك."], ["فله أسلموا", "انقادوا ظاهراً وباطناً لأمره ونهيه."], ["وبشّر المخبتين", "المطيعين المتواضعين الخاشعين."], ["وجلت قلوبهم", "خافت من الله أن تكون قصّرت في طاعته."], ["والبُدن", "جمع بدنة، وهي ما يُساق للحرم من إبل وبقر ليُذبح تقرّباً إلى الله."], ["من شعائر الله", "من أعلام دينه ومظاهر عبادته."], ["صوافّ", "جمع صافّة، وهي القائمة على ثلاث معقولة اليد اليسرى."], ["فإذا وجبت جنوبها", "سقطت على جنوبها على الأرض لا روح فيها."], ["القانع والمعترّ", "القانع: السائل، والمعترّ: الذي يتعرّض للرجل ولا يسأله حياءً."], ["كذلك سخّرناها", "مثل هذا التسخير سخّرناها لكم لتركبوا وتحملوا."], ["لعلكم تشكرون", "لأجل أن تشكروا الله بحمده وطاعته."], ["لن ينال الله لحومها", "لا يُرفع إلى الله لحم ولا دم، ولكن تقواه بفعل ما أمر به وترك ما نهى عنه."], ["لتكبّروا الله على ما هداكم", "تقولون: الله أكبر بعد الصلوات الخمس أيام التشريق شكراً له على هدايته."], ["وبشّر المحسنين", "الذين يريدون بالعبادة وجه الله وحده ويؤدّونها على الوجه المشروع."]], "m": "ولكل أمة من الأمم السابقة من أهل الإيمان جعلنا مكان نسك يتعبّدوننا فيه وذبح قربان يتقرّبون به إلينا، ليذكروا اسم الله على ما رزقهم من بهيمة الأنعام بقولهم: بسم الله والله أكبر، فمعبودكم معبود واحد فله أسلموا، وبشّر المخبتين: الذين إذا ذُكر الله خافت قلوبهم شعوراً بالتقصير، والصابرين على ما أصابهم من البلاء لا يتسخّطون، والمقيمي الصلاة في أوقاتها في بيوت الله مع المؤمنين، ومما رزقناهم ينفقون قلّ أو كثر. والبُدن من الإبل والبقر مما يُهدى إلى الحرم جعلناها من شعائر ديننا، لكم فيها أجر كبير، إذ ما تقرّب متقرّب يوم الأضحى بأفضل من دم يهرقه، فقولوا عند نحرها: بسم الله والله أكبر، وهي قائمة على ثلاث معقولة اليسرى، فإذا سقطت على جنوبها ميتة فكلوا منها وأطعموا السائل والمتعرّض الذي لا يسأل حياءً، كذلك سخّرناها لكم لعلكم تشكروننا بالطاعة والذكر. لن يُرفع إليه لحم ولا دم، ولكن يُرفع إليه التقوى بالإخلاص وفعل الواجب والمندوب وترك الحرام والمكروه، كذلك سخّرها لكم لتكبّروا الله على ما هداكم عند النحر وأداء المناسك وعقب الصلوات أيام التشريق، وبشّر المحسنين الذين عبدوا الله بما شرع متّبعين هدي نبيّه ﷺ.", "h": ["ذبح القربان مشروع في سائر الأديان الإلهية، وهو دليل على أنه لا إله إلا الله، إذ وحدة التشريع تدل على وحدة المشرّع.", "سرّ مشروعية ذبح القربان هو أن يُذكر الله تعالى، ولذا وجب ذكر اسم الله عند الذبح والنحر بلفظ: بسم الله والله أكبر.", "تعريف المخبتين أهل البشارة السارة برضوان الله وجواره الكريم.", "بيان كيفية نحر البُدن، وحرمة الأخذ منها قبل موتها وخروج روحها.", "الندب إلى الأكل من الهدايا، ووجوب إطعام الفقراء والمساكين منها.", "وجوب شكر الله على كل إنعام.", "مشروعية التكبير عند أداء المناسك كرمي الجمار وذبح ما يُذبح، وبعد الصلوات الخمس أيام التشريق.", "فضيلة الإحسان، وفوز المحسنين ببشرى على لسان رسول الله ﷺ."], "k": "«لن ينال الله لحومها ولا دماؤها ولكن يناله التقوى منكم»… ما الذي يُرفع من عبادتي حقاً: صورتها أم تقواها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 237;
insert into public.tdb_cards(topic, i, body) select 237, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٠ – ٣٣", "q": "ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ ﴿٣٠﴾ حُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ ﴿٣١﴾ ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَـٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ ﴿٣٢﴾ لَكُمۡ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ مَحِلُّهَآ إِلَى ٱلۡبَيۡتِ ٱلۡعَتِيقِ ﴿٣٣﴾", "w": [["ذلك", "الأمر ذلك الذي ذكرت."], ["حرمات الله", "جمع حرمة، ما حرّم الله انتهاكه من قول أو فعل."], ["فهو خير له عند ربه", "خير في الآخرة لمن يعظّم حرمات الله فلا ينتهكها."], ["إلا ما يتلى عليكم", "تحريمه في سور البقرة والمائدة والأنعام."], ["فاجتنبوا الرجس من الأوثان", "اجتنبوا عبادة الأوثان."], ["واجتنبوا قول الزور", "الكذب، وأعظمه ما كان على الله، والشرك، وشهادة الزور."], ["حنفاء لله", "موحّدين له مائلين عن كل دين إلى الإسلام."], ["خرّ", "سقط."], ["فتخطفه الطير", "تأخذه بسرعة."], ["شعائر الله", "أعلام دينه، وهي هنا البُدن، بأن تُختار الحسنة السمينة منها."], ["فإنها من تقوى القلوب", "تعظيمها ناشئ من تقوى القلوب."], ["لكم فيها منافع", "منها ركوبها والحمل عليها بما لا يضرّها وشرب لبنها."], ["إلى أجل مسمى", "وقت معيّن، وهو نحرها بالحرم أيام التشريق."], ["ثم محلها إلى البيت", "عند البيت العتيق، وهو مكة والحرم."]], "m": "ما زال السياق في مناسك الحج: الأمر ذلك الذي علمتم من قضاء التفث والنحر والذبح، ومن يعظّم حرمات الله فلا ينتهكها فهو خير له عند ربه. وأُحلّت لكم الإبل والبقر والغنم أكلاً وانتفاعاً إلا ما يتلى عليكم تحريمه من الميتة والدم ولحم الخنزير وما أُهلّ لغير الله به. فاجتنبوا عبادة الأوثان فإنها رجس، واجتنبوا قول الزور، الكذب مطلقاً وشهادة الزور، وأعظمه الكذب على الله بنسبة الولد والشريك إليه، كونوا موحّدين لله مائلين عن كل الأديان إلى دينه غير مشركين به. ومن يشرك بالله فكأنما سقط من السماء بعد أن رُفع إليها، فتخطفه الطير بسرعة كما تفعل البازات بصغار الطيور، أو تهوي به الريح في مكان بعيد فلا يُعثر عليه أبداً، هذا شأن المشرك بعد أن كان في سماء الطهر بسلامة فطرته فانتكس في حمأة الشرك. ذلك، ومن يعظّم أعلام دينه من المناسك، وبخاصة البُدن التي تُهدى للحرم باستحسانها واستسمانها، فإن ذلك من تقوى القلوب، والرسول ﷺ يشير إلى صدره ويقول: «التقوى ها هنا» ثلاثاً. لكم في الهدايا منافع تركبونها وتحملون عليها ما لا يضرّها وتشربون من ألبانها إلى وقت نحرها، ثم محلّها عند البيت العتيق.", "h": ["وجوب تعظيم حرمات الله لما فيها من الخير العظيم.", "تقرير حلّ بهيمة الأنعام بشرط ذكر اسم الله عند ذبحها أو نحرها.", "حرمة قول الزور وشهادة الزور، وفي الأثر: «عُدلت شهادة الزور الشرك بالله».", "وجوب ترك عبادة الأوثان، ووجوب البعد عنها وترك كل ما يمتّ إليها بصلة.", "بيان عقوبة الشرك وخسران المشرك.", "تعظيم شعائر الله، وخاصة البُدن، من تقوى قلوب أصحابها.", "جواز الانتفاع بالبُدن الهدايا بركوبها وشرب لبنها والحمل عليها إلى غاية نحرها."], "k": "«فإنها من تقوى القلوب»… كيف أعظّم شعائر الله في صلاتي وصيامي وأضحيتي؟"}, {"lbl": "الآيات ٣٤ – ٣٧", "q": "وَلِكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكٗا لِّيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ ﴿٣٤﴾ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّـٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ﴿٣٥﴾ وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَـٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرٞۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٣٦﴾ لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ ﴿٣٧﴾", "w": [["منسكاً", "ذبائح من بهيمة الأنعام يتقرّبون بها إلى الله، ومكان الذبح يقال له منسك."], ["فله أسلموا", "انقادوا ظاهراً وباطناً لأمره ونهيه."], ["وبشّر المخبتين", "المطيعين المتواضعين الخاشعين."], ["وجلت قلوبهم", "خافت من الله أن تكون قصّرت في طاعته."], ["والبُدن", "جمع بدنة، وهي ما يُساق للحرم من إبل وبقر ليُذبح تقرّباً إلى الله."], ["من شعائر الله", "من أعلام دينه ومظاهر عبادته."], ["صوافّ", "جمع صافّة، وهي القائمة على ثلاث معقولة اليد اليسرى."], ["فإذا وجبت جنوبها", "سقطت على جنوبها على الأرض لا روح فيها."], ["القانع والمعترّ", "القانع: السائل، والمعترّ: الذي يتعرّض للرجل ولا يسأله حياءً."], ["كذلك سخّرناها", "مثل هذا التسخير سخّرناها لكم لتركبوا وتحملوا."], ["لعلكم تشكرون", "لأجل أن تشكروا الله بحمده وطاعته."], ["لن ينال الله لحومها", "لا يُرفع إلى الله لحم ولا دم، ولكن تقواه بفعل ما أمر به وترك ما نهى عنه."], ["لتكبّروا الله على ما هداكم", "تقولون: الله أكبر بعد الصلوات الخمس أيام التشريق شكراً له على هدايته."], ["وبشّر المحسنين", "الذين يريدون بالعبادة وجه الله وحده ويؤدّونها على الوجه المشروع."]], "m": "ولكل أمة من الأمم السابقة من أهل الإيمان جعلنا مكان نسك يتعبّدوننا فيه وذبح قربان يتقرّبون به إلينا، ليذكروا اسم الله على ما رزقهم من بهيمة الأنعام بقولهم: بسم الله والله أكبر، فمعبودكم معبود واحد فله أسلموا، وبشّر المخبتين: الذين إذا ذُكر الله خافت قلوبهم شعوراً بالتقصير، والصابرين على ما أصابهم من البلاء لا يتسخّطون، والمقيمي الصلاة في أوقاتها في بيوت الله مع المؤمنين، ومما رزقناهم ينفقون قلّ أو كثر. والبُدن من الإبل والبقر مما يُهدى إلى الحرم جعلناها من شعائر ديننا، لكم فيها أجر كبير، إذ ما تقرّب متقرّب يوم الأضحى بأفضل من دم يهرقه، فقولوا عند نحرها: بسم الله والله أكبر، وهي قائمة على ثلاث معقولة اليسرى، فإذا سقطت على جنوبها ميتة فكلوا منها وأطعموا السائل والمتعرّض الذي لا يسأل حياءً، كذلك سخّرناها لكم لعلكم تشكروننا بالطاعة والذكر. لن يُرفع إليه لحم ولا دم، ولكن يُرفع إليه التقوى بالإخلاص وفعل الواجب والمندوب وترك الحرام والمكروه، كذلك سخّرها لكم لتكبّروا الله على ما هداكم عند النحر وأداء المناسك وعقب الصلوات أيام التشريق، وبشّر المحسنين الذين عبدوا الله بما شرع متّبعين هدي نبيّه ﷺ.", "h": ["ذبح القربان مشروع في سائر الأديان الإلهية، وهو دليل على أنه لا إله إلا الله، إذ وحدة التشريع تدل على وحدة المشرّع.", "سرّ مشروعية ذبح القربان هو أن يُذكر الله تعالى، ولذا وجب ذكر اسم الله عند الذبح والنحر بلفظ: بسم الله والله أكبر.", "تعريف المخبتين أهل البشارة السارة برضوان الله وجواره الكريم.", "بيان كيفية نحر البُدن، وحرمة الأخذ منها قبل موتها وخروج روحها.", "الندب إلى الأكل من الهدايا، ووجوب إطعام الفقراء والمساكين منها.", "وجوب شكر الله على كل إنعام.", "مشروعية التكبير عند أداء المناسك كرمي الجمار وذبح ما يُذبح، وبعد الصلوات الخمس أيام التشريق.", "فضيلة الإحسان، وفوز المحسنين ببشرى على لسان رسول الله ﷺ."], "k": "«لن ينال الله لحومها ولا دماؤها ولكن يناله التقوى منكم»… ما الذي يُرفع من عبادتي حقاً: صورتها أم تقواها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (238, 22, 38, 46, 'سورة الحج ٣٨ – ٤٦', '«إن الله يدافع عن الذين آمنوا»، و«أُذن للذين يقاتَلون بأنهم ظُلموا»، و«فإنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 238) = $j$[{"lbl": "الآيات ٣٨ – ٤١", "q": "۞إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٖ كَفُورٍ ﴿٣٨﴾ أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِيرٌ ﴿٣٩﴾ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ ﴿٤٠﴾ ٱلَّذِينَ إِن مَّكَّنَّـٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ﴿٤١﴾", "w": [["يدافع", "يدفع غوائل المشركين وما يكيدون به المؤمنين."], ["خوّان", "خائن لأمانته وعهوده."], ["كفور", "جحود لربه وكتابه ورسوله ونعمه عليه."], ["بأنهم ظُلموا", "بسبب ظلم المشركين لهم."], ["بغير حق", "بغير ما يستوجب إخراجهم من ديارهم."], ["إلا أن يقولوا ربنا الله", "إلا قولهم: ربنا الله، وهل قول الحق يسوّغ الإخراج؟"], ["صوامع وبيع", "معابد الرهبان وكنائس النصارى."], ["وصلوات", "معابد اليهود."], ["ومساجد", "بيوت الصلاة للمسلمين."], ["من ينصره", "ينصر دينه وعباده المؤمنين."], ["قوي عزيز", "قادر على ما يريد، عزيز لا يُمانع فيما يريد."], ["إن مكّنّاهم في الأرض", "نصرناهم على عدوّهم وجعلنا لهم السلطة."], ["ولله عاقبة الأمور", "آخر أمور الخلق مردّها إلى الله الذي يثيب ويعاقب."]], "m": "ما زال السياق في إرشاد المؤمنين: إن الله يدفع عن الذين آمنوا غوائل المشركين ويحميهم من كيدهم، إن الله لا يحب كل خائن لأماناته وعهوده كافر بربه، وهم المشركون الذين صدّوا عن المسجد الحرام، ومقابله أنه يحب كل مؤمن صادق محافظ على عهوده، ومن أحبّه دافع عنه. أُذن للذين يقاتلهم المشركون في قتال أعدائهم بعدما كانوا ممنوعين لحكمة، وهذه أول آية في القرآن تحمل الإذن بالقتال، وإن الله على نصرهم لقدير، الذين أُخرجوا من ديارهم بلا موجب إلا قولهم: ربنا الله. ولولا أن الله يدفع بأهل الإيمان أهل الكفر لتغلّب أهل الكفر فهدموا صوامع الرهبان وكنائس النصارى ومعابد اليهود ومساجد يُذكر فيها اسم الله كثيراً. ولينصرنّ الله من ينصره، من يقاتل من أجل أن يُعبد الله وحده في الأرض، إن الله لقوي عزيز. الذين إن ملّكناهم بعد قهر أعدائهم أقاموا الصلاة، وآتوا الزكاة، وأمروا بالمعروف، ونهوا عن المنكر من الشرك والمعاصي، هؤلاء الأحقّ بنصر الله، ولله مردّ كل أمر يوم القيامة، فليُراقب في السر والعلن.", "h": ["وعد الله الصادق بالدفاع عن المؤمنين الصادقين في إيمانهم.", "كره الله تعالى لأهل الكفر والخيانة.", "مشروعية القتال لإعلاء كلمة الله، بأن يُعبد وحده ولا يُضطهد أولياؤه.", "بيان سرّ الإذن بالجهاد، ونصرة الله لأوليائه الذين يقاتلون من أجله.", "بيان أسس الدولة التي ورّث الله أهلها البلاد وملّكهم فيها، وهي: إقام الصلاة، وإيتاء الزكاة، والأمر بالمعروف، والنهي عن المنكر."], "k": "«الذين إن مكّنّاهم في الأرض أقاموا الصلاة…»… ما مُكّنت فيه من بيت وعمل، هل أقمت فيه هذه الأربع؟"}, {"lbl": "الآيات ٤٢ – ٤٦", "q": "وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَثَمُودُ ﴿٤٢﴾ وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ لُوطٖ ﴿٤٣﴾ وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ ﴿٤٤﴾ فَكَأَيِّن مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةٞ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرٖ مُّعَطَّلَةٖ وَقَصۡرٖ مَّشِيدٍ ﴿٤٥﴾ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبٞ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ ﴿٤٦﴾", "w": [["وإن يكذّبوك", "إن يكذّبك قومك فقد كذّبت قبلهم قوم نوح، فلا تأسَ."], ["وأصحاب مدين", "قوم شعيب ﵇."], ["وكُذّب موسى", "كذّبه فرعون وآله الأقباط."], ["فأمليت للكافرين", "أمهلتهم فلم أعجّل العقوبة لهم."], ["ثم أخذتهم", "بالعذاب المستأصل لهم."], ["فكيف كان نكير", "كيف كان إنكاري عليهم تكذيبهم؟ أكان واقعاً موقعه؟ نعم، فالاستفهام للتقرير."], ["فهي خاوية على عروشها", "ساقطة على سقوفها."], ["وبئر معطّلة", "متروكة لا يُستخرج منها ماء لموت أهلها."], ["وقصر مشيد", "مرتفع مجصّص بالجص."], ["فإنها لا تعمى الأبصار", "الخلل ليس في أبصارهم، ولكن في قلوبهم، حيث أعماها الهوى وأفسدتها الشهوة والتقليد."]], "m": "ما زال السياق في دعوة قريش، فبعد الإذن بالقتال قال لرسوله مسلّياً: وإن يكذّبوك فيما جئت به فلا تحزن، فقد كذّبت قبلهم قوم نوح وعاد وثمود، وقوم إبراهيم وقوم لوط، وأصحاب مدين، وكُذّب موسى مع ما أوتي من الآيات، فأمهلتهم ومددت لهم، حتى إذا بلغوا غاية الكفر أخذتهم أخذ عزيز مقتدر، فكيف كان إنكاري عليهم؟ كان واقعاً موقعه. وكم من قرية عظيمة بأهلها ومالها وسلطانها أهلكناها وهي ظالمة بالشرك، فهي ساقطة على سقوفها، وكم من بئر عذبة كانت سقيا لهم فهي الآن معطّلة، وكم من قصر رفيع مجصّص مات أهله وتركوه. أفلم يسر المكذّبون في البلاد ليقفوا على آثار الهالكين، فتكون لهم قلوب حية يعقلون بها خطابنا، أو آذان يسمعون بها نداء النصح؟ فما لهم من عيون مبصرة بلا قلوب واعية لا ينفع، فإنها لا تعمى الأبصار، ولكن تعمى القلوب التي في الصدور.", "h": ["تكذيب الرسل والدعاة إلى الحق والخير سنة مطّردة في البشر، لها عواملها، من أبرزها التقليد، والمحافظة على المنافع المادية، وظلمات القلب الناشئة عن الشرك والمعاصي.", "مظاهر قدرة الله تعالى في إهلاك الأمم الظالمة بعد الإمهال لهم والإعذار.", "مشروعية طلب العبر وتصيّدها من آثار الهالكين.", "العبرة بالبصيرة القلبية لا بالبصر، فعلى العبد أن يحافظ على بصيرته أكثر من المحافظة على عينيه، بأن يتجنّب مدمّرات القلوب من الكذب والخرافات والكبر والعجب والحب والبغض في غير الله."], "k": "«ولكن تعمى القلوب التي في الصدور»… عيناي سليمتان؛ فكيف حال بصيرة قلبي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 238;
insert into public.tdb_cards(topic, i, body) select 238, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٨ – ٤١", "q": "۞إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٖ كَفُورٍ ﴿٣٨﴾ أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِيرٌ ﴿٣٩﴾ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ ﴿٤٠﴾ ٱلَّذِينَ إِن مَّكَّنَّـٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ﴿٤١﴾", "w": [["يدافع", "يدفع غوائل المشركين وما يكيدون به المؤمنين."], ["خوّان", "خائن لأمانته وعهوده."], ["كفور", "جحود لربه وكتابه ورسوله ونعمه عليه."], ["بأنهم ظُلموا", "بسبب ظلم المشركين لهم."], ["بغير حق", "بغير ما يستوجب إخراجهم من ديارهم."], ["إلا أن يقولوا ربنا الله", "إلا قولهم: ربنا الله، وهل قول الحق يسوّغ الإخراج؟"], ["صوامع وبيع", "معابد الرهبان وكنائس النصارى."], ["وصلوات", "معابد اليهود."], ["ومساجد", "بيوت الصلاة للمسلمين."], ["من ينصره", "ينصر دينه وعباده المؤمنين."], ["قوي عزيز", "قادر على ما يريد، عزيز لا يُمانع فيما يريد."], ["إن مكّنّاهم في الأرض", "نصرناهم على عدوّهم وجعلنا لهم السلطة."], ["ولله عاقبة الأمور", "آخر أمور الخلق مردّها إلى الله الذي يثيب ويعاقب."]], "m": "ما زال السياق في إرشاد المؤمنين: إن الله يدفع عن الذين آمنوا غوائل المشركين ويحميهم من كيدهم، إن الله لا يحب كل خائن لأماناته وعهوده كافر بربه، وهم المشركون الذين صدّوا عن المسجد الحرام، ومقابله أنه يحب كل مؤمن صادق محافظ على عهوده، ومن أحبّه دافع عنه. أُذن للذين يقاتلهم المشركون في قتال أعدائهم بعدما كانوا ممنوعين لحكمة، وهذه أول آية في القرآن تحمل الإذن بالقتال، وإن الله على نصرهم لقدير، الذين أُخرجوا من ديارهم بلا موجب إلا قولهم: ربنا الله. ولولا أن الله يدفع بأهل الإيمان أهل الكفر لتغلّب أهل الكفر فهدموا صوامع الرهبان وكنائس النصارى ومعابد اليهود ومساجد يُذكر فيها اسم الله كثيراً. ولينصرنّ الله من ينصره، من يقاتل من أجل أن يُعبد الله وحده في الأرض، إن الله لقوي عزيز. الذين إن ملّكناهم بعد قهر أعدائهم أقاموا الصلاة، وآتوا الزكاة، وأمروا بالمعروف، ونهوا عن المنكر من الشرك والمعاصي، هؤلاء الأحقّ بنصر الله، ولله مردّ كل أمر يوم القيامة، فليُراقب في السر والعلن.", "h": ["وعد الله الصادق بالدفاع عن المؤمنين الصادقين في إيمانهم.", "كره الله تعالى لأهل الكفر والخيانة.", "مشروعية القتال لإعلاء كلمة الله، بأن يُعبد وحده ولا يُضطهد أولياؤه.", "بيان سرّ الإذن بالجهاد، ونصرة الله لأوليائه الذين يقاتلون من أجله.", "بيان أسس الدولة التي ورّث الله أهلها البلاد وملّكهم فيها، وهي: إقام الصلاة، وإيتاء الزكاة، والأمر بالمعروف، والنهي عن المنكر."], "k": "«الذين إن مكّنّاهم في الأرض أقاموا الصلاة…»… ما مُكّنت فيه من بيت وعمل، هل أقمت فيه هذه الأربع؟"}, {"lbl": "الآيات ٤٢ – ٤٦", "q": "وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَثَمُودُ ﴿٤٢﴾ وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ لُوطٖ ﴿٤٣﴾ وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ ﴿٤٤﴾ فَكَأَيِّن مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةٞ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرٖ مُّعَطَّلَةٖ وَقَصۡرٖ مَّشِيدٍ ﴿٤٥﴾ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبٞ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ ﴿٤٦﴾", "w": [["وإن يكذّبوك", "إن يكذّبك قومك فقد كذّبت قبلهم قوم نوح، فلا تأسَ."], ["وأصحاب مدين", "قوم شعيب ﵇."], ["وكُذّب موسى", "كذّبه فرعون وآله الأقباط."], ["فأمليت للكافرين", "أمهلتهم فلم أعجّل العقوبة لهم."], ["ثم أخذتهم", "بالعذاب المستأصل لهم."], ["فكيف كان نكير", "كيف كان إنكاري عليهم تكذيبهم؟ أكان واقعاً موقعه؟ نعم، فالاستفهام للتقرير."], ["فهي خاوية على عروشها", "ساقطة على سقوفها."], ["وبئر معطّلة", "متروكة لا يُستخرج منها ماء لموت أهلها."], ["وقصر مشيد", "مرتفع مجصّص بالجص."], ["فإنها لا تعمى الأبصار", "الخلل ليس في أبصارهم، ولكن في قلوبهم، حيث أعماها الهوى وأفسدتها الشهوة والتقليد."]], "m": "ما زال السياق في دعوة قريش، فبعد الإذن بالقتال قال لرسوله مسلّياً: وإن يكذّبوك فيما جئت به فلا تحزن، فقد كذّبت قبلهم قوم نوح وعاد وثمود، وقوم إبراهيم وقوم لوط، وأصحاب مدين، وكُذّب موسى مع ما أوتي من الآيات، فأمهلتهم ومددت لهم، حتى إذا بلغوا غاية الكفر أخذتهم أخذ عزيز مقتدر، فكيف كان إنكاري عليهم؟ كان واقعاً موقعه. وكم من قرية عظيمة بأهلها ومالها وسلطانها أهلكناها وهي ظالمة بالشرك، فهي ساقطة على سقوفها، وكم من بئر عذبة كانت سقيا لهم فهي الآن معطّلة، وكم من قصر رفيع مجصّص مات أهله وتركوه. أفلم يسر المكذّبون في البلاد ليقفوا على آثار الهالكين، فتكون لهم قلوب حية يعقلون بها خطابنا، أو آذان يسمعون بها نداء النصح؟ فما لهم من عيون مبصرة بلا قلوب واعية لا ينفع، فإنها لا تعمى الأبصار، ولكن تعمى القلوب التي في الصدور.", "h": ["تكذيب الرسل والدعاة إلى الحق والخير سنة مطّردة في البشر، لها عواملها، من أبرزها التقليد، والمحافظة على المنافع المادية، وظلمات القلب الناشئة عن الشرك والمعاصي.", "مظاهر قدرة الله تعالى في إهلاك الأمم الظالمة بعد الإمهال لهم والإعذار.", "مشروعية طلب العبر وتصيّدها من آثار الهالكين.", "العبرة بالبصيرة القلبية لا بالبصر، فعلى العبد أن يحافظ على بصيرته أكثر من المحافظة على عينيه، بأن يتجنّب مدمّرات القلوب من الكذب والخرافات والكبر والعجب والحب والبغض في غير الله."], "k": "«ولكن تعمى القلوب التي في الصدور»… عيناي سليمتان؛ فكيف حال بصيرة قلبي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (239, 22, 47, 57, 'سورة الحج ٤٧ – ٥٧', '«وإن يوماً عند ربك كألف سنة مما تعدّون»، و«قل يا أيها الناس إنما أنا لكم نذير مبين»، و«الملك يومئذ لله يحكم بينهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 239) = $j$[{"lbl": "الآيات ٤٧ – ٥١", "q": "وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن يُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ يَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةٖ مِّمَّا تَعُدُّونَ ﴿٤٧﴾ وَكَأَيِّن مِّن قَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةٞ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ ﴿٤٨﴾ قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمۡ نَذِيرٞ مُّبِينٞ ﴿٤٩﴾ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٥٠﴾ وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿٥١﴾", "w": [["ويستعجلونك بالعذاب", "يطالبونك مستعجلين بما حذّرتهم منه من عذاب الله."], ["كألف سنة مما تعدّون", "من أيام الدنيا ذات الأربع والعشرين ساعة."], ["وكأيّن من قرية", "وكثير من القرى، أي العواصم والحواضر."], ["أمليت لها", "أمهلتها فمدّدت أيام حياتها ولم أستعجلها بالعذاب."], ["نذير مبين", "مخوّف عاقبة الكفر والظلم بيّن الإنذار."], ["لهم مغفرة ورزق كريم", "ستر لذنوبهم ورزق حسن في الجنة."], ["سعوا في آياتنا معاجزين", "عملوا بجدّ في إبعاد الناس عن الإيمان بآياتنا، ظانّين أنهم يعجزوننا."]], "m": "ما زال السياق في إرشاد الرسول ﷺ إلى الصبر: ويستعجلك المشركون، كالنضر بن الحارث ورفقائه، بالعذاب الذي خوّفتهم به، ولن يخلف الله وعده، وقد تم ذلك في بدر. وإن يوماً عند ربك كألف سنة مما تعدّون، فلذا لا يستعجل وهم يستعجلون، فإذا حدّد لعذابهم يوماً فمعناه ألف سنة، ونصف يوم خمسمائة سنة، فالله ينجز وعده في الوقت الذي حدّده لا يستخفّه استعجال المجرمين. وكثير من المدن الكبرى أمهلتها وهي ظالمة بالشرك، ثم أخذتها، وإليّ مصير كل شيء، فلا معنى للاستعجال، عُذّبوا في الدنيا أو لم يُعذّبوا فمصيرهم إلى الله. قل: يا أيها الناس إنما أنا لكم نذير مبين، لست بإله بيدي عذابكم أو إنعامكم، وإنما عبد مأمور أنذر العصاة وأبشّر الطائعين: فالذين آمنوا وعملوا الصالحات لهم مغفرة لذنوبهم ورزق كريم في الجنة، والذين سعوا جادّين في صرف الناس عن آيات الله، ظانّين أنهم يعجزونه، أولئك أصحاب الجحيم الملازمون لها.", "h": ["العجلة من طبع الإنسان، ولكن استعجال الله ورسوله بالعذاب حمق وطيش وضلال.", "ما عند الله في الملكوت الأعلى يختلف تماماً عما في هذا الملكوت السفلي.", "عاقبة الظلم وخيمة، وفي الخبر: الظلم يترك الديار بلاقع، أي خراباً خالية.", "بيان مهمة الرسل، وهي البلاغ مع الإنذار والتبشير ليس غير.", "بيان مصير المؤمنين والكافرين يوم القيامة."], "k": "«وإن يوماً عند ربك كألف سنة»… حين أستعجل الفرج، أتذكّر أن موازينه غير موازيني."}, {"lbl": "الآيات ٥٢ – ٥٧", "q": "وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٥٢﴾ لِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِينَ لَفِي شِقَاقِۭ بَعِيدٖ ﴿٥٣﴾ وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٥٤﴾ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةٖ مِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ ﴿٥٥﴾ ٱلۡمُلۡكُ يَوۡمَئِذٖ لِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡۚ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فِي جَنَّـٰتِ ٱلنَّعِيمِ ﴿٥٦﴾ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَـٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ﴿٥٧﴾", "w": [["من رسول ولا نبي", "الرسول: ذكر من بني آدم أوحي إليه بشرع وأُمر بإبلاغه، والنبي: مقرّر لشرع من قبله."], ["تمنّى", "قرأ."], ["في أمنيّته", "في قراءته."], ["ثم يُحكم الله آياته", "بعد إزالة ما ألقاه الشيطان يثبّت الله آياته."], ["فتنة للذين في قلوبهم مرض", "اختباراً للذين في قلوبهم مرض الشك والنفاق."], ["والقاسية قلوبهم", "هم المشركون."], ["فتخبت له قلوبهم", "تتطامن وتخشع له قلوبهم."], ["في مرية منه", "في شك وريب من القرآن."], ["عذاب يوم عقيم", "عذاب يوم بدر، إذ كان يوماً عقيماً لا خير فيه لهم."], ["في جنات النعيم", "جنات ذات نعيم لا يبلغ الوصف مداه."], ["فلهم عذاب مهين", "يُهان فيه صاحبه، فهو عذاب جثماني نفساني."]], "m": "ذكر تعالى تسلية ثانية للنبي ﷺ: وما أرسلنا من قبلك من رسول ولا نبي إلا إذا قرأ ألقى الشيطان في قراءته كلمات في مسامع الكافرين أوليائه، فيزيل الله ويبطل ما يلقي الشيطان، ثم يثبّت آياته فلا تقبل زيادة ولا نقصاناً، والله عليم حكيم، هذه سنّته في رسله، فلا تأس ولا تحزن. والحكمة: ليجعل ما يلقي الشيطان محنة للذين في قلوبهم مرض الشك والنفاق والقاسية قلوبهم من المشركين، يزدادون بها ضلالاً، وإن الظالمين لفي خلاف لله ورسوله بعيد. وليعلم الذين أوتوا العلم بالله وآياته أنه الحق من ربك فيؤمنوا به فتطمئن له قلوبهم وتخشع، وإن الله لهادي الذين آمنوا إلى صراط مستقيم بحمايتهم من الشيطان وإعانتهم على الطاعة. ولا يزال الذين كفروا في شك من القرآن حتى تأتيهم القيامة فجأة، أو يأتيهم عذاب يوم لا خير فيه لهم، وهو يوم بدر، وعندها علموا أنه الحق حيث لا ينفع العلم. الملك يومئذ لله وحده يحكم بينهم: فالذين آمنوا وعملوا الصالحات في جنات النعيم، والذين كفروا وكذّبوا بآياتنا فأولئك لهم عذاب مهين.", "h": ["بيان سنة الله في إلقاء الشيطان في قراءة الرسول أو النبي للفتنة.", "الفتنة يهلك فيها مرضى القلوب وقساتها، ويخرج منها المؤمنون أكثر يقيناً.", "بيان حكم الله تعالى بين عباده يوم القيامة بإكرام أهل الإيمان والتقوى وإهانة أهل الشرك والمعاصي.", "ظهور مصداق ما أخبر به تعالى عن مجرمي قريش."], "k": "«وإن الله لهادي الذين آمنوا إلى صراط مستقيم»… أطلب منه الهداية في كل فتنة تمر بي."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 239;
insert into public.tdb_cards(topic, i, body) select 239, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٧ – ٥١", "q": "وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن يُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ يَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةٖ مِّمَّا تَعُدُّونَ ﴿٤٧﴾ وَكَأَيِّن مِّن قَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةٞ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ ﴿٤٨﴾ قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمۡ نَذِيرٞ مُّبِينٞ ﴿٤٩﴾ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٥٠﴾ وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿٥١﴾", "w": [["ويستعجلونك بالعذاب", "يطالبونك مستعجلين بما حذّرتهم منه من عذاب الله."], ["كألف سنة مما تعدّون", "من أيام الدنيا ذات الأربع والعشرين ساعة."], ["وكأيّن من قرية", "وكثير من القرى، أي العواصم والحواضر."], ["أمليت لها", "أمهلتها فمدّدت أيام حياتها ولم أستعجلها بالعذاب."], ["نذير مبين", "مخوّف عاقبة الكفر والظلم بيّن الإنذار."], ["لهم مغفرة ورزق كريم", "ستر لذنوبهم ورزق حسن في الجنة."], ["سعوا في آياتنا معاجزين", "عملوا بجدّ في إبعاد الناس عن الإيمان بآياتنا، ظانّين أنهم يعجزوننا."]], "m": "ما زال السياق في إرشاد الرسول ﷺ إلى الصبر: ويستعجلك المشركون، كالنضر بن الحارث ورفقائه، بالعذاب الذي خوّفتهم به، ولن يخلف الله وعده، وقد تم ذلك في بدر. وإن يوماً عند ربك كألف سنة مما تعدّون، فلذا لا يستعجل وهم يستعجلون، فإذا حدّد لعذابهم يوماً فمعناه ألف سنة، ونصف يوم خمسمائة سنة، فالله ينجز وعده في الوقت الذي حدّده لا يستخفّه استعجال المجرمين. وكثير من المدن الكبرى أمهلتها وهي ظالمة بالشرك، ثم أخذتها، وإليّ مصير كل شيء، فلا معنى للاستعجال، عُذّبوا في الدنيا أو لم يُعذّبوا فمصيرهم إلى الله. قل: يا أيها الناس إنما أنا لكم نذير مبين، لست بإله بيدي عذابكم أو إنعامكم، وإنما عبد مأمور أنذر العصاة وأبشّر الطائعين: فالذين آمنوا وعملوا الصالحات لهم مغفرة لذنوبهم ورزق كريم في الجنة، والذين سعوا جادّين في صرف الناس عن آيات الله، ظانّين أنهم يعجزونه، أولئك أصحاب الجحيم الملازمون لها.", "h": ["العجلة من طبع الإنسان، ولكن استعجال الله ورسوله بالعذاب حمق وطيش وضلال.", "ما عند الله في الملكوت الأعلى يختلف تماماً عما في هذا الملكوت السفلي.", "عاقبة الظلم وخيمة، وفي الخبر: الظلم يترك الديار بلاقع، أي خراباً خالية.", "بيان مهمة الرسل، وهي البلاغ مع الإنذار والتبشير ليس غير.", "بيان مصير المؤمنين والكافرين يوم القيامة."], "k": "«وإن يوماً عند ربك كألف سنة»… حين أستعجل الفرج، أتذكّر أن موازينه غير موازيني."}, {"lbl": "الآيات ٥٢ – ٥٧", "q": "وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٥٢﴾ لِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِينَ لَفِي شِقَاقِۭ بَعِيدٖ ﴿٥٣﴾ وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٥٤﴾ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةٖ مِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ ﴿٥٥﴾ ٱلۡمُلۡكُ يَوۡمَئِذٖ لِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡۚ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فِي جَنَّـٰتِ ٱلنَّعِيمِ ﴿٥٦﴾ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَـٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ﴿٥٧﴾", "w": [["من رسول ولا نبي", "الرسول: ذكر من بني آدم أوحي إليه بشرع وأُمر بإبلاغه، والنبي: مقرّر لشرع من قبله."], ["تمنّى", "قرأ."], ["في أمنيّته", "في قراءته."], ["ثم يُحكم الله آياته", "بعد إزالة ما ألقاه الشيطان يثبّت الله آياته."], ["فتنة للذين في قلوبهم مرض", "اختباراً للذين في قلوبهم مرض الشك والنفاق."], ["والقاسية قلوبهم", "هم المشركون."], ["فتخبت له قلوبهم", "تتطامن وتخشع له قلوبهم."], ["في مرية منه", "في شك وريب من القرآن."], ["عذاب يوم عقيم", "عذاب يوم بدر، إذ كان يوماً عقيماً لا خير فيه لهم."], ["في جنات النعيم", "جنات ذات نعيم لا يبلغ الوصف مداه."], ["فلهم عذاب مهين", "يُهان فيه صاحبه، فهو عذاب جثماني نفساني."]], "m": "ذكر تعالى تسلية ثانية للنبي ﷺ: وما أرسلنا من قبلك من رسول ولا نبي إلا إذا قرأ ألقى الشيطان في قراءته كلمات في مسامع الكافرين أوليائه، فيزيل الله ويبطل ما يلقي الشيطان، ثم يثبّت آياته فلا تقبل زيادة ولا نقصاناً، والله عليم حكيم، هذه سنّته في رسله، فلا تأس ولا تحزن. والحكمة: ليجعل ما يلقي الشيطان محنة للذين في قلوبهم مرض الشك والنفاق والقاسية قلوبهم من المشركين، يزدادون بها ضلالاً، وإن الظالمين لفي خلاف لله ورسوله بعيد. وليعلم الذين أوتوا العلم بالله وآياته أنه الحق من ربك فيؤمنوا به فتطمئن له قلوبهم وتخشع، وإن الله لهادي الذين آمنوا إلى صراط مستقيم بحمايتهم من الشيطان وإعانتهم على الطاعة. ولا يزال الذين كفروا في شك من القرآن حتى تأتيهم القيامة فجأة، أو يأتيهم عذاب يوم لا خير فيه لهم، وهو يوم بدر، وعندها علموا أنه الحق حيث لا ينفع العلم. الملك يومئذ لله وحده يحكم بينهم: فالذين آمنوا وعملوا الصالحات في جنات النعيم، والذين كفروا وكذّبوا بآياتنا فأولئك لهم عذاب مهين.", "h": ["بيان سنة الله في إلقاء الشيطان في قراءة الرسول أو النبي للفتنة.", "الفتنة يهلك فيها مرضى القلوب وقساتها، ويخرج منها المؤمنون أكثر يقيناً.", "بيان حكم الله تعالى بين عباده يوم القيامة بإكرام أهل الإيمان والتقوى وإهانة أهل الشرك والمعاصي.", "ظهور مصداق ما أخبر به تعالى عن مجرمي قريش."], "k": "«وإن الله لهادي الذين آمنوا إلى صراط مستقيم»… أطلب منه الهداية في كل فتنة تمر بي."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (240, 22, 58, 66, 'سورة الحج ٥٨ – ٦٦', '«والذين هاجروا في سبيل الله ثم قُتلوا أو ماتوا ليرزقنّهم الله رزقاً حسناً»، و«ألم تر أن الله سخّر لكم ما في الأرض»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 240) = $j$[{"lbl": "الآيات ٥٨ – ٦٢", "q": "وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ ٱلرَّـٰزِقِينَ ﴿٥٨﴾ لَيُدۡخِلَنَّهُم مُّدۡخَلٗا يَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٞ ﴿٥٩﴾ ۞ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ ﴿٦٠﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ ﴿٦١﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ ﴿٦٢﴾", "w": [["والذين هاجروا", "هجروا ديار الكفر وذهبوا إلى دار الإيمان المدينة."], ["في سبيل الله", "لا لدنيا، ولكن ليعبدوا الله وينصروا دينه."], ["ليرزقنّهم رزقاً حسناً", "في الجنة، إذ أرواحهم في حواصل طير خضر ترعى فيها."], ["مدخلاً يرضونه", "الجنة يوم القيامة."], ["ذلك", "الأمر ذلك المذكور فاذكروه ولا تنسوه."], ["ثم بُغي عليه", "ظُلم بعد أن عاقب عدوّه بمثل ما ظُلم به."], ["يولج الليل في النهار", "يدخل جزءاً من الليل في النهار والعكس بحسب فصول السنة."], ["بأن الله هو الحق", "الإله الحق الذي تجب عبادته دون سواه."], ["من دونه", "من أصنام وأوثان وغيرها، هو الباطل بعينه."]], "m": "ما زال السياق في بيان حكم الله بين عباده، وذكر هنا ما حكم به لأهل الهجرة والجهاد: والذين خرجوا من ديارهم لطاعة الله ونصرة دينه ثم قتلهم المشركون أو ماتوا حتف أنوفهم ليرزقنّهم الله رزقاً حسناً في الجنة، إذ أرواحهم في حواصل طير خضر ترعى فيها وتأوي إلى قناديل معلّقة في العرش، وليدخلنّهم يوم القيامة الجنة يرضونها، وإن الله لهو خير الرازقين، وإن الله لعليم بأعمالهم، حليم يعفو عن زلّات عباده المؤمنين، إذ لا يخلو عبد من ذنب إلا من عصم الله من أنبيائه. الأمر ذلك، ومن أخذ من ظالمه قصاصاً بقدر ما أُخذ منه، ثم ظلمه المعاقَب بعد ذلك، لينصرنّه الله، إن الله لعفو غفور، وفيه ترغيب في العفو فإنه خير من المعاقبة. ذلك بأن القادر على إدخال الليل في النهار والنهار في الليل، السميع البصير، قادر على نصرة من بُغي عليه. ذلك بأن الله هو الإله الحق المستحق للعبادة، وأن ما يدعون من دونه من الأصنام هو الباطل، وأن الله هو العلي القاهر الكبير العظيم.", "h": ["بيان فضل الهجرة في سبيل الله، حتى إنها تعدل الجهاد في سبيل الله.", "جواز المعاقبة بشرط المماثلة، والعفو أولى من المعاقبة.", "بيان مظاهر الربوبية من العلم والقدرة الموجبة لعبادة الله تعالى وحده.", "إثبات صفات الله تعالى: العلم والحلم والمغفرة والسمع والبصر والعفو والعلوّ على الخلق والعظمة، الموجبة لعبادته وترك عبادة من سواه."], "k": "«إن الله لعفو غفور»… حين أقدر على أن أعاقب من ظلمني، أتذكّر أنه عفوّ ويحب العفو."}, {"lbl": "الآيات ٦٣ – ٦٦", "q": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ ﴿٦٣﴾ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ ﴿٦٤﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ ﴿٦٥﴾ وَهُوَ ٱلَّذِيٓ أَحۡيَاكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۗ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ ﴿٦٦﴾", "w": [["ألم تر", "ألم تعلم."], ["مخضرّة", "بالعشب والكلأ والنبات."], ["الغني الحميد", "الغني عن كل ما سواه، المحمود في أرضه وسمائه."], ["سخّر لكم ما في الأرض", "سهّل لكم تملّكه والتصرّف فيه والانتفاع به."], ["أحياكم", "أوجدكم أحياء بعدما كنتم عدماً."], ["لكفور", "كثير الكفر والجحود لربه ونعمه عليه."]], "m": "ما زال السياق في تقرير التوحيد بذكر مظاهر القدرة: ألم تعلم أن الله أنزل من السماء مطراً فتصبح الأرض مخضرّة بالعشب والزروع؟ إن الله لطيف بعباده خبير بما يصلحهم. له ما في السماوات وما في الأرض خلقاً وملكاً وتصرّفاً، وإنه لهو الغني عن خلقه، المحمود بجميل صنعه وعظيم إنعامه. ألم تعلم أن الله سخّر لكم ما في الأرض من الدواب والبهائم، والسفن تجري في البحر بإذنه، ويمسك السماء أن تقع على الأرض إلا بإذنه؟ إن الله بالناس لرءوف رحيم، رحمة متجلّية في حملهم وإرضاعهم وغذائهم ونومهم ويقظتهم، وفي عفوه عن زلّاتهم وعدم تعجيل العقوبة، وفي إرسال الرسل وإنزال الكتب. وهو الذي أوجدكم من العدم، ثم يميتكم عند انتهاء آجالكم، ثم يحييكم ليجزيكم، إن الإنسان لكثير الجحود يترك ذكر ربه وشكره ويذكر غيره ويشكر سواه، وهذه الآلاء توجب الإيمان به وتوحيده وتجعل عبادة غيره سخفاً وضلالاً.", "h": ["تقرير التوحيد بذكر مقتضياته من القدرة والنعمة.", "إثبات صفات الله تعالى: اللطيف الخبير الغني الحميد الرءوف الرحيم.", "بيان إنعام الله وإفضاله على خلقه.", "مظاهر قدرة الله تعالى في إمساك السماء أن تقع على الأرض، وفي الإحياء والإماتة."], "k": "«إن الله بالناس لرءوف رحيم»… أعدّ ثلاث رحمات مررت بها اليوم، وأشكره عليها."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 240;
