insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (241, 22, 67, 78, 'سورة الحج ٦٧ – ٧٨', '«لكل أمة جعلنا منسكاً»، ومثل الذباب: «ضعف الطالب والمطلوب»، و«يا أيها الذين آمنوا اركعوا واسجدوا… وجاهدوا في الله حق جهاده»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 241) = $j$[{"lbl": "الآيات ٦٧ – ٧٢", "q": "لِّكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ فِي ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدٗى مُّسۡتَقِيمٖ ﴿٦٧﴾ وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ ﴿٦٨﴾ ٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿٦٩﴾ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿٧٠﴾ وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَمَا لَيۡسَ لَهُم بِهِۦ عِلۡمٞۗ وَمَا لِلظَّـٰلِمِينَ مِن نَّصِيرٖ ﴿٧١﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ تَعۡرِفُ فِي وُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿٧٢﴾", "w": [["جعلنا منسكاً", "مكاناً يتعبّدون فيه بالذبائح أو غيرها."], ["فلا ينازعنّك", "لا ينبغي أن ينازعوك."], ["هدى مستقيم", "دين مستقيم هو الإسلام دين الله الحق."], ["في كتاب", "هو اللوح المحفوظ."], ["ما لم ينزّل به سلطاناً", "حجة وبرهاناً."], ["المنكر", "الإنكار الدال عليه عبوس الوجه وتقطيبه."], ["يسطون", "يبطشون."], ["بشر من ذلكم", "هو النار."]], "m": "ما زال السياق في هداية الرسول والمؤمنين ودعوة المشركين: لكل أمة مضت أو حاضرة جعلنا مكاناً يتنسّكون فيه، فلا تقبل منهم منازعة في أمر واضح، وذلك أن المشركين انتقدوا ذبائح الهدي والضحايا واعترضوا على تحريم الميتة وقالوا: كيف تأكلون ما تذبحون ولا تأكلون ما ذبح الله؟ فأعرض عن الجدل الفارغ وادع إلى توحيد ربك، إنك لعلى طريق مستقيم هو الإسلام. وإن جادلوك فاتركهم فإنهم جهلة، وقل: الله أعلم بما تعملون وسيجزيكم، الله يحكم بينكم يوم القيامة فيما كنتم فيه تختلفون. ألم تعلم أن الله يعلم ما في السماء والأرض من جليل ودقيق؟ إن ذلك مكتوب في اللوح المحفوظ، وكتبه وحفظه على الله يسير. ويعبد المشركون من دون الله أصناماً لم ينزّل بها حجة ولا برهاناً، وما ليس لهم به علم، وما للظالمين من نصير. وإذا تُليت عليهم آياتنا البيّنات تعرف في وجوههم الإنكار، يكادون يبطشون بالذين يتلونها عليهم لهدايتهم. قل: أفأنبّئكم بشرّ من ذلك الذي تكرهون؟ النار وعدها الله الذين كفروا، وبئس المصير.", "h": ["تقرير حقيقة، وهي أن كل أمة من الأمم بعث الله فيها رسولاً وشرع لها عبادات تعبده بها.", "استحسان ترك الجدال في البدهيات والإعراض عما فيها.", "تقرير علم الله تعالى بكل خفي وجلي وصغير وكبير في السماوات والأرض.", "تقرير عقيدة القضاء والقدر بتقرير الكتاب الحاوي لذلك، وهو اللوح المحفوظ.", "بيان شدة بغض المشركين للموحّدين إذا دعوهم إلى التوحيد وذكّروهم بالآيات.", "مشروعية إغاظة الظالم بما يغيظه من القول الحق."], "k": "«وإن جادلوك فقل الله أعلم بما تعملون»… جدال لا ثمرة منه، هل أملك شجاعة تركه؟"}, {"lbl": "الآيات ٧٣ – ٧٦", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٞ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابٗا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ ﴿٧٣﴾ مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ ﴿٧٤﴾ ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَـٰٓئِكَةِ رُسُلٗا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ ﴿٧٥﴾ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٧٦﴾", "w": [["ضُرب مثل", "جُعل مثل، هو ما تضمّنه قوله: «إن الذين تدعون…»."], ["لن يخلقوا ذباباً", "لن يستطيعوا خلق ذبابة، وهي من أحقر الحيوانات."], ["ولو اجتمعوا له", "على خلقه، فإنهم لا يقدرون، فكيف إذا لم يجتمعوا؟"], ["لا يستنقذوه منه", "لا يستردّوه منه لعجزهم."], ["ضعف الطالب والمطلوب", "العابد والمعبود."], ["ما قدروا الله حق قدره", "ما عظّم المشركون الله حق عظمته."], ["يصطفي من الملائكة رسلاً", "يجتبي ويختار كجبريل."], ["ومن الناس", "كمحمد ﷺ."]], "m": "ما زال السياق في الدعوة إلى التوحيد: يا أيها المشركون، ضُرب لآلهتكم في حقارتها وضعفها مثل فاستمعوا له: إن الذين تدعون من دون الله من أوثان لن يخلقوا ذباباً، وهو من أحقر الحيوان، ولو اجتمعوا متعاونين على خلقه، وإن يسلبهم الذباب شيئاً من الطيب الذي يضمّخونها به لا يستطيعون استرداده منه، فما أضعفها وما أحقرها إذا كان الذباب أقدر منها! ضعف العابد والمعبود. ما عظّموا الله حق عظمته إذ سوّوا به أحقر مخلوقاته، إن الله لقوي عزيز لا يُمانع فيما يريد. ولما قالوا: أأنزل عليه الذكر من بيننا؟ أخبر تعالى أنه يختار من الملائكة رسلاً كجبريل، ومن الناس كنوح وإبراهيم وموسى وعيسى ومحمد ﷺ، إن الله سميع بصير، يعلم ما بين أيديهم وما خلفهم، فحقّ له أن يختار لرسالته من يشاء، وإلى الله ترجع الأمور كلها بدءاً ونهاية.", "h": ["استحسان ضرب الأمثال لتقريب المعاني إلى الأذهان.", "التنديد بالشرك وبطلانه، وبيان سفه المشركين.", "ما قدر الله حق قدره من سوّى به أحقر مخلوقاته، وجعل له من عباده جزءاً وشبهاً.", "إثبات الرسالات للملائكة وللناس معاً.", "ذكر صفات الجلال والكمال لله تعالى المقتضية لربوبيته والموجبة لألوهيته، وهي القوة والعزة، والسمع والبصر، والعلم بكل شيء."], "k": "«ما قدروا الله حق قدره»… هل أعظّمه في قلبي كما ينبغي، أم أقدّم عليه أشياء صغيرة؟"}, {"lbl": "الآيتان ٧٧ – ٧٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩ ﴿٧٧﴾ وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ ﴿٧٨﴾", "w": [["واعبدوا ربكم", "أطيعوه في أمره ونهيه في غاية التعظيم وغاية الذل."], ["وافعلوا الخير", "كل ما ندبكم الله لفعله ورغّبكم فيه من صالح الأقوال والأعمال."], ["لعلكم تفلحون", "كي تفوزوا بالنجاة من النار ودخول الجنة."], ["حق جهاده", "الجهاد الحق الذي شرعه الله، وهو جهاد الكفار والشيطان والنفس والهوى."], ["اجتباكم", "اختاركم لحمل دعوة الله إلى الناس كافة."], ["من حرج", "من ضيق وتكليف لا يُطاق."], ["ملّة أبيكم", "الزموا ملة أبيكم إبراهيم، وهي عبادة الله وحده."], ["وفي هذا", "القرآن."], ["واعتصموا بالله", "تمسّكوا بدينه وثقوا في نصرته وحسن مثوبته."], ["ونعم النصير", "هو تعالى نعم الناصر لكم."]], "m": "بعد تقرير العقيدة نادى المسلمين: يا من آمنتم بالله رباً وبمحمد رسولاً وبالإسلام ديناً، اركعوا واسجدوا بإقامة الصلاة، واعبدوا ربكم معظّمين له غاية التعظيم، وافعلوا الخير من أنواع البر، لعلكم تتأهّلون للفلاح بالجنة بعد النجاة من النار. وجاهدوا في الله حق جهاده باستفراغ الجهد نفساً ومالاً ودعوة حتى لا تكون فتنة ويكون الدين كله لله. هو اختاركم، وما جعل عليكم في الدين من ضيق، بل وسّع فجعل التوبة لكل ذنب، والكفارة لبعض الذنوب، ورخّص للمسافر والمريض في القصر والفطر، ولمن لم يجد الماء في التيمم، الزموا ملة أبيكم إبراهيم، هو سمّاكم المسلمين في الكتب السابقة وفي القرآن، ليكون الرسول شهيداً عليكم يوم القيامة بأنه بلّغكم، وتكونوا شهداء على الناس بأن الرسل بلّغوا أممهم. فاشكروا هذا الإنعام: فأقيموا الصلاة، وآتوا الزكاة، وتمسّكوا بشرع الله عقيدة وعبادة وخلقاً وحكماً، هو مولاكم، فنعم المولى ونعم النصير ما دمتم أولياءه.", "h": ["فضيلة الصلاة وشرف العبادة وفعل الخير.", "مشروعية السجود عند تلاوة هذه الآية: «وافعلوا الخير لعلكم تفلحون».", "فضل الجهاد في سبيل الله، وهو جهاد الكفار، وأن لا تأخذ المؤمن في الله لومة لائم.", "فضيلة هذه الأمة المسلمة، حيث أُعطيت ثلاثاً لم يُعطها إلا نبي: كان يقال للنبي: اذهب فليس عليك حرج، فقال لهذه الأمة: «وما جعل عليكم في الدين من حرج»، وكان يقال للنبي: أنت شهيد على قومك، فقال: «لتكونوا شهداء على الناس»، وكان يقال للنبي: سل تُعطه، فقال لهذه الأمة: «ادعوني أستجب لكم».", "فرضية الصلاة والزكاة والتمسك بالشريعة."], "k": "«وما جعل عليكم في الدين من حرج»… أي رخصة أو سعة في ديني، هل أشكر الله عليها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 241;
insert into public.tdb_cards(topic, i, body) select 241, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٧ – ٧٢", "q": "لِّكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ فِي ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدٗى مُّسۡتَقِيمٖ ﴿٦٧﴾ وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ ﴿٦٨﴾ ٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿٦٩﴾ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ ﴿٧٠﴾ وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَمَا لَيۡسَ لَهُم بِهِۦ عِلۡمٞۗ وَمَا لِلظَّـٰلِمِينَ مِن نَّصِيرٖ ﴿٧١﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ تَعۡرِفُ فِي وُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿٧٢﴾", "w": [["جعلنا منسكاً", "مكاناً يتعبّدون فيه بالذبائح أو غيرها."], ["فلا ينازعنّك", "لا ينبغي أن ينازعوك."], ["هدى مستقيم", "دين مستقيم هو الإسلام دين الله الحق."], ["في كتاب", "هو اللوح المحفوظ."], ["ما لم ينزّل به سلطاناً", "حجة وبرهاناً."], ["المنكر", "الإنكار الدال عليه عبوس الوجه وتقطيبه."], ["يسطون", "يبطشون."], ["بشر من ذلكم", "هو النار."]], "m": "ما زال السياق في هداية الرسول والمؤمنين ودعوة المشركين: لكل أمة مضت أو حاضرة جعلنا مكاناً يتنسّكون فيه، فلا تقبل منهم منازعة في أمر واضح، وذلك أن المشركين انتقدوا ذبائح الهدي والضحايا واعترضوا على تحريم الميتة وقالوا: كيف تأكلون ما تذبحون ولا تأكلون ما ذبح الله؟ فأعرض عن الجدل الفارغ وادع إلى توحيد ربك، إنك لعلى طريق مستقيم هو الإسلام. وإن جادلوك فاتركهم فإنهم جهلة، وقل: الله أعلم بما تعملون وسيجزيكم، الله يحكم بينكم يوم القيامة فيما كنتم فيه تختلفون. ألم تعلم أن الله يعلم ما في السماء والأرض من جليل ودقيق؟ إن ذلك مكتوب في اللوح المحفوظ، وكتبه وحفظه على الله يسير. ويعبد المشركون من دون الله أصناماً لم ينزّل بها حجة ولا برهاناً، وما ليس لهم به علم، وما للظالمين من نصير. وإذا تُليت عليهم آياتنا البيّنات تعرف في وجوههم الإنكار، يكادون يبطشون بالذين يتلونها عليهم لهدايتهم. قل: أفأنبّئكم بشرّ من ذلك الذي تكرهون؟ النار وعدها الله الذين كفروا، وبئس المصير.", "h": ["تقرير حقيقة، وهي أن كل أمة من الأمم بعث الله فيها رسولاً وشرع لها عبادات تعبده بها.", "استحسان ترك الجدال في البدهيات والإعراض عما فيها.", "تقرير علم الله تعالى بكل خفي وجلي وصغير وكبير في السماوات والأرض.", "تقرير عقيدة القضاء والقدر بتقرير الكتاب الحاوي لذلك، وهو اللوح المحفوظ.", "بيان شدة بغض المشركين للموحّدين إذا دعوهم إلى التوحيد وذكّروهم بالآيات.", "مشروعية إغاظة الظالم بما يغيظه من القول الحق."], "k": "«وإن جادلوك فقل الله أعلم بما تعملون»… جدال لا ثمرة منه، هل أملك شجاعة تركه؟"}, {"lbl": "الآيات ٧٣ – ٧٦", "q": "يَـٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٞ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابٗا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ ﴿٧٣﴾ مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ ﴿٧٤﴾ ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَـٰٓئِكَةِ رُسُلٗا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ ﴿٧٥﴾ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٧٦﴾", "w": [["ضُرب مثل", "جُعل مثل، هو ما تضمّنه قوله: «إن الذين تدعون…»."], ["لن يخلقوا ذباباً", "لن يستطيعوا خلق ذبابة، وهي من أحقر الحيوانات."], ["ولو اجتمعوا له", "على خلقه، فإنهم لا يقدرون، فكيف إذا لم يجتمعوا؟"], ["لا يستنقذوه منه", "لا يستردّوه منه لعجزهم."], ["ضعف الطالب والمطلوب", "العابد والمعبود."], ["ما قدروا الله حق قدره", "ما عظّم المشركون الله حق عظمته."], ["يصطفي من الملائكة رسلاً", "يجتبي ويختار كجبريل."], ["ومن الناس", "كمحمد ﷺ."]], "m": "ما زال السياق في الدعوة إلى التوحيد: يا أيها المشركون، ضُرب لآلهتكم في حقارتها وضعفها مثل فاستمعوا له: إن الذين تدعون من دون الله من أوثان لن يخلقوا ذباباً، وهو من أحقر الحيوان، ولو اجتمعوا متعاونين على خلقه، وإن يسلبهم الذباب شيئاً من الطيب الذي يضمّخونها به لا يستطيعون استرداده منه، فما أضعفها وما أحقرها إذا كان الذباب أقدر منها! ضعف العابد والمعبود. ما عظّموا الله حق عظمته إذ سوّوا به أحقر مخلوقاته، إن الله لقوي عزيز لا يُمانع فيما يريد. ولما قالوا: أأنزل عليه الذكر من بيننا؟ أخبر تعالى أنه يختار من الملائكة رسلاً كجبريل، ومن الناس كنوح وإبراهيم وموسى وعيسى ومحمد ﷺ، إن الله سميع بصير، يعلم ما بين أيديهم وما خلفهم، فحقّ له أن يختار لرسالته من يشاء، وإلى الله ترجع الأمور كلها بدءاً ونهاية.", "h": ["استحسان ضرب الأمثال لتقريب المعاني إلى الأذهان.", "التنديد بالشرك وبطلانه، وبيان سفه المشركين.", "ما قدر الله حق قدره من سوّى به أحقر مخلوقاته، وجعل له من عباده جزءاً وشبهاً.", "إثبات الرسالات للملائكة وللناس معاً.", "ذكر صفات الجلال والكمال لله تعالى المقتضية لربوبيته والموجبة لألوهيته، وهي القوة والعزة، والسمع والبصر، والعلم بكل شيء."], "k": "«ما قدروا الله حق قدره»… هل أعظّمه في قلبي كما ينبغي، أم أقدّم عليه أشياء صغيرة؟"}, {"lbl": "الآيتان ٧٧ – ٧٨", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩ ﴿٧٧﴾ وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ ﴿٧٨﴾", "w": [["واعبدوا ربكم", "أطيعوه في أمره ونهيه في غاية التعظيم وغاية الذل."], ["وافعلوا الخير", "كل ما ندبكم الله لفعله ورغّبكم فيه من صالح الأقوال والأعمال."], ["لعلكم تفلحون", "كي تفوزوا بالنجاة من النار ودخول الجنة."], ["حق جهاده", "الجهاد الحق الذي شرعه الله، وهو جهاد الكفار والشيطان والنفس والهوى."], ["اجتباكم", "اختاركم لحمل دعوة الله إلى الناس كافة."], ["من حرج", "من ضيق وتكليف لا يُطاق."], ["ملّة أبيكم", "الزموا ملة أبيكم إبراهيم، وهي عبادة الله وحده."], ["وفي هذا", "القرآن."], ["واعتصموا بالله", "تمسّكوا بدينه وثقوا في نصرته وحسن مثوبته."], ["ونعم النصير", "هو تعالى نعم الناصر لكم."]], "m": "بعد تقرير العقيدة نادى المسلمين: يا من آمنتم بالله رباً وبمحمد رسولاً وبالإسلام ديناً، اركعوا واسجدوا بإقامة الصلاة، واعبدوا ربكم معظّمين له غاية التعظيم، وافعلوا الخير من أنواع البر، لعلكم تتأهّلون للفلاح بالجنة بعد النجاة من النار. وجاهدوا في الله حق جهاده باستفراغ الجهد نفساً ومالاً ودعوة حتى لا تكون فتنة ويكون الدين كله لله. هو اختاركم، وما جعل عليكم في الدين من ضيق، بل وسّع فجعل التوبة لكل ذنب، والكفارة لبعض الذنوب، ورخّص للمسافر والمريض في القصر والفطر، ولمن لم يجد الماء في التيمم، الزموا ملة أبيكم إبراهيم، هو سمّاكم المسلمين في الكتب السابقة وفي القرآن، ليكون الرسول شهيداً عليكم يوم القيامة بأنه بلّغكم، وتكونوا شهداء على الناس بأن الرسل بلّغوا أممهم. فاشكروا هذا الإنعام: فأقيموا الصلاة، وآتوا الزكاة، وتمسّكوا بشرع الله عقيدة وعبادة وخلقاً وحكماً، هو مولاكم، فنعم المولى ونعم النصير ما دمتم أولياءه.", "h": ["فضيلة الصلاة وشرف العبادة وفعل الخير.", "مشروعية السجود عند تلاوة هذه الآية: «وافعلوا الخير لعلكم تفلحون».", "فضل الجهاد في سبيل الله، وهو جهاد الكفار، وأن لا تأخذ المؤمن في الله لومة لائم.", "فضيلة هذه الأمة المسلمة، حيث أُعطيت ثلاثاً لم يُعطها إلا نبي: كان يقال للنبي: اذهب فليس عليك حرج، فقال لهذه الأمة: «وما جعل عليكم في الدين من حرج»، وكان يقال للنبي: أنت شهيد على قومك، فقال: «لتكونوا شهداء على الناس»، وكان يقال للنبي: سل تُعطه، فقال لهذه الأمة: «ادعوني أستجب لكم».", "فرضية الصلاة والزكاة والتمسك بالشريعة."], "k": "«وما جعل عليكم في الدين من حرج»… أي رخصة أو سعة في ديني، هل أشكر الله عليها؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;